    ["01-4"] = {steps={[1]={npc="Eric Brighthammer", tgt="Eric Brighthammer", desc="Töte nach dem Tunnel auf dem Weg zum Gasthaus jeden Eber."}, [2]={npc="Eric Brighthammer", tgt="Eric Brighthammer"}, [3]={hint="Setzt Euch an Erics einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt."}, [4]={npc="Eric Brighthammer", tgt="Eric Brighthammer"}, [5]={npc="Eric Brighthammer", tgt="Eric Brighthammer", text="Grundlagen des Zeltens (beliebiger Beruf)", tag="Optional"}, [6]={npc="Eric Brighthammer", tgt="Eric Brighthammer"}, [7]={npc="Senir Whitebeard", tgt="Senir Whitebeard"}, [8]={npc="Senir Whitebeard", tgt="Senir Whitebeard"}, [9]={npc="Tannok Frosthammer", tgt="Tannok Frosthammer"}, [10]={text="Binde deinen Ruhestein im Gasthaus in Kharanos (47.40, 52.50)."}, [11]={npc="Maxan Anvol", tgt="Maxan Anvol"}, [12]={npc="Ragnar Donnerbräu", tgt="Ragnar Donnerbräu"}, [13]={npc="Tharek Blackstone", tgt="Tharek Blackstone"}, [14]={npc="Tognus Flintfire", tgt="Tognus Flintfire"}, [15]={npc="Pilot Bellowfiz", tgt="Pilot Bellowfiz"}, [16]={npc="Pilot Stonegear", tgt="Pilot Stonegear"}, [17]={npc="Loslor Rudge", tgt="Loslor Rudge"}, [18]={npc="Beldin Steelgrill", tgt="Beldin Steelgrill"}, [19]={hint="Bringt Rumbleshots Munition zu Hegnar Rumbleshot in Dun Morogh.", desc="Schließ zuerst „Vorräte für Jetsteam\" ab. Töte unterwegs alle Bären und Eber."}, [20]={npc="Gebirgsjägerin Gretchen", tgt="Gebirgsjägerin Gretchen"}, [21]={npc="Gebirgsjägerin Gretchen", tgt="Gebirgsjägerin Gretchen"}, [22]={hint="Findet Gebirgsjäger Cornelius im Graufelsbau für Gebirgsjägerin Gretchen."}, [23]={hint="Sammelt Flintfires Lieferungen (8 Stück) im Graufelsbau für Tongus Flintfire in Kharanos."}, [24]={hint="Sammelt 8 Wendigomähnen und bringt sie Pilot Stonegear."}, [25]={npc="Gebirgsjägerin Gretchen", tgt="Gebirgsjägerin Gretchen"}, [26]={npc="Gebirgsjägerin Gretchen", tgt="Gebirgsjägerin Gretchen"}, [27]={hint="Sammelt 4 Brocken Eberfleisch und 2 dicke Bärenfelle und lief