    ["01-7"] = {tips={{k="交通", text="Startgebiet der Skyborne. Allianz und Horde teilen sich die Startquests der Insel und trennen sich erst beim Verlassen der Insel nach Fraktion.", s={{"Startgebiet der Skyborne. Allianz und Horde teilen sich die Startquests der Insel und trennen sich erst beim Verlassen der Insel nach Fraktion.", {race={"Skyborne"}}}}}}, grind={[1]={mob="Zirrusfliegensoldat", note="Der Zirrusfliegenschwarm im Osten des Thendalhains; es sind viele, und sie liegen auf dem Weg zur Königin."}, [2]={mob="Magerer Ursera", note="Der Wald westlich des Wachturms; normale Gegner, die du einzeln ziehen kannst."}}, steps={[1]={npc="Dalia die Sammlerin", tgt="Ailee Farheart"}, [2]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [3]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [4]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [5]={hint="Tötet 8 junge Vuldren im Thendalhain."}, [6]={hint="Tötet 8 lästige Zirrusfliegen im Thendalhain."}, [7]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [8]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [9]={npc="Halaan Hawk-Eye", tgt="Halaan Hawk-Eye"}, [10]={npc="Halaan Hawk-Eye", tgt="Halaan Hawk-Eye"}, [11]={npc="Myriaal Mistwake", tgt="Myriaal Mistwake"}, [12]={hint="Springt von der Spitze des Wachturms im Thendalhain und verlangsamt Euren Fall mit Eurer Fähigkeit \"Luftwandeln\".", desc="Setz beim Sprung in Richtung Zirrusfliegenkönigin dein Skyborne-Volksfähigkeit ein."}, [13]={desc="Hast du noch nicht Stufe 3, farme im Thendalhain unterhalb des Turms Zirrusfliegensoldaten und Magere Ursera bis Stufe 3."}, [14]={hint="Vernichtet die Zirrusfliegenkönigin im Thendalhain."}, [15]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [16]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [17]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [18]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [19]={npc="Rorian der Tagsucher", tgt="Rorian der Tagsucher"}, [20]={npc="Ailee Farheart"