    ["02-15"] = {steps={[1]={to="Lakeshire", toA="{a:69}"}, [2]={npc="Marshal Marris", tgt="Marshal Marris"}, [3]={npc="Marshal Marris", tgt="Marshal Marris"}, [4]={npc="Großknecht Oslow", tgt="Großknecht Oslow"}, [5]={npc="Verner Osgood", tgt="Verner Osgood"}, [6]={npc="Verner Osgood", tgt="Verner Osgood"}, [7]={npc="Verner Osgood", tgt="Verner Osgood"}, [8]={npc="Wache Berton", tgt="Wache Berton", tag="Gruppe empfohlen, Optional"}, [9]={npc="Shawn", tgt="Shawn"}, [10]={hint="Sucht Hilarys Halskette und bringt sie Hilary in Seenhain zurück."}, [11]={npc="Wache Parker", tgt="Wache Parker"}, [12]={npc="Wache Parker", tgt="Wache Parker"}, [13]={hint="Sammelt 5 Stachelhalsbänder von Hauer der Rotkammgnolle für Deputy Feldon in der Nähe von Seenhain.", desc="Töte bei etwa 10.8, 63.7 zusätzliche Bastarde der Rotkammgnolle."}, [14]={hint="Tötet 10 Bastarde der Rotkammgnolle und 6 Wilderer der Rotkammgnolle und meldet Euch anschließend wieder bei Deputy Feldon in Seenhain."}, [15]={hint="Sammelt 6 Welpenbauchschuppen von schwarzen Großdrachenwelpen ein und bringt sie ins Rotkammgebirge zu Verner Osgood."}, [16]={hint="Bringt 10 gefleckte Sonnenfische nach Seenhain zu Dockmeister Baren."}, [17]={hint="Bringt 8 Murlocflossen nach Seenhain zu Dockmeister Baren."}, [18]={hint="Bringt 8 gestohlene Waffen und 10 Blackrockvorräte nach Seenhain zu Marshal Marris."}, [19]={hint="Bringt 10 kampferprobte Äxte nach Seenhain zu Marshal Marris."}, [20]={hint="Großknecht Oslow aus Seenhain möchte, dass Ihr seinen Werkzeugkasten vom Grunde des Immerruhsees heraufholt."}, [21]={npc="Verner Osgood", tgt="Verner Osgood"}, [22]={npc="Marshal Marris", tgt="Marshal Marris"}, [23]={npc="Marshal Marris", tgt="Marshal Marris"}, [24]={npc="Marshal Marris", tgt="Marshal Marris", tag="Optional"}, [25]={npc="Marshal Marris", tgt="Marshal Marris", tag="Optional"}, [26]={npc="Großknecht Oslow", tgt="Großknecht Oslow"}, [27]={npc="Großknecht Oslow", tgt="Großknecht Oslow"}, [28]={npc="Magistrat Solomon",