    ["02-16"] = {steps={[1]={npc="Thundris Windwirker", tgt="Thundris Windwirker"}, [2]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [3]={npc="Gershala Nightwhisper", tgt="Gershala Nightwhisper"}, [4]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [5]={text="Flieg von Auberdine nach Rut'theran (ist es nicht auf deiner Flugkarte, nimm das Schiff) und geh durch das Portal im Dorf nach Darnassus."}, [6]={npc="Mathiel", tgt="Mathiel"}, [7]={npc="Mathiel", tgt="Mathiel"}, [8]={hint="Bringt 20 sonnenverbrannte Schalen zu Mathiel in Darnassus."}, [9]={npc="Mathiel", tgt="Mathiel"}, [10]={npc="Mathiel", tgt="Mathiel"}, [11]={npc="Mathiel", tgt="Mathiel"}, [12]={text="Geh durch das Portal zurück nach Rut'theran und flieg nach Auberdine, um wieder auf die Route zu kommen."}, [13]={text="Flieg von Auberdine nach Rut'theran (ist es nicht auf deiner Flugkarte, nimm das Schiff) und geh durch das Portal im Dorf nach Darnassus."}, [14]={npc="Priesterin Alathea", tgt="Priesterin Alathea", desc="Lerne Elunes Anmut."}, [15]={npc="Priesterin Alathea", tgt="Priesterin Alathea", desc="Lerne Elunes Anmut."}, [16]={text="Geh durch das Portal zurück nach Rut'theran und flieg nach Auberdine, um wieder auf die Route zu kommen."}, [17]={text="Flieg von Auberdine nach Rut'theran (ist es nicht auf deiner Flugkarte, nimm das Schiff) und geh durch das Portal im Dorf nach Darnassus."}, [18]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}, [19]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [20]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [21]={npc="Avatar von Saeyleenan", tgt="Avatar von Saeyleenan", desc="Der Avatar von Saeyleenan ist im Süden von Moonglade."}, [22]={npc="Avatar von Saeyleenan", tgt="Avatar von Saeyleenan"}, [23]={hint="Beschafft das Relikt des Reißzahns, das Relikt der Klaue und das Relikt des stillen Schattens aus dem Grabhügel des Stormrage und bringt die Relikte zum Avatar von Saeyleenan zurück.", desc="Benutze am Eingang