    ["03-40"] = {grind={[1]={mob="Schurke der Wüstenläufer", note="Das Lager der Wüstenläufer südöstlich von Gadgetzan; dieselben Gegner wie für „Wüstenläufergerechtigkeit\"."}, [2]={mob="Schattenmagier der Wüstenläufer", note="Dasselbe Lager; Zauberwirker, zieh sie einzeln."}}, steps={[1]={to="Gadgetzan", toA="{a:976}"}, [2]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [3]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [4]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [5]={npc="Pozzik", tgt="Pozzik"}, [6]={npc="Zamek", tgt="Zamek"}, [7]={npc="Zamek", tgt="Zamek"}, [8]={npc="Rizzles Pläne", npcObj=true, desc="Warte, bis Rizzle Brassbolts das Gebäude verlässt, bevor du loslegst."}, [9]={npc="Rizzles Pläne", npcObj=true}, [10]={npc="Pozzik", tgt="Pozzik"}, [11]={npc="GESUCHT: Kalif Skorpidstich", npcObj=true}, [12]={npc="GESUCHT: Kalif Skorpidstich", npcObj=true}, [13]={npc="Leitungshahnmaschinist Luglunket", tgt="Leitungshahnmaschinist Luglunket"}, [14]={npc="Chefingenieur Bilgewhizzle", tgt="Chefingenieur Bilgewhizzle"}, [15]={npc="Jhordy Lapforge", tgt="Jhordy Lapforge"}, [16]={hint="Jhordy Lapforge möchte, dass Ihr zu ihm zurückkehrt, nachdem Ihr die Kiste mit radioaktiven Abfällen in der Wüste von Tanaris entsorgt habt, in sicherer Entfernung von Gadgetzan und anderem Müll.", desc="Such dir auf dem Weg zum Lager der Wüstenläufer eine freie Stelle und benutze dort den Questgegenstand."}, [17]={hint="Erledigt 10 Banditen und Diebe der Wüstenläufer östlich von Gadgetzan und meldet Euch dann wieder bei Chefingenieur Bilgewhizzle."}, [18]={desc="Hast du noch nicht Stufe 44, bleib im Lager der Wüstenläufer und farme Schurken der Wüstenläufer und Schattenmagier der Wüstenläufer bis Stufe 44."}, [19]={npc="Eingebildete Modeschöpferin", tgt="Eingebildete Modeschöpferin"}, [20]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [21]={npc="Stoley", tgt="Stoley"}, [22]={npc="Stoley", tgt="Stoley"}, [23]={npc="Sicherheitchef Bilgewhizzle", tgt="Sicherheitchef Bilgewhizzle", de