    ["05-d10"] = {name="Zul'Farrak", entrance="Tanaris 38.70, 20.10", pickup="Nimm die Quests für den Dungeon schon bei Schlingendorntal (3. Besuch) an, dann musst du vorher nicht extra zurück.", pickupS={{"Nimm die Quests für den Dungeon schon bei Schlingendorntal (3"}, {"Besuch) an, dann musst du vorher nicht extra zurück"}}, steps={[1]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts", tag="Optional, Gruppe empfohlen"}, [2]={npc="Tabetha", tgt="Tabetha", tag="Optional, Gruppe empfohlen"}, [3]={npc="Krazek", tgt="Krazek"}, [4]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon-Vorquest"}, [5]={hint="Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück.", tag="Dungeon-Vorquest", desc="Tötet Talschreier an der Küste der Insel des Schreckens in Feralas. Benutzt Yeh'kinyas Dornbusch auf jedem Kadaver und sprecht mit dem erscheinenden Geist, bis das Questlog drei Geister zählt."}, [6]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon-Vorquest"}, [7]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Optional"}, [8]={npc="Tran'rek", tgt="Tran'rek", tag="Optional"}, [9]={npc="Chefingenieur Bilgewhizzle", tgt="Chefingenieur Bilgewhizzle", tag="Optional"}, [10]={npc="Trenton Lighthammer", tgt="Trenton Lighthammer", tag="Optional"}, [11]={text="Eingang: Zul'Farrak"}, [12]={hint="Bringt die Tiara der Tiefen zu Tabetha in den Marschen von Dustwallow.", tag="Optional, Gruppe empfohlen", spot="Besiegt Hydromantin Velratha am Becken und nehmt ihre Tiara an euch."}, [13]={hint="Bringt Wizzle Brassbolts in der schimmernden Ebene Gahz'rillas energiegeladene Schuppe.", tag="Optional, Gruppe empfohlen", spot="Ein Gruppenmitglied braucht den Schlaghammer von Zul'Farrak, um Gahz'rilla am Becken mit dem Gong zu beschwören. Ist er schon da, besiegt ihn und nehmt die Schuppe."}, [14]={hint="Bringt Thadius Grimshade in den verwüsteten Landen Nekrums Medaillon.", tag="Optional, Gruppe empfohlen", spot="Besiegt Nekrum auf der Pyramidentreppe und plündert sein 