    ["03-41"] = {steps={[1]={to="Thalanaar", toA="{a:489}"}, [2]={text="Geh von Thalanaar nach Westen durch Feralas zum Steg an der Küste und nimm das Boot zur Festung Feathermoon."}, [3]={nodeA="{a:1116}", node="Feathermoon Stronghold"}, [4]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [5]={npc="Mardrack Greenwell", tgt="Mardrack Greenwell"}, [6]={text="Binde deinen Ruhestein im Gasthaus in der Festung Feathermoon (31.00, 43.20).", bindA="{a:1116}"}, [7]={npc="Shandris Feathermoon", tgt="Shandris Feathermoon"}, [8]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [9]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [10]={npc="Angelas Moonbreeze", tgt="Angelas Moonbreeze"}, [11]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [12]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [13]={npc="Solarsal Pavillon", npcObj=true}, [14]={npc="Solarsal Pavillon", npcObj=true}, [15]={npc="Shandris Feathermoon", tgt="Shandris Feathermoon"}, [16]={npc="Shandris Feathermoon", tgt="Shandris Feathermoon"}, [17]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [18]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [19]={hint="Bringt Latronicus Moonspear in der Festung Feathermoon 10 Nagaschuppen der Hasskämme.", desc="Die Naga an der Küste südlich der Festung Feathermoon lassen alle Schuppen fallen; sammle sie und kehre zur Festung zurück."}, [20]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [21]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear", tag="Wenn du höherstufige Mobs schaffst, Optional"}, [22]={hint="Vernichtet Lord Shalzaru und bringt dann Latronicus Moonspear in der Festung Feathermoon das geheimnisvolle Relikt, das er entdeckt hat.", tag="Wenn du höherstufige Mobs schaffst, Optional"}, [23]={text="Küste der Insel des Schreckens: Benutzt den Dornbusch am Kadaver und sprecht mit dem Geist."}, [24]={hint="Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück.", desc="Tötet Talschreier an der Küste der Insel des Schreckens in Feralas. Benutzt Yeh'kinyas Dornbusch auf jedem Kadaver und sprecht mit dem erscheinenden Geist, bis das Questlog drei Geister zählt."}, [25]={npc="Havariertes Ruderboot", npcObj=true}, [26]={npc="Havariertes Ruderboot", npcObj=true}, [27]={bindA="{a:1116}"}, [28]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [29]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [30]={npc="Quintis Jonespyre", tgt="Quintis Jonespyre"}, [31]={npc="Quintis Jonespyre", tgt="Quintis Jonespyre"}, [32]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [33]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [34]={hint="Bringt Pratt McGrubben in der Festung Feathermoon 10 dicke Yetibälge."}, [35]={hint="Angelas Moonbreeze will, dass Ihr 8 Hexenmeister der Gordunni, 8 Schamanen der Gordunni und 8 Schläger der Gordunni tötet."}, [36]={npc="Kindal Moonweaver", tgt="Kindal Moonweaver"}, [37]={hint="Befreit mit dem Bambuskäfigschlüssel die Grimmlingflitzer aus dem Pferch im Grimmtotemlager. Kindal Moonweaver sowie mindestens 6 Grimmlingflitzer müssen überleben.", desc="Zeitlimit 6 Minuten; heile dich vor der Annahme voll auf und räum die Gegner in der Nähe des Geheges."}, [38]={npc="Kindal Moonweaver", tgt="Kindal Moonweaver"}, [39]={npc="Jer'kai Moonweaver", tgt="Jer'kai Moonweaver"}, [40]={hint="Tötet 12 Naturalisten der Grimmtotem, 10 Räuber der Grimmtotem sowie 6 Schamanen der Grimmtotem und kehrt dann zu Jer'kai Moonweaver nach Feralas zurück."}, [41]={npc="Jer'kai Moonweaver", tgt="Jer'kai Moonweaver"}, [42]={npc="Jer'kai Moonweaver", tgt="Jer'kai Moonweaver"}, [43]={npc="Große Lederrucksäcke", npcObj=true}, [44]={npc="Große Lederrucksäcke", npcObj=true}, [45]={text="Der Kokon liegt in der Höhle; geh vom Eingang hinein (73.20, 63.90 → 72.30, 64.20)."}, [46]={npc="Kapsel der Zukk'ash", npcObj=true}, [47]={npc="Kapsel der Zukk'ash", npcObj=true}, [48]={hint="Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus."}, [49]={npc="OOX-22/FE-Notsignalgeber", npcObj=true, tag="Nur wenn es droppt, Optional", desc="Rechtsklicke OOX-22/FE-Notsignalgeber im Rucksack, um die Quest anzunehmen."}, [50]={npc="Leitroboter OOX-22/FE", tgt="Leitroboter OOX-22/FE", tag="Optional"}, [51]={npc="Leitroboter OOX-22/FE", tgt="Leitroboter OOX-22/FE", tag="Optional"}, [52]={hint="Eskortiert OOX-22/FE zum Dock an der Vergessenen Küste und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay.", tag="Optional", desc="Eskortiere das Roboterhuhn zum Steg an der Vergessenen Küste im Nordwesten, unterwegs gibt es Hinterhalte; abgegeben wird in Booty Bay."}, [53]={hint="Eskortiert OOX-22/FE zum Dock an der Vergessenen Küste und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay.", tag="Optional", desc="Eskorte gescheitert: Gebt die Quest im Questlog auf und nehmt sie beim Roboter erneut an."}, [54]={npc="Angelas Moonbreeze", tgt="Angelas Moonbreeze"}, [55]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [56]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [57]={npc="Shandris Feathermoon", tgt="Shandris Feathermoon"}, [58]={npc="Shandris Feathermoon", tgt="Shandris Feathermoon"}, [59]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [60]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [61]={npc="Vestia Moonspear", tgt="Vestia Moonspear"}, [62]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [63]={to="Rut'theran Village", toA="{a:702}"}}},
    ["05-d21"] = {name="Maraudon", entrance="Desolace 29.10, 62.50", pickup="Bist du in den Düstermarschen schon Stufe 39, nimm in Theramore bei Erzmagier Tervosh die Schattensplitter-Quest an. Den Rest gibt es in Desolace: Talendria und Bewahrer Marandis an der Nijelspitze, Willow, der Zentaurenpariah und zuletzt Cavindra am Höhleneingang.", pickupS={{"Bist du in den Düstermarschen schon Stufe 39, nimm in Theramore bei Erzmagier Tervosh die Schattensplitter-Quest an"}, {"Den Rest gibt es in Desolace: Talendria und Bewahrer Marandis an der Nijelspitze, Willow, der Zentaurenpariah und zuletzt Cavindra am Höhleneingang"}}, tips={{k="取捨", text="Geh beim ersten Lauf sowohl die orangefarbene als auch die violette Seite, um das Zepter zu erhalten. Willst du nur die Prinzessin und das Krokodil, kannst du mit dem Zepter eines Gruppenmitglieds direkt in den inneren Bereich. Nimm nicht die Abkürzung, wenn du die Schattenmonster draußen oder Ziele auf einer anderen Seite brauchst."}, {k="說明", text="29.10, 62.50 ist der Höhleneingang in der offenen Welt; die beiden Dungeonportale, Orange und Violett, findest du, indem du dem Tunnel der jeweiligen Farbe folgst. Die violette und die orange Route treffen sich in der Nähe des Giftwasserfalls.", s={{"29.10, 62.50 ist der Höhleneingang in der offenen Welt; die beiden Dungeonportale, Orange und Violett, findest du, indem du dem Tunnel der jeweiligen Farbe folgst"}, {"Die violette und die orange Route treffen sich in der Nähe des Giftwasserfalls"}}}}, steps={[1]={npc="Erzmagier Tervosh", tgt="Erzmagier Tervosh"}, [2]={text="Optional: Flieg von Festung Feathermoon nach Nijelspitze für die Quests, geh dann nach Süden zu Willow und dem Zentaurenpariah und zuletzt zur Höhle von Maraudon im Südwesten. Flieg nach dem Dungeon nach Rut'theran und steig bei {s:04-42} wieder ein.", tag="Optional"}, [3]={npc="Talendria", tgt="Talendria"}, [4]={npc="Bewahrer Marandis", tgt="Bewahrer Marandis"}, [5]={npc="Willow", tgt="Willow"}, [6]={npc="Zentaurenpariah", tgt="Zentaurenpariah", desc="Zentaurenpariah patrouilliert im Süden von Desolace."}, [7]={npc="Pylon der Shen'dralar", npcObj=true, tag="Optional"}, [8]={hint="Erkundet Shen'dralas, um andere Pylonen wie den zu finden, den ihr bereits gefunden habt.", tag="Optional"}, [9]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional"}, [10]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", preText="Seltsame Pylonen"}, [11]={hint="Bergt Scherben und Fragmente der Pylonen, die in den Dörfern der Magram und der Gelkis bewacht werden, und bringt sie zurück zu Mordent Evenshade.", tag="Optional", desc="Die Koordinaten zeigen der Reihe nach die beiden Gegenstände in den Zentaurendörfern von Magram und Gelkis."}, [12]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional"}, [13]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", desc="Die benötigte Menge Mana steht im Questlog.", preText="Die Fragmente der Pylonen"}, [14]={hint="Holt das Manasieb aus dem Tempel in Shen'dralas und verwendet es, um uralte Manakristalle zu sammeln. Ladet die Pylonen auf, sobald Ihr genug Mana gesammelt habt, und kehrt anschließend zu Mordent Evenshade zurück.", tag="Optional", desc="Die Menge an Mana richtet sich nach deinem Questlog. Hol das Sieb vom höchsten Stockwerk des Tempels; insgesamt sammelst du 8 Mana, 4 pro Turm. Der West- und der Ostturm lassen sich im Schleichen benutzen."}, [15]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", desc="Die benötigte Menge Mana steht im Questlog."}, [16]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", preText="Energie für die Pylonen"}, [17]={hint="Sprecht mit Mordent Evenshade in Shen'dralas, um Informationen zu den Kristallen zu erhalten, die Ihr repariert habt.", tag="Optional"}, [18]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional"}, [19]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", preText="Eine kurze Geschichtsstunde"}, [20]={hint="Findet Magister Kirandis im Tempel von Shen'dralas.", tag="Optional"}, [21]={npc="Magister Kirandis", tgt="Magister Kirandis", tag="Optional"}, [22]={npc="Mithera", tgt="Mithera", tag="Optional", preText="Ein Treffen mit dem Magister"}, [23]={hint="Untersucht die Verlorenen Gärten in der Nähe von Shen'dralas und kehrt anschließend zurück zu Mithera im nahegelegenen Tempel.", tag="Optional"}, [24]={npc="Mithera", tgt="Mithera", tag="Optional"}, [25]={npc="Mithera", tgt="Mithera", tag="Optional", preText="Verlorene Gärten"}, [26]={npc="Waldemar", tgt="Waldemar", tag="Optional"}, [27]={npc="Waldemar", tgt="Waldemar", tag="Optional", desc="Gib zuerst Wort aus dem Wald ab. Bring dies in das innere Maraudon.", preText="Wort aus dem Wald"}, [28]={npc="Cavindra", tgt="Cavindra", desc="Cavindra befindet sich außerhalb des orangefarbenen Portals. Plündere einen Gegenstand vom Boss jeder Seite."}, [29]={hint="Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Marschen von Dustwallow."}, [30]={text="Eingang: Maraudon"}, [31]={text="Orangefarbene Seite: Faulsporenhöhle (45-53). Such tief in der Höhle nach den orangefarbenen Kristallen und dem Teich. Füll das Fläschchen, bevor du das Portal betrittst."}, [32]={hint="Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.", desc="Ort: Füll das Fläschchen am Teich vor dem orangefarbenen Portal. Such nach dem Betreten unterwegs nach Ranken.", spot="Füll das Fläschchen am Teich vor dem orangefarbenen Portal. Such nach dem Betreten unterwegs nach Ranken."}, [33]={text="Violette Seite: Böse Grotte (45-53). Nimm den violetten Kristallgang an der Drei-Wege-Gabelung. Plündere den Diamanten von Lord Schlangenzunge."}, [34]={hint="Sammelt 25 theradrische Kristallschnitzereien für Willow in Desolace.", desc="Richte dich nach der Menge in deinem Questlog. Ort: Töte zuerst die Zentauren in den orangen und violetten Außenhöhlen und plündere nach dem Betreten alle Statuen entlang des Wegs.", spot="Töte Zentauren vor beiden Portalen und plündere unterwegs Statuen."}, [35]={hint="Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace.", desc="Der Erste steht zwischen der orangen und der violetten Linie. Der Zweite und der Dritte stehen jeweils in den Gängen vor den Toren. Der Vierte und der Fünfte stehen hinter dem orangen und dem violetten Tor und patrouillieren jeweils. Ort: Such die ersten drei an der Gabelung von Orange und Violett und in den zwei Außenhöhlen, dazu je einen hinter jedem Tor.", spot="Finde drei Khane an der Gabelung und den äußeren Höhlen, dann einen in jedem Portal."}, [36]={hint="Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten.", desc="Ort: Nimm auf der orangen Linie den Zauberstab und auf der violetten den Diamanten und kämpfe am Treffpunkt gegen Celebras. Reihenfolge: Beide Linien, Orange und Violett, sind nötig. Gib erst ab, wenn alle Materialien beisammen sind.", spot="Hol den Zauberstab auf der orangefarbenen und den Diamanten auf der violetten Seite. Töte Celebras dort, wo sich beide Seiten treffen."}, [37]={npc="Celebras der Erlöste", tgt="Celebras der Erlöste", desc="Sprich nach dem Sieg über den Boss mit Celebras dem Erlösten. Gib nach dem Sieg beim Erlösten im Raum ab.", spot="Im Bossraum von Celebras dem Verfluchten: Celebras der Erlöste"}, [38]={npc="Celebras der Erlöste", tgt="Celebras der Erlöste", desc="Der Erlöste befindet sich im Raum des Bosses; folge ihm während des Rituals.", preText="Legenden von Maraudon"}, [39]={hint="Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt.", desc="Der Erlöste ist im Bossraum. Folge ihm während des Rituals. Ort: Der Bossraum von Celebras: Folge dem Erlösten durch das Ritual.", spot="Folg Celebras der Erlöste durch das Ritual in seinem Bossraum."}, [40]={npc="Celebras der Erlöste", tgt="Celebras der Erlöste", desc="Der Erlöste befindet sich im Raum des Bosses; folge ihm während des Rituals.", spot="Im Bossraum von Celebras dem Verfluchten: Celebras der Erlöste"}, [41]={text="Innere Route: Fälle des irdenen Gesangs (48-57). Die Gruppe kann an der Kreuzung der orangefarbenen und violetten Route nach unten gehen, oder ein Spieler mit dem Zepter öffnet die Abkürzung."}, [42]={hint="Begebt Euch nach Maraudon und besorgt für Waldemar in den Verlorenen Gärten in Desolace eine Phiole mit Wasser aus den Fällen des Irdenen Gesangs.", tag="Optional", desc="Faulschnapper patrouilliert am Becken; die kleine Quelle befindet sich an der Wasseroberfläche. Spring unterhalb der Höhle der Prinzessin in den Pool von Faulschnapper. Such die kleine Fontäne an der Wasseroberfläche. Benutze zuerst die Quelle an der Oberfläche, dann tauch ab.", spot="Spring unterhalb der Höhle der Prinzessin in den Pool von Faulschnapper. Such die kleine Fontäne an der Wasseroberfläche."}, [43]={hint="Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück.", desc="Ort: Folge den Fällen des irdenen Gesangs in die Höhle von Zaetar und geh zur Plattform der Prinzessin.", spot="Folge den Fällen des irdenen Gesangs in die Höhle von Zaetar und geh zur Plattform der Prinzessin."}, [44]={npc="Zaetars Geist", tgt="Zaetars Geist", desc="Nach dem Tod von Prinzessin Theradras erscheint Zaetars Geist. Nimm die Quest jetzt an und gib sie nach dem Dungeon ab."}, [45]={npc="Bewahrer Marandis", tgt="Bewahrer Marandis"}, [46]={npc="Talendria", tgt="Talendria"}, [47]={npc="Willow", tgt="Willow"}, [48]={npc="Zentaurenpariah", tgt="Zentaurenpariah"}, [49]={npc="Erzmagier Tervosh", tgt="Erzmagier Tervosh"}, [50]={hint="Begebt Euch nach Maraudon und besorgt für Waldemar in den Verlorenen Gärten in Desolace eine Phiole mit Wasser aus den Fällen des Irdenen Gesangs.", tag="Optional"}, [51]={npc="Waldemar", tgt="Waldemar", tag="Optional"}, [52]={hint="Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens.", desc="Heb dir das für den Weg durch Moonglade auf."}, [53]={npc="Bewahrer Remulos", tgt="Bewahrer Remulos", desc="Heb dir das für Moonglade auf."}}},
    ["04-42"] = {grind={[1]={mob="Küstenkriecherschnappklaue", note="Der Strand gegenüber der Festung Feathermoon; du bist da, sobald du vom Schiff gehst."}, [2]={mob="Krieger der Hasskämme", note="Die Naga am Südende der Insel Sardor; nah an der Festung, etwas niedrigere Stufe."}}, steps={[1]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [2]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [3]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [4]={npc="Feralas: Ein historischer Abriss", npcObj=true}, [5]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [6]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [7]={text="Geh in Rut'theran durch das Portal nach Darnassus.", tag="Du kannst jetzt im Auktionshaus 15 × Seidenstoff kaufen oder dir von einem Twink schicken lassen (später für Eingesperrt! in der Sengenden Schlucht)."}, [8]={npc="Gracina Spiritmight", tgt="Gracina Spiritmight"}, [9]={npc="Tyrande Whisperwind", tgt="Tyrande Whisperwind"}, [10]={bindA="{a:1116}"}, [11]={desc="„Der versunkene Tempel\" kannst du erst ab Stufe 46 annehmen; fehlt dir nur noch wenig, farme Gegner in der Nähe der Festung Feathermoon bis Stufe 46; das spätere „Der runde Stein\" schließt daran an."}, [12]={npc="Angelas Moonbreeze", tgt="Angelas Moonbreeze"}, [13]={to="Gadgetzan", toA="{a:976}"}, [14]={npc="Curgle Cranklehop", tgt="Curgle Cranklehop"}, [15]={npc="Curgle Cranklehop", tgt="Curgle Cranklehop"}, [16]={npc="Leitender Feldmesser Fizzledowser", tgt="Leitender Feldmesser Fizzledowser"}, [17]={hint="Benutzt den unangezapften Wünschelrutenapparat in der Nähe des Teichs bei der Sandsorrow-Wache. Bringt den angezapften Wünschelrutenapparat zum Leitenden Feldmesser Fizzledowser nach Gadgetzan zurück, wenn Ihr die Probe entnommen habt."}, [18]={npc="Leitender Feldmesser Fizzledowser", tgt="Leitender Feldmesser Fizzledowser"}, [19]={npc="Leitender Feldmesser Fizzledowser", tgt="Leitender Feldmesser Fizzledowser"}}},
    ["04-43"] = {steps={[1]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [2]={npc="Andi Lynn", tgt="Andi Lynn", tag="Optional"}, [3]={npc="Tran'rek", tgt="Tran'rek", tag="Wenn du höherstufige Mobs schaffst, Optional"}, [4]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [5]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [6]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [7]={hint="Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [8]={hint="Sicherheitschef Bilgewhizzle aus Steamwheedle in Tanaris möchte, dass Ihr einen besonders glänzenden Armreif zurückbringt, der irgendwo beim Lager der Oger der Dünenbrecher verloren ging."}, [9]={hint="Bringt fünf Centipaarinsektenteile vom Giftigen Unterschlupf nach Gadgetzan zum Alchimisten Pestlezugg."}, [10]={hint="Marvon Rivetseeker in Tanaris möchte, dass Ihr 30 Gahz'ridian-Ornamente sammelt."}, [11]={hint="Beschafft Euch eine volle Taudrüse und bringt sie nach Gadgetzan zu Marin Noggenfogger."}, [12]={hint="Tran'rek in Gadgetzan möchte, dass Ihr 8 knorrige Distelwandler und 8 Distelwurzelformer erledigt.", tag="Wenn du höherstufige Mobs schaffst, Optional"}, [13]={npc="OOX-17/TN-Notsignalgeber", npcObj=true, tag="Nur wenn es droppt, Optional", desc="Rechtsklicke OOX-17/TN-Notsignalgeber im Rucksack, um die Quest anzunehmen."}, [14]={npc="Tooga", tgt="Tooga", tag="Optional, Eskorte, Nur machen, wenn du sie siehst", desc="Nimm die Quest nur an, wenn du Tooga antriffst und ihn zu Fuß begleiten kannst."}, [15]={hint="Zeigt Tooga den Weg zurück zu seiner Frau Torta.", tag="Optional, Eskorte", desc="Eskortiere Tooga zu Fuß zu Torta südwestlich des Dampfdruckhafens. Achte unterwegs auf Hinterhalte."}, [16]={npc="Leitroboter OOX-17/TN", tgt="Leitroboter OOX-17/TN", tag="Optional", desc="Eskortquest: In der Gruppe erst annehmen, wenn alle gleich weit sind, und automatisches Annehmen ausschalten."}, [17]={npc="Leitroboter OOX-17/TN", tgt="Leitroboter OOX-17/TN", tag="Optional"}, [18]={hint="Eskortiert OOX-17/TN nach Steamwheedle und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay.", tag="Optional"}, [19]={hint="Eskortiert OOX-17/TN nach Steamwheedle und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay.", tag="Optional", desc="Eskorte gescheitert: Gebt die Quest im Questlog auf und nehmt sie beim Roboter erneut an."}, [20]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [21]={npc="Torta", tgt="Torta", tag="Optional, Eskorte"}, [22]={text="Toogas Eskorte ist fehlgeschlagen. Du kannst der Hauptroute folgen. Für einen neuen Versuch brich die Quest ab und suche Tooga erneut."}, [23]={npc="Sicherheitchef Bilgewhizzle", tgt="Sicherheitchef Bilgewhizzle"}, [24]={npc="Andi Lynn", tgt="Andi Lynn", tag="Optional"}, [25]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [26]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [27]={npc="Sprinkle", tgt="Sprinkle"}, [28]={npc="Sprinkle", tgt="Sprinkle"}, [29]={npc="Alchimist Pestlezugg", tgt="Alchimist Pestlezugg"}, [30]={npc="Leitender Feldmesser Fizzledowser", tgt="Leitender Feldmesser Fizzledowser"}, [31]={npc="Tran'rek", tgt="Tran'rek"}, [32]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [33]={text="Die Ausrüstung liegt unten in der Höhle; folge vom Eingang der Rampe nach unten (55.00, 70.00 → 54.20, 72.90 → 56.30, 72.20)."}, [34]={hint="Erforscht das Schicksal von Unterfeldmesser Scrimshank und bringt entweder ihn oder seine Feldmesserausrüstung nach Gadgetzan zum Leitenden Feldmesser Fizzledowser."}, [35]={npc="Leitender Feldmesser Fizzledowser", tgt="Leitender Feldmesser Fizzledowser"}, [36]={npc="Leitender Feldmesser Fizzledowser", tgt="Leitender Feldmesser Fizzledowser"}, [37]={npc="Alchimist Pestlezugg", tgt="Alchimist Pestlezugg"}, [38]={npc="Alchimist Pestlezugg", tgt="Alchimist Pestlezugg"}, [39]={npc="Leitender Feldmesser Fizzledowser", tgt="Leitender Feldmesser Fizzledowser"}, [40]={npc="Leitender Feldmesser Fizzledowser", tgt="Leitender Feldmesser Fizzledowser"}, [41]={to="Theramore"}, [42]={to="Menethil Harbor", toA="{a:150}", from="Theramore", desc="Das Schiff am Pier von Theramore fährt direkt nach Menethil."}, [43]={to="Stormwind", desc="Hast du Auf der Suche nach dem Tempel nicht angenommen, musst du nicht nach Sturmwind; flieg direkt von Menethil nach Southshore."}, [44]={npc="Brohann Caskbelly", tgt="Brohann Caskbelly"}, [45]={npc="Brohann Caskbelly", tgt="Brohann Caskbelly"}}},
    ["04-44"] = {grind={[1]={mob="Wilde Eulenbestie", note="Der Wald im Zentrum des Hinterlands; viele Gegner, dieselben wie für die Wildekinfedern."}, [2]={mob="Silbermähnenpirscher", note="Die Wolfsrudel weiter östlich; sie stehen verstreut, du kannst sie einzeln töten."}}, steps={[1]={to="Southshore", toA="{a:271}", desc="Ist Southshore nicht freigeschaltet, flieg nach Menethil, nimm am nördlichen Pier das Schiff nach Auberdine und steig in Southshore aus."}, [2]={npc="Raleigh der Andächtige", tgt="Raleigh der Andächtige", tag="Optional"}, [3]={npc="Raleigh der Andächtige", tgt="Raleigh der Andächtige", tag="Optional, Gruppe empfohlen", desc="Besiegt Loksey in der Bibliothek, Herod in der Waffenkammer sowie Mograine und Whitemane in der Kathedrale. Ihr könnt die Flügel bei getrennten Besuchen abschließen."}, [4]={npc="Raleigh der Andächtige", tgt="Raleigh der Andächtige", tag="Optional, Nur mit Material"}, [5]={text="Nimm den Bergpfad nach Nordosten ins Hinterland."}, [6]={npc="Falstad Wildhammer", tgt="Falstad Wildhammer"}, [7]={nodeA="{a:348}", node="Aerie Peak"}, [8]={npc="Falstad Wildhammer", tgt="Falstad Wildhammer"}, [9]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [10]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [11]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [12]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [13]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [14]={text="Binde deinen Ruhestein im Gasthaus am Aerie Peak (13.80, 41.60).", bindA="{a:348}"}, [15]={npc="Rhapsody Shindigger", tgt="Rhapsody Shindigger", desc="Auf dem Weg zu den Eulenbestien; für die Folgequest musst du Alkohol mitbringen, nimm sie nicht an."}, [16]={hint="Sammelt 15 Wildekinfedern aus dem Hinterland für Erelas Ambersky in Rut'theran."}, [17]={hint="Durchsucht die Käfige in den beiden Dörfern der Witherbark und kehrt dann zu Greifenmeister Talonaxe zurück."}, [18]={desc="Hast du noch nicht Stufe 47, geh nach Osten und farme Wilde Eulenbestien und Silbermähnenpirscher bis Stufe 47; sammle dabei gleich Wildekinfedern."}, [19]={hint="Bringt Fraggar Thundermantle in Aerie Peak 5 Troll-Stammeshalsketten."}, [20]={hint="Sprinkle in Gadgetzan möchte, dass Ihr einen violetten Tragan sucht und ihr bringt."}, [21]={hint="Tötet 10 grüne Schlämme sowie 10 jadegrüne Brühschlammer und meldet Euch dann wieder bei Fraggar Thundermantle in Aerie Peak."}, [22]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [23]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [24]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [25]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [26]={hint="Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Talonaxe zurück."}, [27]={npc="OOX-09/HL-Notsignalgeber", npcObj=true, tag="Nur wenn es droppt, Optional", desc="Rechtsklicke OOX-09/HL-Notsignalgeber im Rucksack, um die Quest anzunehmen."}, [28]={npc="Leitroboter OOX-09/HL", tgt="Leitroboter OOX-09/HL", tag="Optional"}, [29]={npc="Leitroboter OOX-09/HL", tgt="Leitroboter OOX-09/HL", tag="Optional"}, [30]={hint="Eskortiert OOX-09/HL zur Küste jenseits der Aussichtsklippen und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay.", tag="Optional"}, [31]={hint="Eskortiert OOX-09/HL zur Küste jenseits der Aussichtsklippen und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay.", tag="Optional", desc="Eskorte gescheitert: Gebt die Quest im Questlog auf und nehmt sie beim Roboter erneut an."}, [32]={hint="Benutzt den Superschnapper FX, um einen Schnappschuss von Gammerita zu machen, und kehrt dann zu Daryn Lightwind nach Rut'theran zurück."}, [33]={hint="Whiskey Slim in Booty Bay möchte, dass Ihr ihm die Flaschen Pupellyverbos-Portwein bringt, die er verloren hat."}, [34]={bindA="{a:348}"}, [35]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [36]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [37]={to="Thelsamar", toA="{a:144}"}, [38]={text="Binde deinen Ruhestein im Gasthaus von Thelsamar (35.40, 48.40).", bindA="{a:144}"}, [39]={text="Verlass Loch Modan nach Süden und nimm hier den Bergpfad ins Ödland."}, [40]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Gruppe empfohlen, Optional", desc="Du musst erst „Elementare Hilfe\" (Kral von Razorfen) und „Sturm, Erde und Feuer\" abschließen, sonst kannst du sie nicht annehmen."}, [41]={hint="Verwendet die verdrehten Totems, um das Stacheleberritual ein für alle mal zu beenden.", tag="Gruppe empfohlen, Optional", desc="Flieg von der Zuflucht nach Menethil, nimm am Südanleger das Schiff nach Theramore, flieg nach Thalanaar und geh dann zu Fuß nach Osten in die Tausend Nadeln."}, [42]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Gruppe empfohlen, Optional", desc="Flieg von Thalanaar nach Theramore, fahr mit dem Schiff nach Menethil und flieg dann zur Zuflucht."}, [43]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Optional"}, [44]={npc="Bath'rah der Windbehüter", tgt="Bath'rah der Windbehüter", tag="Optional"}, [45]={npc="Bath'rah der Windbehüter", tgt="Bath'rah der Windbehüter"}, [46]={npc="Bath'rah der Windbehüter", tgt="Bath'rah der Windbehüter", desc="Benötigt Hauer der Bloodscalp ×30, Lebenswurz ×8 und Essenz der Verbannung ×1. Für Essenz der Verbannung bringst du je 8 × Brennender Glücksbringer, Donnernder Glücksbringer und Schäumender Glücksbringer zum Kessel neben ihm. Lebenswurz und die drei Glücksbringer gibt es im Auktionshaus."}, [47]={hint="Bringt die Gegenstände auf Bath'rahs Pergament zu Bath'rah dem Windbehüter in Alterac."}, [48]={npc="Bath'rah der Windbehüter", tgt="Bath'rah der Windbehüter"}, [49]={npc="Bath'rah der Windbehüter", tgt="Bath'rah der Windbehüter"}, [50]={hint="Bringt das Wirbelherz zu Bath'rah dem Windbehüter."}, [51]={npc="Bath'rah der Windbehüter", tgt="Bath'rah der Windbehüter"}, [52]={npc="Bath'rah der Windbehüter", tgt="Bath'rah der Windbehüter", desc="Belohnung: eine Wirbelwaffe."}, [53]={npc="Bath'rah der Windbehüter", tgt="Bath'rah der Windbehüter", desc="Belohnung: eine Wirbelwaffe."}}},
    ["04-45"] = {tips={{k="取捨", text="Mach die fünf Sammelaufgaben zusammen. Für die Abgabe aller brauchst du insgesamt Kiefer ×5, Eberlungen ×6, Skorpidscheren ×6, Echsenhirne ×11 und Geiermägen ×14. Bei jeder Abgabe werden die Materialien abgezogen."}, {k="取捨", text="Sind Geier oder Basilisken stark umkämpft, lass Der Biss des Basilisken oder Lebensenergie des Geiers unvollendet und geh wie geplant nach Norden in die Sümpfe des Elends."}}, grind={[1]={mob="Zuchtmeister der Dunkeleisenzwerge", note="Die Dunkeleisenzwerge am Rand des Kessels; die Stufe passt."}, [2]={mob="Sklavenhändler der Dunkeleisenzwerge", note="Die Südseite des Kessels; etwas niedrigere Stufe, die Gegner stehen verstreut."}}, steps={[1]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew", tag="Optional", desc="Unterwegs erhältst du meist Feuerverzauberungen. Fällt keine, brich die Quest ab."}, [2]={npc="Garek", tgt="Garek", tag="Gruppe empfohlen, Optional", desc="Du musst zwei Elite-Schwarzdrachen der Stufe 50 töten; ohne Gruppe überspringst du das."}, [3]={hint="Benutzt das Zeichen der Erde, um die Amethyst-, Opal- und Diamantsäulen zu aktivieren und die Runensteine zu holen.", tag="Später unterwegs erledigen, Gruppe empfohlen, Optional"}, [4]={npc="Siegel der Erde", npcObj=true, tag="Gruppe empfohlen, Optional"}, [5]={npc="Siegel der Erde", npcObj=true, tag="Gruppe empfohlen, Optional"}, [6]={npc="Garek", tgt="Garek", tag="Gruppe empfohlen, Optional"}, [7]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew", tag="Optional"}, [8]={hint="Tötet den Botschafter Infernus in der Festung Angor und bringt Berater Belgrum in Ironforge einen Beweis seines Tod.", tag="Gruppe empfohlen, Optional"}, [9]={text="Geh aus dem Ödland nach Westen und nimm den Bergpfad neben Kargath, dem Lager der Horde, in die Sengende Schlucht. Umgehe Kargath.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [10]={npc="Hölzernes Plumpsklo", npcObj=true, desc="Seidenstoff gibt es im Auktionshaus. Du brauchst 15 Stück."}, [11]={hint="Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff."}, [12]={text="Töte Margol den Wüterich, das bringt viel Erfahrung.", tag="Optional", desc="Margols Horn startet die Questreihe um den Schlüssel zur Sengenden Schlucht; willst du nicht kämpfen, überspring es; die zugehörigen späteren Schritte werden dann automatisch übersprungen, und zum Schluss fliegst du von Ironforge zurück zur Thoriumspitze."}, [13]={npc="Margols Horn", npcObj=true, tag="Optional, Gruppe empfohlen", desc="Rechtsklicke Margols Horn im Rucksack, um die Quest anzunehmen."}, [14]={npc="Hölzernes Plumpsklo", npcObj=true}, [15]={npc="Hölzernes Plumpsklo", npcObj=true, tag="Optional", desc="Für die Abgabe brauchst du vier Dinge: das Geschäftsbuch neben dem Abort, Beine von Glasnetzspinnen ×20, das überfällige Paket aus den Düstermarschen und Jarquias Schwert aus den Sümpfen des Elends. Für fehlende Teile lohnt sich kein Extraweg."}, [16]={hint="Nehmt die Abschrift von Goodsteels Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goodsteel in Tanaris aufsucht.", tag="Nur mit Material"}, [17]={npc="Dorius Stonetender", tgt="Dorius Stonetender"}, [18]={hint="Helft Dorius, zurück nach Ironforge zu kommen.", tag="Eskorte", desc="Folge Dorius nach Norden; nach dem Hinterhalt, sobald das Questlog sie als abgeschlossen zeigt, heb den verkohlten Brief an Ort und Stelle auf und gib ihn ab."}, [19]={npc="Angesengter Brief", npcObj=true}, [20]={npc="Angesengter Brief", npcObj=true}, [21]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [22]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [23]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [24]={nodeA="{a:1446}", node="Thorium Point"}, [25]={npc="Gesucht/Vermisst/Verloren & Gefunden", npcObj=true, tag="Gruppe empfohlen, Optional", desc="Aufseher Maltorius ist ein Elite der Stufe 50; ohne Gruppe überspringst du das."}, [26]={npc="Gesucht/Vermisst/Verloren & Gefunden", npcObj=true}, [27]={npc="Gesucht/Vermisst/Verloren & Gefunden", npcObj=true}, [28]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [29]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands", tag="Optional"}, [30]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [31]={npc="Meisterschmied Burninate", tgt="Meisterschmied Burninate"}, [32]={bindA="{a:144}"}, [33]={npc="Gebirgsjägerin Pebblebitty", tgt="Gebirgsjägerin Pebblebitty", tag="Optional"}, [34]={npc="Gebirgsjägerin Pebblebitty", tgt="Gebirgsjägerin Pebblebitty"}, [35]={to="Ironforge"}, [36]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Optional"}, [38]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [39]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [40]={npc="Kurator Thorius", tgt="Kurator Thorius", tag="Optional"}, [41]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [42]={npc="Berater Belgrum", tgt="Berater Belgrum", tag="Gruppe empfohlen, Optional"}, [43]={npc="Berater Belgrum", tgt="Berater Belgrum", tag="Optional, Gruppe empfohlen"}, [44]={to="Thelsamar", toA="{a:144}", tag="Optional", desc="Geh nur mit „Endlich!\" zu Gebirgsjägerin Pebblebitty zurück, um den Schlüssel zu holen; hast du sie nicht, überspring es und flieg direkt von Ironforge zurück zur Thoriumspitze."}, [45]={npc="Gebirgsjägerin Pebblebitty", tgt="Gebirgsjägerin Pebblebitty", tag="Optional"}, [46]={text="Öffne mit dem frisch erhaltenen Schlüssel zur Sengenden Schlucht das Tor neben Gebirgsjägerin Pebblebitty und geh durch den Tunnel in die Sengende Schlucht.", tag="Optional"}, [47]={to="Thorium Point", toA="{a:1446}", desc="Hast du den Schlüssel zur Sengenden Schlucht nicht, flieg von Ironforge direkt zurück zur Sengenden Schlucht. Bist du bereits durch den Tunnel hereingekommen, überspring das."}, [48]={hint="Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Velarok Windblade."}, [49]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [50]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [51]={hint="Sucht die Schmiedewindform und das Ausguck-Handfernrohr. Bringt diese Gegenstände zu Zuchtmeister Scrange in der sengenden Schlucht."}, [52]={hint="Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Scrange zurück, sobald Ihr die Aufgabe erfüllt habt."}, [53]={hint="Hansel Heavyhands möchte, dass Ihr 20 Schwere Kriegsgolems tötet."}, [54]={hint="Hansel Heavyhands möchte, dass Ihr 20 sengende Lavaspinnen in der sengenden Schlucht tötet.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [55]={text="Vom östlichen Eingang mit den Bergleuten aus rechts halten und dem unteren Gang an der Lava entlang bis zur Incendosaurierhöhle folgen."}, [56]={hint="Hansel Heavyhands möchte, dass Ihr 20 Incendosaurier tötet."}, [57]={desc="Falls noch EP bis Stufe 48 fehlen, in der Mine bleiben und auf dem bereits geräumten Weg einzelne normale Incendosaurier bekämpfen. Gibt es drinnen keinen sicheren Kampf, auf demselben Weg hinausgehen und am Rand des Kessels Dunkeleisenaufseher oder Sklavenjäger bekämpfen."}, [58]={hint="Tief in der Schlackengrube des Kessels in der sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden.", tag="Später unterwegs erledigen, Gruppe empfohlen, Optional"}, [59]={text="Auf dem östlichen Weg zu den Plänen die Brücke überqueren und im großen Raum links abbiegen. Die Pläne liegen auf der oberen Plattform auf dem Tisch hinter dem Aufseher. Bei Elitewachen den Schritt überspringen und später oder mit einer Gruppe reaktivieren."}, [60]={hint="Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der sengenden Schlucht.", desc="Aufseher Maltorius oder eine Elitewache kann die obere Plattform bewachen. Allein erst prüfen, ob der Weg zum Tisch frei ist. Nur für das Kopfgeld muss der Aufseher sterben."}, [61]={hint="Bringt 8 mit Thorium beschichtete Dolche zu Velarok Windblade."}, [62]={npc="Sterbender Archäologe", tgt="Sterbender Archäologe"}, [63]={npc="Sterbender Archäologe", tgt="Sterbender Archäologe"}, [64]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [65]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional"}, [66]={hint="Sucht das mysteriöse Artefakt, das im Norden von den Twilight-Hammer bewacht wird.", tag="Später unterwegs erledigen", desc="Das Artefakt liegt im Lager des Schattenhammers am nördlichen Lavabecken, bewacht von Elite-Götzendienern der Stufen 49-51. Warte, bis die Elitegegner weggehen, nimm es und verschwinde. Schaffst du es nicht, überspringe diesen Schritt und die Abgabe von Erlöst sie."}, [67]={hint="Bringt ein Symbol von Ragnaros zu Velarok Windblade.", tag="Gruppe empfohlen, Optional, Später unterwegs erledigen", desc="Nur Elitegegner droppen das Symbol von Ragnaros."}, [68]={npc="Zamael Lunthistle", tgt="Zamael Lunthistle"}, [69]={npc="Zamael Lunthistle", tgt="Zamael Lunthistle"}, [70]={npc="Zamael Lunthistle", tgt="Zamael Lunthistle", tag="Gruppe empfohlen, Optional"}, [71]={npc="Ausguck Captain Lolo Longstriker", tgt="Ausguck Captain Lolo Longstriker", tag="Gruppe empfohlen, Optional"}, [72]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [73]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands", tag="Optional"}, [74]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [75]={npc="Zuchtmeister Scrange", tgt="Zuchtmeister Scrange"}, [76]={npc="Zuchtmeister Scrange", tgt="Zuchtmeister Scrange"}, [77]={npc="Meisterschmied Burninate", tgt="Meisterschmied Burninate"}, [78]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional"}, [79]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [80]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [81]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [82]={npc="Fackel der Vergeltung", npcObj=true}, [83]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [84]={npc="Knappe Maltrake", tgt="Knappe Maltrake"}, [85]={npc="Knappe Maltrake", tgt="Knappe Maltrake"}, [86]={hint="Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt."}, [87]={npc="Altar von Suntara", npcObj=true}, [88]={npc="Sterbender Archäologe", tgt="Sterbender Archäologe", tag="Gruppe empfohlen, Optional", desc="Lathoric der Schwarze und Obsidion sind beide Elitegegner der Stufe 52; such dir dafür eine Gruppe."}, [89]={hint="Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Ironforge mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion.", tag="Gruppe empfohlen, Optional"}, [90]={npc="Knappe Maltrake", tgt="Knappe Maltrake"}, [91]={npc="Hort des Schwarzdrachenschwarms", npcObj=true}, [92]={npc="Hort des Schwarzdrachenschwarms", npcObj=true, desc="Behalte die Abgestreifte Haut des schwarzen Drachenschwarms und gib sie in der Brennenden Steppe bei Cyrus Therepentous ab."}, [93]={tag="Optional, Gruppe empfohlen", desc="Level hier nur mit einer Gruppe für die Blackrocktiefen bis 52. Solo überspringen."}, [94]={to="Ironforge", desc="Ist dein Ruhestein bereit, nutze ihn zurück nach Thelsamar und flieg von dort; sonst geh zurück zur Thoriumspitze (37.90, 30.40) und such den Flugmeister."}, [95]={npc="Kurator Thorius", tgt="Kurator Thorius", tag="Gruppe empfohlen, Optional"}, [96]={npc="Hochforscher Magellas", tgt="Hochforscher Magellas"}, [97]={npc="Hochforscher Magellas", tgt="Hochforscher Magellas", desc="Erst verfügbar, nachdem du „Die Platinscheiben\" in Uldaman abgeschlossen hast."}, [98]={npc="Historiker Karnik", tgt="Historiker Karnik"}, [99]={npc="Historiker Karnik", tgt="Historiker Karnik"}, [100]={text="Binde deinen Ruhestein im Gasthaus von Ironforge (18.60, 51.60)."}, [101]={to="Nethergarde Keep", toA="{a:1438}", desc="Ist die Burg Nethergarde nicht freigeschaltet, flieg nach Dunkelhain, geh nach Osten durch den Gebirgspass der Totenwinde in die Sümpfe des Elends und dann nach Süden in die Verwüsteten Lande zur Burg Nethergarde."}, [102]={npc="Thadius Grimshade", tgt="Thadius Grimshade"}, [103]={npc="Thadius Grimshade", tgt="Thadius Grimshade", tag="Optional, Gruppe empfohlen"}, [104]={npc="Blutmagier Drazial", tgt="Blutmagier Drazial"}, [105]={npc="Blutmagier Drazial", tgt="Blutmagier Drazial"}, [106]={npc="Blutmagier Drazial", tgt="Blutmagier Drazial"}, [107]={npc="Blutmagierin Lynnore", tgt="Blutmagierin Lynnore"}, [108]={npc="Blutmagierin Lynnore", tgt="Blutmagierin Lynnore"}, [109]={hint="Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange."}, [110]={hint="Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn."}, [111]={hint="Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge."}, [112]={hint="Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen."}, [113]={hint="Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer."}, [114]={npc="Blutmagier Drazial", tgt="Blutmagier Drazial"}, [115]={npc="Blutmagier Drazial", tgt="Blutmagier Drazial"}, [116]={npc="Blutmagier Drazial", tgt="Blutmagier Drazial"}, [117]={npc="Blutmagierin Lynnore", tgt="Blutmagierin Lynnore"}, [118]={npc="Blutmagierin Lynnore", tgt="Blutmagierin Lynnore"}, [119]={npc="Cortellos Rätsel", npcObj=true, tag="Nur wenn es droppt, Optional", desc="Rechtsklicke Cortellos Rätsel im Rucksack, um die Quest anzunehmen."}, [120]={text="Geh vom Lager der Blutmagier zurück zur nördlichen Straße, verlass die Verwüsteten Lande nach Norden in die Sümpfe des Elends und folge dann der Straße nach Westen bis an den Westrand des Sumpfes."}, [121]={npc="Eine glitschige Rolle", npcObj=true}, [122]={npc="Eine glitschige Rolle", npcObj=true}}},
    ["04-46"] = {grind={[1]={mob="Blaumähnengorilla", note="Die kleine Insel, auf der König Mukla ist; normale Gegner, die du nach dem Kampf gegen den König nebenbei erledigst."}, [2]={mob="Jagueropirscher", note="Die Westseite derselben Insel."}}, steps={[1]={to="Booty Bay", toA="{a:35}", desc="In den Sümpfen des Elends gibt es keinen Flugpunkt der Allianz: Geh nach Westen durch den Gebirgspass der Totenwinde zurück nach Dunkelhain und flieg von dort."}, [2]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [3]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [4]={npc="Whiskey Slim", tgt="Whiskey Slim"}, [5]={npc="Seewolf MacKinley", tgt="Seewolf MacKinley"}, [6]={npc="Fin Fizracket", tgt="Fin Fizracket"}, [7]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Optional"}, [8]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Optional"}, [9]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Optional"}, [10]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Optional"}, [11]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Optional"}, [12]={npc="Sorgfältig gefaltete Notiz", npcObj=true, desc="Rechtsklicke Sorgfältig gefaltete Notiz im Rucksack, um die Quest anzunehmen. Rechtsklicke jetzt die gefaltete Notiz von vorhin, um die Quest zu starten."}, [13]={npc="Prinzessin Poobah", tgt="Prinzessin Poobah"}, [14]={npc="Prinzessin Poobah", tgt="Prinzessin Poobah", tag="Gruppe empfohlen, Optional"}, [15]={hint="Erschlagt König Mukla und kehrt mit dem Schlüssel zu Prinzessin Poobah zurück, um sie zu befreien.", tag="Gruppe empfohlen, Optional"}, [16]={npc="Prinzessin Poobah", tgt="Prinzessin Poobah", tag="Gruppe empfohlen, Optional"}, [17]={npc="Hexendoktor Unbagwa", tgt="Hexendoktor Unbagwa", desc="Nimm zuerst Schlingendornfieber an und schließe dann dieses Ereignis zur Abgabe der Hauer ab."}, [18]={hint="Beute von: Nebeltalgorilla, Dschungeldonnerer, Wütender Silberrücken", desc="Nimm zuerst Schlingendornfieber an und schließe dann dieses Ereignis zur Abgabe der Hauer ab."}, [19]={npc="Hexendoktor Unbagwa", tgt="Hexendoktor Unbagwa", desc="Nimm zuerst Schlingendornfieber an und schließe dann dieses Ereignis zur Abgabe der Hauer ab."}, [20]={hint="Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizracket.", desc="Mit der Abgabe von Schlingendornfieber erscheint Mokk. Fehlen dir Gorillahauer oder hältst du die Gorillawellen nicht aus, überspringe diesen Schritt und die Abgabe von Schlingendornfieber darunter; später hängt nichts davon ab."}, [21]={desc="Hast du noch nicht Stufe 49, töte im Nebeltal weiter Gorillas bis Stufe 49."}, [22]={npc="Fin Fizracket", tgt="Fin Fizracket"}, [23]={to="Ratchet", toA="{a:392}", from="Booty Bay", fromA="{a:35}"}, [24]={hint="Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet."}, [25]={to="Theramore"}, [26]={npc="Modrige Rolle", npcObj=true}, [27]={npc="Modrige Rolle", npcObj=true, tag="Optional"}}},
    ["05-d22"] = {name="Alcaz Prison", entrance="Marschen von Dustwallow 75.30, 14.10", pickup="Flieg an {s:04-46} vor dem Flug von Dunkelhain nach Booty Bay zuerst nach Sturmwind, wenn du Stufe 48 bist, und nimm bei Meister Mathias Shaw Der Spitzel von Theramore an. Wenn {s:04-46} mit dem Flug nach Theramore endet, such Sully McCleary für die Folgequests auf.", pickupS={{"Flieg an {s:04-46} vor dem Flug von Dunkelhain nach Booty Bay zuerst nach Sturmwind, wenn du Stufe 48 bist, und nimm bei Meister Mathias Shaw Der Spitzel von Theramore an"}, {"Wenn {s:04-46} mit dem Flug nach Theramore endet, such Sully McCleary für die Folgequests auf"}}, tips={{k="提醒", text="Optional ab Stufe 48: Sprecht vor dem Betreten ab, den Verhörer am Leben zu lassen. Redet nach dem Endboss mit dem gefesselten Gefangenen. Nehmt die Quest an, kehrt zum Verhörer zurück und bringt dem Gefangenen seinen Schlüssel.", s={{"Optional ab Stufe 48: Sprecht vor dem Betreten ab, den Verhörer am Leben zu lassen"}, {"Redet nach dem Endboss mit dem gefesselten Gefangenen"}, {"Nehmt die Quest an, kehrt zum Verhörer zurück und bringt dem Gefangenen seinen Schlüssel"}}}}, steps={[1]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw"}, [2]={npc="Sully McCleary", tgt="Sully McCleary"}, [3]={npc="Sully McCleary", tgt="Sully McCleary"}, [4]={npc="Sully McCleary", tgt="Sully McCleary"}, [5]={npc="Sully McCleary", tgt="Sully McCleary"}, [6]={hint="Benutzt das SI:7 Verkleidungsset, um Jaina und ihre Vertrauten im Magierturm von Theramore zu belauschen."}, [7]={npc="Sully McCleary", tgt="Sully McCleary"}, [8]={npc="Sully McCleary", tgt="Sully McCleary"}, [9]={npc="Sully McCleary", tgt="Sully McCleary", tag="Optional"}, [10]={text="Optional: Folge von Theramore der Ostküste nach Norden bis zum Nordostufer der Düstermarschen und schwimm zur Insel Alcaz; das Dungeonportal liegt im Gang unter dem Inselturm. Gib nach dem Dungeon in Theramore ab und steig bei {s:04-47} wieder ein.", tag="Optional"}, [11]={text="Eingang: Alcaz Prison"}, [12]={hint="Begebt Euch in das Gefängnis von Alcaz und tötet 15 Soldaten der Strashaz sowie 8 Verzauberinnen der Strashaz und bringt den Kopf von Gezeitenherrin Ca'zass zu Sully McCleary.", tag="Optional", desc="Ort: Such Gezeitenherrin Ca'zass in den oberen Zellen und räum die Naga im Gang.", spot="Such Gezeitenherrin Ca'zass in den oberen Zellen und räum die Naga im Gang."}, [13]={hint="Begebt Euch in das Gefängnis von Alcaz und findet heraus, was mit dem König von Stormwind passiert ist.", desc="Ort: Öffne das untere Tor und töte den letzten Boss; geh dann in die Geheimkammer dahinter und such den Zettel auf dem Boden. Reihenfolge: Hol zuerst den Schlüssel vom Gefängniswärter.", spot="Öffne die untere Tür und töte den Endboss. Such im versteckten Raum dahinter die Notiz auf dem Boden."}, [14]={npcObj=true, spot="Notiz auf dem Boden des Geheimraums hinter Blazeroar"}, [15]={npcObj=true}, [16]={tag="Optional", desc="Sprich nach dem Endboss mit dem gefesselten Gefangenen daneben. Der Befrager muss noch leben, damit du den Schlüssel bekommst."}, [17]={hint="Beschafft den Fesselschlüssel von Alcaz vom Verhörer im Gefängnis von Alcaz.", tag="Optional"}, [18]={tag="Optional", spot="Neben dem Endboss, der gefesselte Gefangene"}, [19]={npc="Sully McCleary", tgt="Sully McCleary", tag="Optional"}, [20]={npc="Sully McCleary", tgt="Sully McCleary"}, [21]={npc="Sully McCleary", tgt="Sully McCleary"}, [22]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw", desc="Gib sie beim nächsten Besuch in Sturmwind ab."}}},
    ["04-47"] = {steps={[1]={to="Gadgetzan", toA="{a:976}", desc="Die Schriftrolle liegt in der Raptorhöhle im Südwesten der Marschen von Dustwallow. Geh zuerst nach Osten zurück nach Theramore (67.48, 51.30) und flieg dann."}, [2]={npc="Krinkle Goodsteel", tgt="Krinkle Goodsteel", tag="Nur mit Material"}, [3]={npc="Sprinkle", tgt="Sprinkle"}, [4]={npc="Sprinkle", tgt="Sprinkle"}, [5]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [6]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [7]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [8]={text="Folge von Gadgetzan der Straße nach Norden zur Schimmernden Ebene in Tausend Nadeln."}, [9]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [10]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [11]={npc="Gnomen-Boxenboss", tgt="Gnomen-Boxenboss"}, [12]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts", tag="Optional"}, [13]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts", tag="Optional, Gruppe empfohlen"}, [14]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [15]={npc="Uldum-Sockel", npcObj=true}, [16]={npc="Steinbehüter von Norgannon", tgt="Steinbehüter von Norgannon"}, [17]={npc="Uldum-Sockel", npcObj=true}, [18]={npc="Uldum-Sockel", npcObj=true}, [19]={text="Geh nach Nordwesten zum Anfang des Pfads in den Un'Goro-Krater."}}},
    ["04-48"] = {grind={[1]={mob="Blutblütenpeitscher", note="Die Pflanzengegner auf der Ostseite; töte sie, wenn du gerade in den Krater gekommen bist."}, [2]={mob="Un'Goro-Gorilla", note="Vor der Gorillahöhle im Nordosten; dieselben Gegner wie für die Gorillapelze."}, [3]={mob="Pterrordax", note="Die Felswand östlich von Marshals Zuflucht."}, [4]={mob="Teerlauerer", note="Die Teergruben südlich des Lagers; eher hohe Stufe, zieh sie einzeln."}}, steps={[1]={text="Folge dem Bergpfad westlich von Tanaris die Rampe hinab in den Un'Goro-Krater. Torwa Pathfinder steht direkt am Eingang am Fuß der Rampe.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [2]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Wenn du höherstufige Mobs schaffst, Optional"}, [3]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [4]={npc="Ein havariertes Floß", npcObj=true, desc="Sammle je 7 rote, blaue, grüne und gelbe Kristalle und hol dir „Ein zerfleddertes Tagebuch\" von den Raptoren."}, [5]={npc="Ein kleines Pack", npcObj=true}, [6]={npc="Ein kleines Pack", npcObj=true}, [7]={hint="Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pathfinder im Un'Goro Krater zurück."}, [8]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [9]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [10]={hint="Bringt Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater 2 Ravasaurus-Pheromondrüsen."}, [11]={npc="Kristalldurchdrungene Schuppe", npcObj=true, tag="Optional"}, [12]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Optional, Nur mit Material"}, [13]={text="Benutzt die Kristalldurchdrungene Schuppe in eurer Tasche, um Mikrokristallkontamination zu starten. Gebt dann beide Quests bei Torwa ab."}, [14]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [15]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Optional"}, [16]={hint="Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater.", tag="Gruppe empfohlen, Optional", desc="Diese ist schwerer. Du kannst sie für die Rückkehr nach Un'Goro aufheben."}, [17]={npc="Karna Remtravel", tgt="Karna Remtravel"}, [18]={npc="Linken", tgt="Linken"}, [19]={npc="Linken", tgt="Linken"}, [20]={nodeA="{a:541}", node="Marshal's Refuge"}, [21]={npc="Williden Marshal", tgt="Williden Marshal"}, [22]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [23]={npc="Spark Nilminer", tgt="Spark Nilminer"}, [24]={npc="J.D. Collie", tgt="J.D. Collie", desc="Sammelt auf dem Weg Machtkristalle. Habt ihr beim ersten Treffen mit J.D. Collie sieben von jeder Farbe, gebt sie gleich ab. Fehlende Kristalle könnt ihr bis zum nächsten Besuch sammeln."}, [25]={npc="Vorsicht, Pterrordax!", npcObj=true}, [26]={npc="Muigin", tgt="Muigin"}, [27]={npc="Shizzle", tgt="Shizzle"}, [28]={hint="Bringt 8 Dinosaurierknochen zu Spark Nilminer im Un'Goro Krater."}, [29]={hint="Bringt Torwa Pathfinder am Eingang zum Un'Goro Krater 2 Un'Goro-Gorillapelze, 2 Un'Goro-Stampferpelze und 2 Un'Goro-Donnererpelze.", tag="Wenn du höherstufige Mobs schaffst, Optional"}, [30]={desc="Hast du noch nicht Stufe 50, bleib vor der Gorillahöhle und farme Un'Goro-Gorillas bis Stufe 50."}, [31]={hint="Sammelt 15 Blutblüten und kehrt zu Muigin zurück."}, [32]={text="Plündere die Vorratskiste im östlichen Lager."}, [33]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [34]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [35]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [36]={text="Für die Probe in den Bau: Geh nach Südwesten zum Höhleneingang und dann hinein (50.40, 78.80 → 48.70, 85.20)."}, [37]={hint="Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Un'Goro Krater zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut."}, [38]={text="Schließ deine offenen Töte- und Sammelquests ab."}, [39]={hint="Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marshal im Un'Goro Krater.", desc="Die Kiste mit Lebensmitteln liegt im Osten (auf dem Weg zur Gorillahöhle und zu Torwa), die Forscherausrüstung im Südwesten (auf dem Weg vom Silithidenstock zu den Pterrordaxen), nimm im Vorbeigehen je eins mit."}, [40]={hint="Sammelt 8 eingesponnene Dimetrodon-Schuppen und 8 eingesponnene Pterrordax-Schuppen für Shizzle in Marshals Zuflucht."}, [41]={hint="Tötet 10 Pterrordax und 15 rasende Pterrordax und sprecht dann mit Spraggle Frock in Marshals Zuflucht."}, [42]={npc="Shizzle", tgt="Shizzle"}, [43]={npc="Muigin", tgt="Muigin"}, [44]={npc="Muigin", tgt="Muigin"}, [45]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [46]={npc="Spark Nilminer", tgt="Spark Nilminer"}, [47]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [48]={npc="Williden Marshal", tgt="Williden Marshal"}, [49]={npc="Ein zerfleddertes Tagebuch", npcObj=true, tag="Optional", desc="Rechtsklicke Ein zerfleddertes Tagebuch nur, wenn du es von Gegnern erbeutet hast."}, [50]={npc="Williden Marshal", tgt="Williden Marshal", tag="Optional"}, [51]={desc="Hast du noch nicht Stufe 51, farme östlich des Lagers Pterrordax oder an den Teergruben im Süden Teerlauerer bis Stufe 51."}, [52]={desc="Wenn dein Ruhestein an Eisenschmiede gebunden ist, benutze ihn, sobald er bereit ist. Priester können bei Hohepriester Rohan die Quest „Cenarische Hilfe\" annehmen, Magier bei Dink optional „Geschick der Magier\"."}, [53]={text="Geh nur hin, wenn du die Einführungsquest in Sturmwind annehmen willst: Nimm in Ironforge die Tiefenbahn nach Sturmwind.", tag="Optional"}, [54]={npc="Maginor Dumas", tgt="Maginor Dumas", tag="Optional", desc="Die Einführung in Sturmwind kannst du überspringen. In Azshara musst du dich trotzdem zuerst von Sanath Lim-yo auf die Klippe teleportieren lassen."}, [55]={text="Flieg von Sturmwind zum Hafen von Menethil, um wieder auf die Route zu kommen.", tag="Optional"}, [56]={npc="Hohepriester Rohan", tgt="Hohepriester Rohan", tag="Du kannst jetzt im Auktionshaus 1 × Sekret des Untodes kaufen oder dir von einem Twink schicken lassen (später für Sekret des Untodes in Azshara).", desc="Gib sie bei Ogtinc in Azshara ab."}, [57]={to="Menethil Harbor", toA="{a:150}", desc="Prüfe in Marschalls Zuflucht die Flugkarte. Fliege nach Auberdine oder Rut'theran, wenn der Flug angeboten wird. Sonst nimm die südöstliche Rampe nach Tanaris und prüfe die Flüge in Gadgetzan."}, [58]={to="Auberdine", from="Menethil Harbor", fromA="{a:150}", desc="Dieses Schiff hält unterwegs in Southshore. Steig erst in Auberdine aus."}, [59]={to="Rut'theran Village", toA="{a:702}", desc="Steige in Auberdine nach Rut'theran um. Wenn du auf dem Schiff bist, gehe nach dem Anlegen von Bord. Nimm einen verfügbaren Flug oder das Schiff am Nordsteg (33.3, 39.8)."}, [60]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [61]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [62]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [63]={text="Geh in Rut'theran durch das Portal nach Darnassus.", tag="Du kannst jetzt im Auktionshaus 1 × Mithrilgehäuse kaufen oder dir von einem Twink schicken lassen (später für Chasing A-Me 01 im Krater von Un'Goro)."}, [64]={npc="Gracina Spiritmight", tgt="Gracina Spiritmight"}, [65]={npc="Gracina Spiritmight", tgt="Gracina Spiritmight"}, [66]={npc="Astarii Starseeker", tgt="Astarii Starseeker", tag="Gruppe empfohlen, Optional"}, [67]={npc="Dorion", tgt="Dorion", desc="Nimm sie in Darnassus (oder Ironforge, Sturmwind) an und gib sie bei Ogtinc in Azshara ab."}, [68]={text="Geh in Darnassus durch das Portal zurück nach Rut'theran."}, [69]={to="Astranaar", toA="{a:415}"}, [70]={text="Binde deinen Ruhestein im Gasthaus von Astranaar (37.00, 49.20).", bindA="{a:415}"}, [71]={text="Prüfe deinen Standort. Wenn du an Bord bist, gehe erst am Zielhafen von Bord. Steige in Auberdine nach Rut'theran um. Sobald du dort an Land bist, gib deine Quests ab."}, [72]={text="Für die Klassenquest in den Östlichen Königreichen prüfe in Marschalls Zuflucht die Flüge nach Auberdine. Gibt es keinen passenden Flug, nimm die südöstliche Rampe nach Tanaris und prüfe die Flüge in Gadgetzan. Nimm in Auberdine das direkte Schiff nach Sturmwind."}, [73]={text="Nimm in Auberdine das direkte Schiff nach Sturmwind. Wenn du noch an Bord bist, gehe nach dem Anlegen von Bord und warte am Steg nach Sturmwind (30.5, 40.9)."}, [74]={text="Fahre vom Hafen von Sturmwind zurück nach Auberdine. Warte am Steg nach Auberdine (21.8, 56.9) und setze nach dem Anlegen deine Route in Kalimdor fort."}, [75]={text="Prüfe deinen Standort und dein Questlog. Halte vor der Überfahrt einen Platz für die Klassenquest frei. Bleibe an Bord, bis das Schiff im Zielhafen anlegt."}, [76]={text="Gehe nach dem Anlegen im Hafen von Sturmwind von Bord und suche den Geber der Klassenquest in der Stadt auf. Bleibe auf See an Bord."}, [77]={npc="Bruder Joshua", tgt="Bruder Joshua"}, [78]={npc="Dink", tgt="Dink", tag="Optional"}, [79]={text="Fragt beim Flugmeister in Eisenschmiede nach einem Flug zum Hafen von Menethil. Gibt es keinen passenden Flug, nehmt die Tiefenbahn nach Sturmwind und vom Hafen dort das Schiff nach Auberdine."}, [80]={to="Talrendis Point", toA="{a:3137}"}, [81]={npc="Loh'atu", tgt="Loh'atu"}, [82]={npc="Loh'atu", tgt="Loh'atu"}, [83]={hint="Vernichtet 6 Erscheinungen einer Hochgeborenen und 6 Lichlinge eines Hochgeborenen, bevor Ihr zu Loh'atu in Azshara zurückkehrt."}, [84]={hint="Tötet 6 Satyrn der Haldarr, 2 Schwindler der Haldarr sowie 2 Teufelsanbeter der Haldarr und kehrt dann zu Loh'atu an der Grenze zu Ashenvale zurück."}, [85]={npc="Loh'atu", tgt="Loh'atu"}, [86]={npc="Loh'atu", tgt="Loh'atu"}, [87]={npc="Sanath Lim-yo", tgt="Sanath Lim-yo", tag="Optional", desc="Gib sie hier nur ab, wenn du die Einführung angenommen hast."}, [88]={text="Sprich mit Sanath Lim-yo und bitte ihn, dich auf die Klippe zu Erzmagier Xylem zu teleportieren."}, [89]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem"}, [90]={hint="Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben."}, [91]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", desc="Der Staub liegt unten am Berg; lass dich genauso von Sanath Lim-yo wieder hinaufteleportieren."}, [92]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem"}, [93]={hint="Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem."}, [94]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem"}, [95]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", tag="Gruppe empfohlen, Optional", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [96]={hint="Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück.", tag="Gruppe empfohlen, Optional", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [97]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", tag="Gruppe empfohlen, Optional", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [98]={text="Reise über Astranaar in den Teufelswald. Ist dein Ruhestein an Astranaar gebunden und einsatzbereit, kannst du damit direkt zum Gasthaus zurück. Sobald du sicher unten bist, prüfe die Flugkarte an der Talrendisspitze. Ist Astranaar als Ziel verfügbar, flieg dorthin. Folge sonst der Hauptstraße durch das östliche Eschental nach Westen. Folge von Astranaar aus der Hauptstraße nach Norden in den Teufelswald."}, [99]={npc="Ogtinc", tgt="Ogtinc"}, [100]={npc="Ogtinc", tgt="Ogtinc"}, [101]={hint="Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath."}, [102]={npc="Ogtinc", tgt="Ogtinc"}, [103]={npc="Ogtinc", tgt="Ogtinc", desc="Sekret des Untodes ×1 gibt es im Auktionshaus."}, [104]={hint="Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath."}, [105]={npc="Ogtinc", tgt="Ogtinc"}, [106]={npc="Ogtinc", tgt="Ogtinc", tag="Gruppe empfohlen, Optional", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [107]={text="Bist du noch in Azshara, kehre zum Talrendisspitz zurück, fliege nach Astranaar und reise nach Norden in den Teufelswald. Nach dem Tempel geht es direkt zum Smaragdrefugium im Teufelswald."}, [108]={npc="Ogtinc", tgt="Ogtinc", desc="Nimm sie in Darnassus (oder Ironforge, Sturmwind) an und gib sie bei Ogtinc in Azshara ab."}, [109]={npc="Ogtinc", tgt="Ogtinc"}, [110]={hint="Bringt ein perfektes Rennergeweih zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath."}, [111]={npc="Ogtinc", tgt="Ogtinc"}, [112]={npc="Ogtinc", tgt="Ogtinc"}, [113]={hint="Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath."}, [114]={npc="Ogtinc", tgt="Ogtinc"}, [115]={npc="Ogtinc", tgt="Ogtinc", tag="Gruppe empfohlen, Optional", desc="Der grüne Drache ist im Tempel von Atal'Hakkar."}, [116]={hint="Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", tag="Gruppe empfohlen, Optional", desc="Der grüne Drache ist im Tempel von Atal'Hakkar."}, [117]={npc="Ogtinc", tgt="Ogtinc", tag="Gruppe empfohlen, Optional", desc="Der grüne Drache ist im Tempel von Atal'Hakkar."}, [118]={text="Kehr zur Talrendisspitze zurück und flieg nach Astranaar, folge dann der Straße nach Norden in den Teufelswald."}, [119]={to="Astranaar", toA="{a:415}"}}},
    ["04-49"] = {grind={[1]={mob="Wächter von Jaedenar", note="Rund um den Eingang von Jaedenar; normale Gegner."}, [2]={mob="Kultist von Jaedenar", note="Stehen zwischen den Wächtern; Zauberwirker."}}, steps={[1]={text="Folge von Astranaar der Straße nach Norden in den Teufelswald.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [2]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [3]={npc="Grazle", tgt="Grazle"}, [4]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [5]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Gruppe empfohlen, Optional, Nur mit Material"}, [6]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [7]={npc="Taronn Redfeather", tgt="Taronn Redfeather"}, [8]={hint="Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt."}, [9]={npc="Grazle", tgt="Grazle"}, [10]={npc="Grazle", tgt="Grazle"}, [11]={hint="Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Bluewind im Teufelswald zurück, sobald die Aufgabe erledigt ist."}, [12]={hint="Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt."}, [13]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [14]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [15]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [16]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [17]={hint="Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt."}, [18]={desc="Töte Gegner bei 35, 59 in Jaedenar."}, [19]={hint="Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr das Shatter Scar-Tal erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Fel-Wasser gefüllt sind, kehrt zu Taronn Redfeather im Teufelswald zurück."}, [20]={hint="Eridan Bluewind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt."}, [21]={npc="Flöte des Xavaric", npcObj=true, desc="Rechtsklicke Flöte des Xavaric im Rucksack, um die Quest anzunehmen."}, [22]={hint="Bringt die Flöte von Xavaric und 5 Jadefeuerteufelsbinder zu Eridan Bluewind im südlichen Teil des Teufelswalds."}, [23]={hint="Bringt 15 Einheiten Blutharz zu Arathandris Silversky im Teufelswald."}, [24]={nodeA="{a:1998}", node="Talonbranch Glade"}, [25]={npc="Nafien", tgt="Nafien"}, [26]={npc="Nafien", tgt="Nafien"}, [27]={hint="Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück."}, [28]={npc="Nafien", tgt="Nafien"}, [29]={npc="Nafien", tgt="Nafien", desc="Gib sie bei Salfa ab, wenn du durch die Holzschlundfeste nach Winterquell kommst."}, [30]={text="Betritt hier die Höhle der Holzschlundfeste und geh hindurch, dahinter liegt Winterspring."}, [31]={node="Moonglade", desc="In der Höhle der Holzschlundfeste führt eine Abzweigung nach Moonglade; geh zuerst hinüber, schalte den Flugpunkt frei und kehr dann in die Höhle zurück, um nach Winterspring zu gehen. Für den Abschnitt im Hyjal später fliegst du nach Moonglade."}, [32]={npc="Salfa", tgt="Salfa"}, [33]={npc="Salfa", tgt="Salfa"}, [34]={npc="Donova Snowden", tgt="Donova Snowden"}, [35]={npc="Donova Snowden", tgt="Donova Snowden"}, [36]={npc="Meggi Peppinrocker", tgt="Meggi Peppinrocker"}, [37]={npc="Jessica Redpath", tgt="Jessica Redpath"}, [38]={nodeA="{a:2255}", node="Everlook"}, [39]={npc="Niby der Allmächtige", tgt="Niby der Allmächtige"}, [40]={npc="Impsy", tgt="Impsy"}, [41]={npc="Impsy", tgt="Impsy", desc="Teufelsstoff ×1 gibt es im Auktionshaus."}, [42]={hint="Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald."}, [43]={npc="Impsy", tgt="Impsy"}, [44]={npc="Impsy", tgt="Impsy"}, [45]={hint="Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald."}, [46]={npc="Impsy", tgt="Impsy"}, [47]={npc="Impsy", tgt="Impsy", tag="Gruppe empfohlen, Optional"}, [48]={hint="Bringt 6 Voodoofedern von den Trollen aus dem versunkenen Tempel.", tag="Gruppe empfohlen, Optional"}, [49]={npc="Impsy", tgt="Impsy", tag="Gruppe empfohlen, Optional"}, [50]={npc="Impsy", tgt="Impsy"}, [51]={hint="Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt."}, [52]={npc="Impsy", tgt="Impsy"}, [53]={npc="Impsy", tgt="Impsy", desc="Kroshius ist im Norden des Teufelswalds. Du brauchst eine Gruppe."}, [54]={hint="Sucht im Shattered Scar-Tal im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern.", desc="Kroshius ist im Norden des Teufelswalds. Du brauchst eine Gruppe."}, [55]={npc="Niby der Allmächtige", tgt="Niby der Allmächtige", desc="Kroshius ist im Norden des Teufelswalds. Du brauchst eine Gruppe."}}},
    ["05-d14"] = {name="Der Tempel von Atal'Hakkar", entrance="Sümpfe des Elends 69.50, 52.50 (Wegmarke außen am Tempelgebäude)", steps={[1]={npc="Angelas Moonbreeze", tgt="Angelas Moonbreeze", tag="Dungeon-Vorquest"}, [2]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", tag="Dungeon-Vorquest"}, [3]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", tag="Dungeon-Vorquest"}, [4]={hint="Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet.", tag="Dungeon-Vorquest"}, [5]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", tag="Dungeon-Vorquest"}, [6]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", preText="Der runde Stein"}, [7]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", preText="Der runde Stein"}, [8]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon-Vorquest"}, [9]={hint="Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück.", tag="Dungeon-Vorquest", desc="Tötet Talschreier an der Küste der Insel des Schreckens in Feralas. Benutzt Yeh'kinyas Dornbusch auf jedem Kadaver und sprecht mit dem erscheinenden Geist, bis das Questlog drei Geister zählt."}, [10]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon-Vorquest"}, [11]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon-Vorquest"}, [12]={hint="Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris.", tag="Dungeon-Vorquest"}, [13]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon-Vorquest"}, [14]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon-Vorquest"}, [15]={hint="Bringt das uralte Ei zu Yeh'kinya nach Tanaris.", tag="Dungeon-Vorquest"}, [16]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon-Vorquest"}, [17]={npc="Yeh'kinya", tgt="Yeh'kinya", preText="Das uralte Ei"}, [18]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", tag="Dungeon-Vorquest"}, [19]={hint="Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben.", tag="Dungeon-Vorquest"}, [20]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", tag="Dungeon-Vorquest"}, [21]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", tag="Dungeon-Vorquest"}, [22]={hint="Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem.", tag="Dungeon-Vorquest"}, [23]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", tag="Dungeon-Vorquest"}, [24]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", tag="Optional", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [25]={npc="Bruder Joshua", tgt="Bruder Joshua", tag="Dungeon-Vorquest"}, [26]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon-Vorquest"}, [27]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon-Vorquest"}, [28]={hint="Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", tag="Dungeon-Vorquest"}, [29]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon-Vorquest"}, [30]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon-Vorquest"}, [31]={hint="Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", tag="Dungeon-Vorquest"}, [32]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon-Vorquest"}, [33]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [34]={npc="Dorion", tgt="Dorion", tag="Dungeon-Vorquest"}, [35]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon-Vorquest"}, [36]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon-Vorquest"}, [37]={hint="Bringt ein perfektes Rennergeweih zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath.", tag="Dungeon-Vorquest"}, [38]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon-Vorquest"}, [39]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon-Vorquest"}, [40]={hint="Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", tag="Dungeon-Vorquest"}, [41]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon-Vorquest"}, [42]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="Der grüne Drache ist im Tempel von Atal'Hakkar."}, [43]={text="Eingang: Der Tempel von Atal'Hakkar"}, [44]={hint="Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends.", desc="Ort: Nimm den flachen rechten Weg nach unten. Finde den Altar von Hakkar auf dem Ring.", spot="Nimm den flachen rechten Weg nach unten. Finde den Altar von Hakkar auf dem Ring."}, [45]={npc="Altar von Hakkar", npcObj=true, spot="Altar von Hakkar im Ringkorridor der unteren Ebene"}, [46]={hint="Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt.", desc="Eine falsche Reihenfolge löst eine Falle aus. Ort: Klicke im unteren Ringgang der Reihe nach die sechs Statuen an und geh dann in die Mitte, um den Boss zu töten. Reihenfolge: Süd → Nord → Südwest → Südost → Nordwest → Nordost.", spot="Aktiviere im unteren Ring nacheinander die sechs Statuen und töte dann den Boss in der Mitte."}, [47]={npc="Götze von Hakkar", npcObj=true, spot="Mitte der unteren Ebene: die Hakkari-Statue"}, [48]={hint="Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris.", desc="Geht zuerst alle gemeinsam in den Raum und startet dann das Ereignis. Nimm den westlichen Gang zu Hakkars Raum. Ort: Geh von der Opfergrube den Westgang in Hakkars Raum, sammelt euch und benutzt dann das Ei. Reihenfolge: Der Westgang führt zu Hakkar, der Ostgang zu Jammal'an.", spot="Nimm aus der Opfergrube den Westgang in Hakkars Raum. Sammle die Gruppe, bevor du die Eier benutzt."}, [49]={hint="Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück.", tag="Optional"}, [50]={hint="Tötet Morphaz im versunkenen Tempel von Atal'Hakkar und bringt Greta Mosshoof im Teufelswald sein Blut. Der Eingang zum versunkenen Tempel liegt in den Sümpfen des Elends.", tag="Optional"}, [51]={hint="Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", tag="Optional"}, [52]={npc="Essenz des Eranikus", npcObj=true, tag="Optional, Gruppe empfohlen", desc="Besiegt den Endboss und rechtsklickt auf die selbst erbeutete Essenz, um die Quest anzunehmen."}, [53]={hint="Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet.", tag="Optional, Gruppe empfohlen", spot="Legt die Essenz neben dem Endboss in den Essenzborn."}, [54]={npc="Essenz-Born", npcObj=true, tag="Optional, Gruppe empfohlen", spot="Legt die Essenz neben dem Endboss in den Essenzborn."}, [55]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [56]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", tag="Optional", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [57]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="Der grüne Drache ist im Tempel von Atal'Hakkar."}, [58]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Optional, Nur mit Material"}}},
    ["04-50"] = {steps={[1]={to="Feathermoon Stronghold", toA="{a:1116}"}, [2]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [3]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [4]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [5]={npc="Gregan Brewspewer", tgt="Gregan Brewspewer"}, [6]={hint="Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück.", desc="Gregan gibt dir einen Köder: Lock damit Miblon weg, schnapp dir die Evowurzel und tausch sie danach gegen das Videre-Elixier ein."}, [7]={npc="Felsbeißer", tgt="Felsbeißer"}, [8]={hint="Aktiviert Troyas Stock und findet den Equinex-Monolithen.", desc="Weiter hinten kannst du hochspringen und abkürzen."}, [9]={npc="Equinex-Monolith", npcObj=true, desc="Benutze den Stab in deinem Rucksack."}, [10]={npc="Equinex-Monolith", npcObj=true}, [11]={npc="Shay Leafrunner", tgt="Shay Leafrunner"}, [12]={npc="Shay Leafrunner", tgt="Shay Leafrunner", tag="Eskorte"}, [13]={hint="Nehmt Shays Glocke aus der Truhe.", tag="Eskorte"}, [14]={npc="Felsbeißer", tgt="Felsbeißer"}, [15]={hint="Bringt Pratt McGrubben in der Festung Feathermoon 10 Wutschrammyetibälge."}, [16]={npc="Makelloser Yetibalg", npcObj=true, tag="Optional", desc="Droppt beim Töten der Yetis ein Makelloser Yetibalg, rechtsklicke ihn."}, [17]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [18]={npc="Pratt McGrubben", tgt="Pratt McGrubben", tag="Optional"}, [19]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}}},
    ["04-51"] = {grind={[1]={mob="Pfadfinder der Winterfelle", note="Das Lager der Winterfelle nördlich von Donova; dieselben Gegner wie für die Furbolg-Quest."}, [2]={mob="Totemiker der Winterfelle", note="Dasselbe Lager; Zauberwirker."}}, steps={[1]={bindA="{a:415}", desc="Hat dein Ruhestein Abklingzeit, flieg von der Festung Feathermoon nach Astranaar (über Auberdine) und geh dann nach Norden in den Teufelswald."}, [2]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [3]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [4]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [5]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Gruppe empfohlen, Optional, Nur mit Material"}, [6]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [7]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [8]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [9]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [10]={npc="Taronn Redfeather", tgt="Taronn Redfeather"}, [11]={hint="Beute von: Verfluchter Brühschlammer, Besudelter Brühschlammer, Übler Brühschlammer", desc="Sie droppen nur, solange du das Cenarische Leuchtfeuer im Rucksack hast; die Eisenschnabeleulen sind westlich des Smaragdrefugiums, die Schleime an den Teichen im Nordwesten."}, [12]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [13]={npc="Donova Snowden", tgt="Donova Snowden", desc="Flieg zurück nach Astranaar und dann zur Nachtlaublichtung, geh dann nach Norden durch die Holzschlundfeste nach Winterspring."}, [14]={npc="Donova Snowden", tgt="Donova Snowden", desc="Trink am Friedhof vor Gadgetzan das Videre-Elixier und such als Geist Gaeriyan auf."}, [15]={npc="Donova Snowden", tgt="Donova Snowden"}, [16]={npc="Donova Snowden", tgt="Donova Snowden"}, [17]={desc="Töte Furbolgs bei 32, 36 im Lager der Winterfelle."}, [18]={npc="Gregor Greystone", tgt="Gregor Greystone"}, [19]={npc="Gregor Greystone", tgt="Gregor Greystone"}, [20]={to="Ratchet", toA="{a:392}", desc="Du steigst an der Talrendisspitze um."}, [21]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix"}, [22]={npc="Islen Waterseer", tgt="Islen Waterseer"}, [23]={npc="Islen Waterseer", tgt="Islen Waterseer"}, [24]={to="Gadgetzan", toA="{a:976}"}, [25]={npc="Alchimist Pestlezugg", tgt="Alchimist Pestlezugg"}, [26]={text="Bleib nach dem Trinken des Videre-Elixiers tot und such den Quest-NPC als Geist."}, [27]={npc="Gaeriyan", tgt="Gaeriyan"}, [28]={npc="Gaeriyan", tgt="Gaeriyan"}, [29]={text="Kehr zu deiner Leiche zurück und belebe dich wieder."}, [30]={npc="Ein verdächtiger Grabstein", npcObj=true}, [31]={npc="Ein verdächtiger Grabstein", npcObj=true}, [32]={npc="Tran'rek", tgt="Tran'rek"}, [33]={npc="Alchimist Pestlezugg", tgt="Alchimist Pestlezugg", tag="Optional"}}},
    ["04-52"] = {name="Un'Goro-Krater", steps={[1]={to="Marshal's Refuge", toA="{a:541}"}, [2]={npc="Linken", tgt="Linken"}, [3]={npc="Linken", tgt="Linken"}, [4]={npc="J.D. Collie", tgt="J.D. Collie"}, [5]={npc="J.D. Collie", tgt="J.D. Collie"}, [6]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [7]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal", tag="Optional, If offered", desc="Buchlieferquest: Nimm sie an, wenn der NPC sie anbietet, und bring das Buch zum Gipfel der Ewigkeit im Hyjal. Siehst du die Quest nicht, überspring sie."}, [8]={hint="Sammelt 12 Proben superklebrigen Teer für Tran'rek in Gadgetzan."}, [9]={npc="Krakle", tgt="Krakle"}, [10]={hint="Sammelt 9 Proben Un'Goro-Asche von den Feuerelementare am Vulkan im Un'Goro Krater ein und bringt die Proben zu Liv Rizzlefix in Ratchet."}, [11]={hint="Krakle im Un'Goro Krater möchte, dass Ihr den heißesten Bereich des Feuerfedergrats findet.", desc="Folgt dem Pfad auf den Feuersäulengrat und messt die Temperatur. Sammelt unterwegs Asche, falls ihr die Quest habt. Nach der Messung folgt dem Pfad zu Ringo. Führt ihn nach Beginn der Eskorte direkt nach Norden zu Marshals Zuflucht."}, [12]={npc="Ringo", tgt="Ringo", desc="Eskortquest: In der Gruppe erst annehmen, wenn alle gleich weit sind, und automatisches Annehmen ausschalten."}, [13]={npc="Ringo", tgt="Ringo"}, [14]={hint="Führt Ringo zu Spraggle Frock in Marshals Zuflucht.", tag="Eskorte", desc="Bring Ringo zurück zu Marshals Zuflucht. Er wird unterwegs ohnmächtig; benutze dann Spraggles Feldflasche an ihm."}, [15]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [16]={npc="A-Me 01", tgt="A-Me 01"}, [17]={npc="A-Me 01", tgt="A-Me 01"}, [18]={hint="Sucht ein Mithrilgehäuse und bringt es zu A-Me 01 im Un'Goro Krater.", desc="Kauf das Mithrilgehäuse vorher im Auktionshaus oder lass es einen Ingenieur herstellen."}, [19]={npc="A-Me 01", tgt="A-Me 01"}, [20]={hint="Bringt U'chas Pelz zu Torwa Pathfinder am Eingang des Un'Goro Kraters."}, [21]={npc="A-Me 01", tgt="A-Me 01"}, [22]={hint="Begleitet A-Me 01 zu Karna Remtravel im Un'Goro Krater.", tag="Eskorte", desc="Eskortiere A-Me 01 zurück zu Karna Remtravel; Gegner am Weg greifen ihn an, also beschütze ihn."}, [23]={npc="Karna Remtravel", tgt="Karna Remtravel"}, [24]={hint="Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün. Bringt sie zu J. D. Collie in Marshals Zuflucht.", desc="Kristalle in vier Farben liegen überall im Krater verstreut am Boden; sammle nach, was dir von vorhin noch fehlt."}, [25]={npc="J.D. Collie", tgt="J.D. Collie"}, [26]={npc="J.D. Collie", tgt="J.D. Collie"}, [27]={npc="J.D. Collie", tgt="J.D. Collie"}, [28]={npc="J.D. Collie", tgt="J.D. Collie"}, [29]={hint="Findet den Standort des nördlichen Kristallpylonen im Un'Goro Krater."}, [30]={hint="Findet den Standort des östlichen Kristallpylonen im Un'Goro Krater."}, [31]={hint="Bringt eine Gorishiduftdrüse und 5 Un'Goro-Erdproben zu Alchimist Pestlezugg in Gadgetzan.", tag="Optional", desc="Sucht im Süden beim Schwarmbau nach Gorishiwespen oder Gorishiarbeitern für die Duftdrüse. Sammelt unterwegs fünf Portionen Erde aus Erdhaufen. Allein könnt ihr einzelne Insekten bekämpfen, ohne tiefer zur Königin vorzudringen."}, [32]={hint="Bringt eine Gorishiduftdrüse und 5 Un'Goro-Erdproben zu Alchimist Pestlezugg in Gadgetzan.", tag="Optional", desc="Sucht im Süden beim Schwarmbau nach Gorishiwespen oder Gorishiarbeitern für die Duftdrüse. Sammelt unterwegs fünf Portionen Erde aus Erdhaufen. Allein könnt ihr einzelne Insekten bekämpfen, ohne tiefer zur Königin vorzudringen."}, [33]={hint="Findet den Standort des westlichen Kristallpylonen."}, [34]={npc="Krakle", tgt="Krakle"}, [35]={npc="Krakle", tgt="Krakle"}, [36]={npc="J.D. Collie", tgt="J.D. Collie"}, [37]={npc="J.D. Collie", tgt="J.D. Collie"}, [38]={npc="J.D. Collie", tgt="J.D. Collie"}, [39]={npc="J.D. Collie", tgt="J.D. Collie"}, [40]={npc="J.D. Collie", tgt="J.D. Collie"}, [41]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [42]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [43]={hint="Sammelt Blutkappenpilze und Gorishistachel und kehrt zu Torwa Pathfinder im Un'Goro Krater zurück."}, [44]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [45]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [46]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [47]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Gruppe empfohlen, Optional"}, [48]={hint="Beschafft Euch eine Fäulnisranke von dem Wächter auf dem Grund des versunkenen Tempels und kehrt zu Torwa Pathfinder zurück.", tag="Gruppe empfohlen, Optional"}, [49]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Gruppe empfohlen, Optional"}, [50]={text="Seid Ihr noch im Norden und habt bei Torwa nichts zu erledigen, prüft die Flugkarte in Marschalls Zuflucht und fliegt nach Gadgetzan, wenn das Ziel verfügbar ist. Wollt Ihr U'chas Pelz abgeben oder Torwas Druidenquests erledigen, sucht ihn zuerst im Südosten auf. Von Torwa aus oder wenn kein Flug verfügbar ist, nehmt den südöstlichen Aufstieg nach Tanaris und folgt dem Weg nach Nordosten bis Gadgetzan."}, [51]={npc="Tran'rek", tgt="Tran'rek"}, [52]={npc="Alchimist Pestlezugg", tgt="Alchimist Pestlezugg", tag="Optional"}, [53]={to="Ratchet", toA="{a:392}", desc="Du steigst in Theramore um."}, [54]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix"}, [55]={bindA="{a:415}"}, [56]={to="Auberdine"}, [57]={text="Binde deinen Ruhestein im Gasthaus von Auberdine bei Gastwirtin Shaussiy (37.04, 44.13)."}, [58]={to="Rut'theran Village", toA="{a:702}"}, [59]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [60]={text="Geh in Rut'theran durch das Portal nach Darnassus."}, [61]={hint="Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück."}, [62]={text="Geh in Darnassus durch das Portal zurück nach Rut'theran."}, [63]={to="Astranaar", toA="{a:415}"}, [64]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [65]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Optional, If offered", desc="Briefliefer-Quest: Nimm sie an, wenn der NPC sie anbietet, und bring den Brief in den Hyjal zum Einsiedler Ketharas. Siehst du die Quest nicht, überspring sie."}, [66]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [67]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [68]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [69]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [70]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [71]={hint="Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Bluewind im Teufelswald.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [72]={npc="Eridan Bluewind", tgt="Eridan Bluewind", tag="Optional"}, [73]={text="Folge vom Smaragdrefugium der Straße nach Süden zurück nach Astranaar und flieg nach Auberdine. Du hast den Ruhestein gerade erst in Ratchet benutzt, er hat also wahrscheinlich noch Abklingzeit; ist er schon bereit, nimm ihn direkt nach Auberdine."}, [74]={to="Menethil Harbor", toA="{a:150}", from="Auberdine", desc="Nimm in Auberdine das Schiff nach Menethil. Steig am nächsten Halt aus."}, [75]={to="Ironforge"}, [76]={npc="Historiker Karnik", tgt="Historiker Karnik"}, [77]={npc="Historiker Karnik", tgt="Historiker Karnik"}, [78]={npc="Hochforscher Magellas", tgt="Hochforscher Magellas"}, [79]={npc="Hochforscher Magellas", tgt="Hochforscher Magellas"}, [80]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus"}, [81]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus"}, [82]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus"}}},
    ["05-d11"] = {name="Blackrocktiefen", entrance="Sengende Schlucht 34.80, 85.30", pickup="Bildet auf der Hauptroute nach eurem zweiten Besuch in Un'Goro eine Gruppe in Eisenschmiede. Als Nächstes geht es in die Brennende Steppe. Findet ihr schon in der Sengenden Schlucht eine Gruppe, betretet den Schwarzfels am Südende der Schlucht.", pickupS={{"Bildet auf der Hauptroute nach eurem zweiten Besuch in Un'Goro eine Gruppe in Eisenschmiede"}, {"Als Nächstes geht es in die Brennende Steppe"}, {"Findet ihr schon in der Sengenden Schlucht eine Gruppe, betretet den Schwarzfels am Südende der Schlucht"}}, tips={{k="動線", text="Fliegt von Eisenschmiede zur Thoriumspitze und betretet den Schwarzfels am Südende der Sengenden Schlucht. Fehlt die Flugverbindung, verlasst Dun Morogh im Osten nach Loch Modan. Zieht nach Süden ins Ödland und dann westwärts an Kargath vorbei in die Sengende Schlucht. → Findet ihr in Winterquell eine Gruppe, fliegt nach Auberdine. Ohne Flugverbindung geht ihr durch die Holzschlundfeste zurück in den Teufelswald und durch das Eschental nach Auberdine an der Dunkelküste. Nehmt das Schiff nach Sturmwind und fliegt zur Thoriumspitze. Fehlen euch die östlichen Flugpunkte, geht von Sturmwind durch den Wald von Elwynn ins Rotkammgebirge. Folgt von Seenhain der Straße nach Norden in die Brennende Steppe und zieht nach Westen in den Schwarzfels. → Für die Hauptroute in der Brennenden Steppe verlasst ihr den Schwarzfels durch das Südtor und folgt der Straße nach Osten zu Morgans Wacht. → Für den Rückweg zur Festung Feathermoon nutzt euren Ruhestein, wenn er bereit und an Astranaar gebunden ist. Andernfalls geht von der Brennenden Steppe durch das Rotkammgebirge und den Wald von Elwynn zum Hafen von Sturmwind. Nehmt das Schiff nach Auberdine und fliegt zur Festung Feathermoon. Ohne Flugverbindung geht ihr vom Eschental durch das Steinkrallengebirge und Desolace nach Feralas und nehmt am Anleger an der Westküste das Schiff zur Insel."}}, steps={[1]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright", desc="Sprecht im Schwarzfels als Geist mit Franclorn. Nehmt den ersten Teil an, gebt ihn ab und nehmt den zweiten Teil an, bevor ihr euch wiederbelebt. Die Zugänge zum Berg stehen auf dieser Seite."}, [2]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [3]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [4]={text="Eingang: Blackrocktiefen"}, [5]={hint="Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright."}, [6]={npc="Denkmal für Franclorn Forgewright", npcObj=true, desc="Gebt hier das Dunkeleisenerbe ab. Für die Brennende Steppe nehmt ihr das Südtor des Schwarzfels. Für den Rückweg nach Kalimdor folgt den Hinweisen zu Schiff und Ruhestein auf dieser Seite."}}},
    ["04-54"] = {steps={[1]={text="Hast du Morgans Wacht freigeschaltet, flieg direkt von Ironforge dorthin. Sonst flieg nach Seenhain und folge der Straße nach Norden in die Brennende Steppe; Morgans Wacht liegt gleich am Eingang.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [2]={nodeA="{a:2418}", node="Morgan's Vigil"}, [3]={npc="Oralius", tgt="Oralius"}, [4]={npc="Oralius", tgt="Oralius"}, [5]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Gruppe empfohlen, Optional"}, [6]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil"}, [7]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [8]={hint="Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt."}, [9]={hint="Bringt Maxwort Uberglint in der brennenden Steppe die Abschrift der Schrifttafel."}, [10]={hint="Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen und kehrt zu Oralius zurück, wenn Ihr fertig seid."}, [11]={hint="Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe."}, [12]={hint="Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist.", tag="Gruppe empfohlen, Optional", desc="Die schwarze Drachenbrut und die Schwarzdrachen sind Elitegegner der Stufe 51-53."}, [13]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous"}, [14]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous"}, [15]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil"}, [16]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [17]={npc="Oralius", tgt="Oralius"}, [18]={npc="Oralius", tgt="Oralius"}, [19]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Gruppe empfohlen, Optional"}, [20]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn"}, [21]={hint="Sucht Gor'tesh irgendwo im Westen des Schreckensfelsens. Tötet Gor'tesh und bringt dann seinen abgehackten Kopf zu Oralius in der brennenden Steppe zurück."}, [22]={hint="Oralius will 50 Medaillons der Blackrock haben. Die Chancen stehen gut, dass man die Medaillons bei den Orcs in der brennenden Steppe findet."}, [23]={npc="Oralius", tgt="Oralius"}, [24]={npc="Oralius", tgt="Oralius"}, [25]={to="Lakeshire", toA="{a:69}", desc="Überspringst du Die wahren Meister, flieg direkt nach Sturmwind und überspring die nächsten zwei Schritte."}, [26]={npc="Magistrat Solomon", tgt="Magistrat Solomon"}, [27]={npc="Magistrat Solomon", tgt="Magistrat Solomon"}, [28]={to="Stormwind"}, [29]={npc="Wu Shen", tgt="Wu Shen", tag="Optional"}, [31]={npc="Lord Grayson Shadowbreaker", tgt="Lord Grayson Shadowbreaker", desc="Gib sie auf der Chillwindspitze in den Westlichen Pestländern ab."}, [33]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon"}, [34]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon"}, [35]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon"}, [36]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon"}, [37]={npc="Ausrufer Goodman", tgt="Ausrufer Goodman"}, [38]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [39]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [40]={hint="Tötet 7 Hölleneber in den verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück.", tag="Optional"}, [41]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [42]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [43]={hint="Merzt die Schattenanbeter in den verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück.", tag="Optional"}, [44]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [45]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Gruppe empfohlen, Optional"}, [46]={hint="Bringt die Voodoofedern der Trolle im versunkenen Tempel zu dem gefallenen Helden der Horde.", tag="Gruppe empfohlen, Optional"}, [47]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Gruppe empfohlen, Optional"}}},
    ["05-d26"] = {name="Untere Blackrockspitze", entrance="Brennende Steppe 29.40, 38.30 (Südeingang zum Blackrock)", pickup="Hol die Quests in Morgans Wacht und am Flammenkamm. Fehlt dir die Stufe, hol sie vor dem Lauf nach. Waffenschmiede bekommen Vosh'gajins Schlangenstein in Ewige Warte.", pickupS={{"Hol die Quests in Morgans Wacht und am Flammenkamm"}, {"Fehlt dir die Stufe, hol sie vor dem Lauf nach"}, {"Waffenschmiede bekommen Vosh'gajins Schlangenstein in Ewige Warte"}}, tips={{k="動線", text="Gemeinsames Portal → rechts hinab → Omokk → Vosh'gajin und Bijou → Voone → Mutter Glimmernetz → Halycon → Wyrmthalak."}, {k="說明", text="Bring erst Bijous Nachricht zu Marshal Maxwell. Heb dir seine drei Bosse für den nächsten Lauf auf. Ein Schlüssel für die obere Spitze pro Gruppe reicht.", s={{"Bring erst Bijous Nachricht zu Marshal Maxwell"}, {"Heb dir seine drei Bosse für den nächsten Lauf auf"}, {"Ein Schlüssel für die obere Spitze pro Gruppe reicht"}}}}, steps={[1]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn"}, [2]={npc="Kibler", tgt="Kibler"}, [3]={npc="Kibler", tgt="Kibler"}, [4]={npc="Struppiger John", tgt="Struppiger John", tag="Optional"}, [5]={npc="Kilram", tgt="Kilram", tag="Optional", desc="Nimm sie als Waffenschmied an, wenn du dich auf Äxte spezialisieren willst."}, [6]={text="Voraussetzung: Die verlorenen Schrifttafeln von Mosh'aru", tag="Optional"}, [7]={npc="Ausgrabungsleiter Ironboot", tgt="Ausgrabungsleiter Ironboot", tag="Optional", preText="Die verlorenen Schrifttafeln von Mosh'aru"}, [8]={text="Eingang: Untere Blackrockspitze"}, [9]={npc="Spitzel der Schmetterschilde", tgt="Spitzel der Schmetterschilde", tag="Optional", desc="Geh am Eingang rechts hinab. Über die Schuttrampe erreichst du Vaelan in einer Seitenkammer."}, [10]={npc="Warosh", tgt="Warosh", tag="Optional", desc="Überquere hinter dem Eingang zur unteren Spitze die erste Brücke."}, [11]={hint="Begebt Euch zur Blackrockspitze und erschlagt Schattenjägerin Vosh'gajin. Holt Vosh'gajins Schlangenstein und kehrt zu Kilram zurück.", tag="Optional", desc="Ort: Geh an Omokk vorbei durch den Gang und such Schattenjägerin Vosh'gajin. Reihenfolge: Töte zuerst Vosh'gajin und such dann Bijou am Hang in ihrem Raum.", spot="Geh an Omokk vorbei und folge dem Tunnel zu Schattenjägerin Vosh'gajin."}, [12]={hint="Bringt Ausgrabungsleiter Ironboot in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru.", tag="Optional", desc="Ort: Je eine Tafel bei Vosh'gajin und bei Voone.", spot="Je eine Tafel bei Vosh'gajin und bei Voone."}, [13]={npc="Bijou", tgt="Bijou", desc="Folg bei Vosh'gajin der Rampe zu Bijou."}, [14]={hint="Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!", desc="Ort: Im Gang zwischen den Orcs und dem Spinnenbereich in der unteren Spitze.", spot="Im Gang zwischen den Orcs und dem Spinnenbereich in der unteren Spitze."}, [15]={npc="Bijou", tgt="Bijou", spot="Bijou auf der Rampe bei Vosh'gajin."}, [16]={npc="Bijou", tgt="Bijou", preText="Bijous Habseligkeiten"}, [17]={hint="Reist zur Blackrockspitze und sammelt 15 Spitzenspinnen-Eier für Kibler.", desc="Ort: Pass bei Mutter Glimmernetz auf die schlüpfenden Spinnen auf.", spot="Pass bei Mutter Glimmernetz auf die schlüpfenden Spinnen auf."}, [18]={hint="Ihr findet Mutter Glimmernetz im Herzen der Blackrockspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann.", tag="Optional", desc="Ort: Tief im Spinnenbereich.", spot="Tief im Spinnenbereich."}, [19]={hint="Begebt Euch zur Blackrockspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler.", desc="Ort: Lass die Welpen im Worgbereich am Leben.", spot="Lass die Welpen im Worgbereich am Leben."}, [20]={hint="Begebt Euch zur Blackrockspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs.", desc="Ort: Im Worgbereich der unteren Spitze.", spot="Im Worgbereich der unteren Spitze."}, [21]={hint="Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh.", tag="Optional", desc="Ort: Beim Tributhaufen vor Wyrmthalak.", spot="Beim Tributhaufen vor Wyrmthalak."}, [22]={npc="Warosh", tgt="Warosh", tag="Optional", spot="Warosh hinter der Eingangsbrücke."}, [23]={hint="Reist zur Blackrockspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.", tag="Optional", desc="Ort: Töte alle drei Anführer der unteren Spitze.", spot="Töte alle drei Anführer der unteren Spitze."}, [24]={npc="General Drakkisaths Befehl", npcObj=true, tag="Optional", desc="Plündere Wyrmthalaks Befehle und starte die Quest per Rechtsklick."}, [25]={hint="Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.", tag="Optional", desc="Die Droprate von Edelsteinen und Siegeln ist begrenzt. Sprich vorher mit deinen Mitspielern ab, wie ihr sie verteilt. Spielt ihr nur die obere Ebene, genügt es, wenn ein Gruppenmitglied das fertige Item hat. Ort: Plündere bei jedem der drei Könige einen Edelstein und such bei den Trash-Mobs unterwegs das Urtümliche Siegel. Reihenfolge: Omokk → Voone → Wyrmthalak.", spot="Plündere von jedem der drei Bosse einen Edelstein. Das rohe Siegel droppt von Gegnern auf dem Weg."}, [26]={npc="Spitzel der Schmetterschilde", tgt="Spitzel der Schmetterschilde", tag="Optional"}, [27]={npc="Spitzel der Schmetterschilde", tgt="Spitzel der Schmetterschilde", tag="Optional", preText="Siegel des Aufstiegs"}, [28]={npc="Struppiger John", tgt="Struppiger John", tag="Optional", desc="Geh nach der Vergiftung so schnell wie möglich zu Struppiger John."}, [29]={npc="Kibler", tgt="Kibler"}, [30]={npc="Kibler", tgt="Kibler"}, [31]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn"}, [32]={npc="Kilram", tgt="Kilram", tag="Optional"}, [33]={npc="Ausgrabungsleiter Ironboot", tgt="Ausgrabungsleiter Ironboot", tag="Optional"}, [34]={npc="Marshal Maxwell", tgt="Marshal Maxwell"}, [35]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [36]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional", desc="Plane einen zweiten Durchlauf ein.", preText="Nachricht an Maxwell"}, [37]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [38]={hint="Reist zum Drachensumpf in den Marschen von Dustwallow. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist.", tag="Optional", desc="Der Elite-Gegner sollte mit einer Gruppe angegangen werden. Hör auf zu kämpfen, bevor du den Drachen kontrollierst, und behalte genug Gesundheit."}, [39]={npc="Spitzel der Schmetterschilde", tgt="Spitzel der Schmetterschilde", tag="Optional", desc="Such Vaelan hinter dem Eingang der Unteren Blackrockspitze."}}},
    ["05-d25"] = {name="Düsterbruch: Nord", entrance="Feralas 62.50, 24.90 (Portal des Nordflügels)", pickup="Geh von der Festung Feathermoon in den Norden von Feralas. Prüfe, ob jemand den Mondsichelschlüssel hat. Für den Tributlauf kannst du Frostöl, einen Thoriumapparat, Runenstoffballen, Unverwüstliches Leder und Runenfaden mitbringen.", pickupS={{"Geh von der Festung Feathermoon in den Norden von Feralas"}, {"Prüfe, ob jemand den Mondsichelschlüssel hat"}, {"Für den Tributlauf kannst du Frostöl, einen Thoriumapparat, Runenstoffballen, Unverwüstliches Leder und Runenfaden mitbringen"}}, tips={{k="動線", text="Nordtor → Fengus' Hof → Knot und die Falle → Captain Kromcrush → König Gordok. Lass beim Tributlauf die Wachen am Leben und sprich nach dem König mit Kreeg und Kromcrush."}, {k="說明", text="Überspring Quest Die offene Rechnung der Gordok, wenn der Tributlauf gescheitert ist oder Kromcrush tot ist. Klassenbücher und Buchbände gibst du in der Bibliothek ab.", s={{"Überspring Quest Die offene Rechnung der Gordok, wenn der Tributlauf gescheitert ist oder Kromcrush tot ist"}, {"Klassenbücher und Buchbände gibst du in der Bibliothek ab"}}}}, steps={[1]={text="Eingang: Düsterbruch: Nord"}, [2]={npc="Beschädigte Falle", npcObj=true, tag="Optional"}, [3]={hint="Beute von: Marshal der Zorneshämmer, Drachenbrut der Zornkrallen, Blackhand-Eisenwache", tag="Optional", desc="Ort: Hinter Fengus' Hof findest du die Falle bei Knot.", spot="Hinter Fengus' Hof findest du die Falle bei Knot."}, [4]={npc="Beschädigte Falle", npcObj=true, tag="Optional"}, [5]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Optional"}, [6]={hint="Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Thimblejack. Momentan ist er im Gordokflügel von Düsterbruch angekettet.", tag="Optional", desc="Ort: Geh an Fengus vorbei, plündere oben das Ogertannin und such dann Knot bei der Falle.", spot="Geh an Fengus vorbei, plündere oben das Ogertannin und such dann Knot bei der Falle."}, [7]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Optional", spot="Hinter Fengus, bei der Falle: Knot Fingerhut"}, [8]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Optional"}, [9]={hint="Beute von: Schläger der Gordok, Magierlord der Gordok, Captain der Gordok", tag="Optional", desc="Ort: Geh hinter Fengus' Hof zu Knot neben der kaputten Falle und befreie ihn mit dem Schlüssel.", spot="Geh hinter Fengus' Hof zu Knot neben der kaputten Falle und befreie ihn mit dem Schlüssel."}, [10]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Optional", spot="Fengus' Hof, bei der kaputten Falle: Knot Fingerhut"}, [11]={npc="Stampfer Kreeg", tgt="Stampfer Kreeg", tag="Optional", desc="Hol dir im Tributlauf den Status König der Gordok und sprich dann mit Stampfer Kreeg."}, [12]={npc="Stampfer Kreeg", tgt="Stampfer Kreeg", tag="Optional"}, [13]={npc="Captain Kromcrush", tgt="Captain Kromcrush", tag="Optional", desc="Sprich nach dem Tributlauf mit Captain Kromcrush, wenn er noch lebt."}, [14]={npc="Captain Kromcrush", tgt="Captain Kromcrush", tag="Optional", desc="Melde dich nach deinem nächsten Tributlauf im Nordflügel bei Captain Kromcrush."}, [15]={npc="Garona: Eine Studie über Heimlichkeit und Verrat", npcObj=true, tag="Optional", desc="Bosse und Bücherstapel liefern die Bücher. Starte die Quest per Rechtsklick auf das Buch deiner Klasse."}, [16]={npc="Hüter des Wissens Kildrath", tgt="Hüter des Wissens Kildrath", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}, [17]={npc="Kodex der Verteidigung", npcObj=true, tag="Optional", desc="Bosse und Bücherstapel liefern die Bücher. Starte die Quest per Rechtsklick auf das Buch deiner Klasse."}, [18]={npc="Hüter des Wissens Kildrath", tgt="Hüter des Wissens Kildrath", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}, [19]={npc="Das Arkanistenkochbuch", npcObj=true, tag="Optional", desc="Bosse und Bücherstapel liefern die Bücher. Starte die Quest per Rechtsklick auf das Buch deiner Klasse."}, [20]={npc="Hüter des Wissens Kildrath", tgt="Hüter des Wissens Kildrath", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}, [21]={npc="Vom Licht und wie man es schwingt", npcObj=true, tag="Optional", desc="Bosse und Bücherstapel liefern die Bücher. Starte die Quest per Rechtsklick auf das Buch deiner Klasse."}, [22]={npc="Hüterin des Wissens Mykos", tgt="Hüterin des Wissens Mykos", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}, [23]={npc="Schatten einspannen", npcObj=true, tag="Optional", desc="Bosse und Bücherstapel liefern die Bücher. Starte die Quest per Rechtsklick auf das Buch deiner Klasse."}, [24]={npc="Hüterin des Wissens Mykos", tgt="Hüterin des Wissens Mykos", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}, [25]={npc="Das größte Volk von Jägern", npcObj=true, tag="Optional", desc="Bosse und Bücherstapel liefern die Bücher. Starte die Quest per Rechtsklick auf das Buch deiner Klasse."}, [26]={npc="Hüterin des Wissens Mykos", tgt="Hüterin des Wissens Mykos", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}, [27]={npc="Heiliger Fleischklops: Was das Licht Dir nicht erzählt", npcObj=true, tag="Optional", desc="Bosse und Bücherstapel liefern die Bücher. Starte die Quest per Rechtsklick auf das Buch deiner Klasse."}, [28]={npc="Hüter des Wissens Javon", tgt="Hüter des Wissens Javon", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}, [29]={npc="Frostschock und Du", npcObj=true, tag="Optional", desc="Bosse und Bücherstapel liefern die Bücher. Starte die Quest per Rechtsklick auf das Buch deiner Klasse."}, [30]={npc="Hüter des Wissens Javon", tgt="Hüter des Wissens Javon", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}, [31]={npc="Der Smaragdgrüne Traum", npcObj=true, tag="Optional", desc="Bosse und Bücherstapel liefern die Bücher. Starte die Quest per Rechtsklick auf das Buch deiner Klasse."}, [32]={npc="Hüter des Wissens Javon", tgt="Hüter des Wissens Javon", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}, [33]={npc="Nostros Kompendium des Drachentötens", npcObj=true, tag="Optional", desc="Bosse und Bücherstapel liefern die Bücher. Starte die Quest per Rechtsklick auf das Buch deiner Klasse."}, [34]={npc="Hüter des Wissens Lydros", tgt="Hüter des Wissens Lydros", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}, [35]={npc="Hüter des Wissens Lydros", tgt="Hüter des Wissens Lydros", tag="Optional", preText="Elfische Legenden"}, [36]={hint="Bringt ein Buchband der Schnelligkeit, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 2 mal das Blut von Helden, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum der Schnelligkeit zu erhalten.", tag="Optional"}, [37]={npc="Hüter des Wissens Lydros", tgt="Hüter des Wissens Lydros", tag="Optional"}, [38]={npc="Hüter des Wissens Lydros", tgt="Hüter des Wissens Lydros", tag="Optional", preText="Elfische Legenden"}, [39]={hint="Bringt ein Buchband des Fokus, 1 makellosen schwarzen Diamanten, 4 große glänzende Splitter und 2 mal Schattenhaut, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Fokus zu erhalten.", tag="Optional"}, [40]={npc="Hüter des Wissens Lydros", tgt="Hüter des Wissens Lydros", tag="Optional"}, [41]={npc="Hüter des Wissens Lydros", tgt="Hüter des Wissens Lydros", tag="Optional", preText="Elfische Legenden"}, [42]={hint="Bringt ein Buchband des Schutzes, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 1 ausgefranste Monstrositätenstickerei zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Schutzes zu erhalten.", tag="Optional"}, [43]={npc="Hüter des Wissens Lydros", tgt="Hüter des Wissens Lydros", tag="Optional"}}},
    ["05-d24"] = {name="Düsterbruch: West", entrance="Feralas 60.30, 30.20 (Portal im Westteil des Hofes)", pickup="Nimm auf Stufe 54 „Elfische Legenden\" bei der Gelehrten Runethorn in der Festung Feathermoon an. Den Mondsichelschlüssel für den West- und Nordflügel lässt Pusillin im Ostflügel fallen.", pickupS={{"Nimm auf Stufe 54 „Elfische Legenden\" bei der Gelehrten Runethorn in der Festung Feathermoon an"}, {"Den Mondsichelschlüssel für den West- und Nordflügel lässt Pusillin im Ostflügel fallen"}}, tips={{k="動線", text="Westtor → Tendris Wucherborke → Uralte Shen'dralar im Obergeschoss → fünf Kristallpylonen → Immol'thar → Prinz Tortheldrin in der Bibliothek."}, {k="說明", text="Gib die Klassenbücher in der Bibliothek ab. Für die Quest aus dem Nord-Tributlauf sprich zuerst mit Kromcrush und öffne dann die Truhe des Prinzen.", s={{"Gib die Klassenbücher in der Bibliothek ab"}, {"Für die Quest aus dem Nord-Tributlauf sprich zuerst mit Kromcrush und öffne dann die Truhe des Prinzen"}}}}, steps={[1]={npc="Gelehrter Runethorn", tgt="Gelehrter Runethorn"}, [2]={text="Eingang: Düsterbruch: West"}, [3]={npc="Uralte Shen'dralar", tgt="Uralte Shen'dralar", desc="Sprich auf der oberen Ebene von Düsterbruch West zuerst mit dem Uralten Shen'dralar."}, [4]={hint="Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.", desc="Säubere zuerst die fünf Kristalltürme. Ort: Säubere im Garten und im Obergeschoss die fünf Türme, geh durch die verschlossene Tür und töte Immol'thar und den Prinzen. Reihenfolge: Fünf Türme → Immol'thar → der Prinz in der Bibliothek.", spot="Räum im Garten und auf der oberen Ebene die fünf Pylonen und geh dann durch die verschlossene Tür zu Immol'thar und dem Prinzen."}, [5]={npc="Uralte Shen'dralar", tgt="Uralte Shen'dralar", spot="Bibliothek: Uralte Shen'dralar"}, [6]={npc="Uralte Shen'dralar", tgt="Uralte Shen'dralar", preText="Der innere Wahnsinn"}, [7]={hint="Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!", desc="Ort: Geh vom Käfig von Immol'thar durch den Gang zur Bibliothek. Such unter der Treppe die Truhe.", spot="Geh vom Käfig von Immol'thar durch den Gang zur Bibliothek. Such unter der Treppe die Truhe."}, [8]={npc="Shen'dralar Schatz", npcObj=true, spot="Shen'dralar-Truhe unter der Bibliothekstreppe"}, [9]={hint="Sucht in Düsterbruch nach Telmius Dreamseeker. Meldet Euch anschließend bei der Gelehrten Runethorn in Feathermoon.", desc="Ort: Geh vom Käfig durch den Gang in die Bibliothek und such neben den Regalen die Überreste.", spot="Geh vom Käfig durch den Gang in die Bibliothek und such neben den Regalen die Überreste."}, [10]={hint="Findet die Stulpen der Gordokmacht und bringt sie zu Captain Kromcrush in Düsterbruch.", tag="Optional", desc="Ort: In der Bibliothek des Westflügels, hinter dem Prinzen.", spot="In der Bibliothek des Westflügels, hinter dem Prinzen."}, [11]={npc="Gelehrter Runethorn", tgt="Gelehrter Runethorn"}}},
    ["05-d23"] = {name="Düsterbruch: Ost", entrance="Feralas 64.80, 30.20 (Portal in der Ostmauer der Arena)", pickup="Sprich ab Stufe 54 mit Latronicus Moonspear in der Festung Feathermoon. Besuche Azj'Tordin bei Lariss' Pavillon auf dem Weg zum Osttor. Hol die Quests vor dem Gruppenlauf nach, falls deine Stufe noch zu niedrig ist.", pickupS={{"Sprich ab Stufe 54 mit Latronicus Moonspear in der Festung Feathermoon"}, {"Besuche Azj'Tordin bei Lariss' Pavillon auf dem Weg zum Osttor"}, {"Hol die Quests vor dem Gruppenlauf nach, falls deine Stufe noch zu niedrig ist"}}, tips={{k="動線", text="Osttor → verfolge Pusillin für den Schlüssel → Lethtendris → Alzzin. Als Magier mit der Wasserquest gehst du durch den Wasserlauf zu Hydrobrut."}, {k="說明", text="Das Osttor ist ohne Schlüssel zugänglich. Mach „Ein Reliquiar der Reinheit\" nur, wenn du die gebietsübergreifende Kette schon angefangen hast. Pusillin im Ostflügel lässt den Mondsichelschlüssel für den West- und Nordflügel fallen.", s={{"Das Osttor ist ohne Schlüssel zugänglich"}, {"Mach „Ein Reliquiar der Reinheit\" nur, wenn du die gebietsübergreifende Kette schon angefangen hast"}, {"Pusillin im Ostflügel lässt den Mondsichelschlüssel für den West- und Nordflügel fallen"}}}}, steps={[1]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [2]={npc="Azj'Tordin", tgt="Azj'Tordin"}, [3]={npc="Rabine Saturna", tgt="Rabine Saturna", tag="Optional"}, [4]={hint="Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nighthaven, Moonglade zurück.", tag="Optional"}, [5]={npc="Rabine Saturna", tgt="Rabine Saturna", tag="Optional"}, [6]={npc="Rabine Saturna", tgt="Rabine Saturna", tag="Optional", preText="Ein Reliquiar der Reinheit"}, [7]={npc="Hüter des Wissens Lydros", tgt="Hüter des Wissens Lydros", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}, [8]={text="Eingang: Düsterbruch: Ost"}, [9]={hint="Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben.", desc="Sprich am Osttor mit Pusillin und folg ihm den Gang entlang bis ans Ende. Sprich jedes Mal mit ihm, wenn er anhält."}, [10]={hint="Bringt Lethtendris' Netz zu Latronicus Moonspear in der Festung Feathermoon, in Feralas.", desc="Ort: Nimm den oberen Durchgang vom Garten zur Plattform von Lethtendris.", spot="Nimm den oberen Durchgang vom Garten zur Plattform von Lethtendris."}, [11]={hint="Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach, werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Requiliar der Reinheit, um darin den Splitter sicher zu versiegeln und bringt das versiegelte Reliquiar zu Rabine Saturna in Nighthaven, Moonglade.", tag="Optional", desc="Ort: In Alzzins Raum.", spot="In Alzzins Raum."}, [12]={hint="Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz, zum Hüter des Wissens Lydros im Athenaeum zurück.", tag="Optional", desc="Ort: Nimm den unteren Wasserweg in Düsterbruch Ost. Töte Hydrobrut am Pool.", spot="Nimm den unteren Wasserweg in Düsterbruch Ost. Töte Hydrobrut am Pool."}, [13]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [14]={npc="Azj'Tordin", tgt="Azj'Tordin"}, [15]={npc="Rabine Saturna", tgt="Rabine Saturna", tag="Optional"}, [16]={npc="Hüter des Wissens Lydros", tgt="Hüter des Wissens Lydros", tag="Optional", desc="Nimm vom Eingangshof des Nordflügels die Seitentür zur Bibliothek."}}},
    ["04-55"] = {steps={[1]={to="Aerie Peak", toA="{a:348}", desc="Hast du die Chillwindspitze freigeschaltet, flieg direkt dorthin und überspring den nächsten Schritt. Ist der Aerie Peak nicht auf deiner Flugkarte, flieg nach Southshore und lauf auf demselben Weg wie bei der Hinterland-Etappe nach Osten zum Aerie Peak."}, [2]={text="Geh vom Aerie Peak auf dem Bergpfad nach Norden in die Südostecke der Westlichen Pestländer (65.30, 86.80) und folge dann der Straße nach Westen zur Chillwindspitze.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [3]={nodeA="{a:3197}", node="Chillwind Camp"}, [4]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [5]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [6]={hint="Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den westlichen Pestländern."}, [7]={npc="Hohepriester Thel'danis", tgt="Hohepriester Thel'danis"}, [8]={npc="Hohepriester Thel'danis", tgt="Hohepriester Thel'danis"}, [9]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [10]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist", tag="Gruppe empfohlen, Optional", desc="Gib sie ab, um den Machtstein zu erhalten."}, [11]={hint="Bringt die Voodoofedern zu Ashlam Valorfist.", tag="Gruppe empfohlen, Optional", desc="Gib sie ab, um den Machtstein zu erhalten."}, [12]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist", tag="Gruppe empfohlen, Optional", desc="Gib sie ab, um den Machtstein zu erhalten."}, [13]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [14]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [15]={npc="Argentumoffizier Pureheart", tgt="Argentumoffizier Pureheart"}, [16]={npc="Argentumoffizier Pureheart", tgt="Argentumoffizier Pureheart"}, [17]={npc="Argentumoffizier Pureheart", tgt="Argentumoffizier Pureheart"}, [18]={npc="Argentumoffizier Pureheart", tgt="Argentumoffizier Pureheart", desc="Eine Briefliefer-Quest; gib sie in der Nähe des Eingangs zum Hyjal ab."}, [19]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [20]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [21]={hint="Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Sorrow Hill."}, [22]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [23]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [24]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [25]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [26]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [27]={hint="Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren."}, [28]={hint="Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}, [29]={npc="Geißelkessel", npcObj=true}, [30]={npc="Geißelkessel", npcObj=true}, [31]={npc="Janice Teufelsstein", tgt="Janice Teufelsstein"}, [32]={npc="Janices Paket", npcObj=true}, [33]={npc="Janices Paket", npcObj=true}, [34]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [35]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [36]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [37]={hint="Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}, [38]={npc="Geißelkessel", npcObj=true}, [39]={npc="Geißelkessel", npcObj=true}, [40]={npc="Mrs. Dalsons Tagebuch", npcObj=true, desc="Das Tagebuch in der Scheune neben dem Kessel."}, [41]={hint="Questziele erfüllen."}, [42]={npc="Mrs. Dalsons Tagebuch", npcObj=true}, [43]={npc="Plumpsklo", npcObj=true, desc="Lies das Tagebuch und such dann das umherwandernde Skelett. Wenn du das Plumpsklo öffnest, erscheint der Bauer."}, [44]={hint="Beute von: Wanderndes Skelett"}, [45]={npc="Plumpsklo", npcObj=true}, [46]={npc="Verschlossener Schrank", npcObj=true, desc="Räum zuerst alles rund um das Plumpsklo und öffne dann die Kiste; danach kannst du sofort abgeben."}, [47]={hint="Beute von: Bauer Dalson"}, [48]={npc="Verschlossener Schrank", npcObj=true}, [49]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [50]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [51]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [52]={hint="Begebt Euch zum trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}, [53]={npc="Geißelkessel", npcObj=true}, [54]={npc="Geißelkessel", npcObj=true}, [55]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [56]={hint="Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück."}, [57]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [58]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [59]={hint="Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück."}, [60]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [61]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [62]={text="Geh nach Südosten und nimm hier den Bergpfad ins Hinterland."}, [63]={text="Binde deinen Ruhestein im Gasthaus von Aerie Peak (13.80, 41.60).", bindA="{a:348}"}, [64]={npc="Cortellos Schatz", npcObj=true, tag="Optional", desc="Der Schatz liegt an der Ostküste des Hinterlands, du musst quer über die ganze Karte; benutze nach der Abgabe deinen Ruhestein für den Rückweg."}, [65]={bindA="{a:348}"}}},
    ["04-56"] = {steps={[1]={text="Geh vom Aerie Peak auf dem Bergpfad nach Norden in die Westlichen Pestländer, dann nach Osten über den Thondroril in die Östlichen Pestländer. Tirion Fordring ist in der Hütte direkt am Eingang."}, [2]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [3]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [5]={hint="Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt."}, [6]={hint="Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück."}, [7]={hint="Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt."}, [8]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [9]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [10]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [11]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [12]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [13]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [14]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [15]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [16]={hint="Sucht Pamelas Puppe.", desc="Sammle in den zerstörten Häusern von Darrowshire Kopf, linke und rechte Seite und kombiniere sie per Rechtsklick."}, [17]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [18]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [19]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [20]={npc="Fürst Nicholas Zverenhoff", tgt="Fürst Nicholas Zverenhoff"}, [21]={npc="Fürst Nicholas Zverenhoff", tgt="Fürst Nicholas Zverenhoff", tag="Optional, Gruppe empfohlen"}, [22]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Gruppe empfohlen"}, [23]={npc="Leonid Barthalomew der Geachtete", tgt="Leonid Barthalomew der Geachtete", tag="Optional, Gruppe empfohlen"}, [24]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Optional, Gruppe empfohlen"}, [25]={node="Kapelle des hoffnungsvollen Lichts"}, [26]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [27]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [28]={npc="Verwalter Alen", tgt="Verwalter Alen"}, [29]={hint="Befreit 15 Geister von Darrowshire und kehrt dann zu Carlin Redpath zurück.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [30]={hint="Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt."}, [31]={hint="Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des hoffnungsvollen Lichts."}, [32]={npc="Zerrissene Rolle", npcObj=true}, [33]={hint="Sucht in den östlichen Pestländern nach Hinweisen auf den 'Blightcaller' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Shadowmore an der Chillwindspitze.", tag="Optional", desc="Nehmt von jeder der drei Leichen eine Insignie. Prüft mit allen drei Insignien das Erkundungsziel im Questlog. Ist es noch offen, erkundet die Umgebung des markierten Punkts und haltet Abstand vom Elitegegner."}, [34]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [35]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [36]={npc="Verwalter Alen", tgt="Verwalter Alen"}, [37]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}}},
    ["04-53"] = {steps={[1]={to="Southshore", toA="{a:271}", desc="Du steigst an der Chillwindspitze oder am Aerie Peak um; ist Southshore nicht auf deiner Flugkarte, flieg wie gewohnt nach Sturmwind und nimm im Hafen das Schiff nach Auberdine."}, [2]={npc="Raleigh der Andächtige", tgt="Raleigh der Andächtige", tag="Optional, Nur mit Material"}, [3]={to="Auberdine", from="Southshore", fromA="{a:271}", desc="Nimm am Pier von Southshore das Schiff nach Auberdine. Fliegst du stattdessen nach Sturmwind, geh im Hafen von Sturmwind an Bord."}, [4]={to="Everlook", toA="{a:2255}"}, [5]={hint="Donova Snowden in Winterspring möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt."}, [6]={hint="Salfa möchte, dass Ihr 8 Schamanen der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Ursa der Winterfelle erledigt. Salfa befindet sich direkt außerhalb des Eingangs zur Holzschlundfeste in Winterspring."}, [7]={npc="Leeres Feuerwasserfläschchen", npcObj=true, tag="Nur wenn es droppt, Optional", desc="Die Furbolgs der Winterfelle droppen das Leere Feuerwasserfläschchen; hast du es geplündert, nimm die Quest per Rechtsklick an; ist es noch nicht gedroppt, töte weiter Furbolgs."}, [8]={npc="Donova Snowden", tgt="Donova Snowden"}, [9]={npc="Donova Snowden", tgt="Donova Snowden", tag="Nur machen, wenn es droppt"}, [10]={npc="Donova Snowden", tgt="Donova Snowden"}, [11]={npc="Donova Snowden", tgt="Donova Snowden"}, [12]={npc="Donova Snowden", tgt="Donova Snowden", desc="Das Erkunden der Flüsternde Schlucht erledigst du an der nächsten Station auf dem Weg in den Hyjal; gib es ab, bevor du zurück nach Winterspring und weiter nach Moonglade gehst. Gib es ab, bevor du zurück nach Winterspring und weiter nach Moonglade gehst."}, [13]={hint="Sammelt 10 mondbestrahlte Federn aus Winterspring und kehrt dann zu Erelas Ambersky in Rut'theran zurück."}, [14]={npc="Salfa", tgt="Salfa"}, [15]={npc="Kessel der Totenwaldfelle", npcObj=true}, [16]={npc="Kessel der Totenwaldfelle", npcObj=true}, [17]={to="Rut'theran Village", toA="{a:702}", desc="Geh vom Kessel der Totenwaldfelle nach Süden zum Flugpunkt Nachtlaublichtung (62.49, 24.24) und flieg von dort ab; du steigst in Auberdine um."}, [18]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [19]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [20]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [21]={to="Everlook", toA="{a:2255}"}, [22]={npc="Harlo Wigglesworth", tgt="Harlo Wigglesworth"}, [23]={npc="Harlo Wigglesworth", tgt="Harlo Wigglesworth", tag="Optional", desc="Reine Gesprächsquest im Ort; in der Folgequest musst du gegen Elite-Riesen kämpfen, nimm sie nicht an."}, [24]={npc="Hexendoktorin Mau'ari", tgt="Hexendoktorin Mau'ari", tag="Optional"}, [25]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker", desc="Kämpfe erst gegen die Yetis, wenn du von Donova zurück bist und bevor du nach Süden aufbrichst."}, [26]={npc="Wynd Nightchaser", tgt="Wynd Nightchaser"}, [27]={npc="Wynd Nightchaser", tgt="Wynd Nightchaser"}, [28]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [29]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [30]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [31]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [32]={hint="Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Skycaller in den Östlichen Pestländern."}, [33]={npc="Donova Snowden", tgt="Donova Snowden"}, [34]={hint="Sammelt 10 dicke Yetifelle für Umi Rumplesnicker in Everlook."}, [35]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker"}, [36]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker", tag="Optional", desc="Die Hörner droppen nur von den Matriarchinnen und Patriarchen in der Höhle, und die Droprate ist niedrig; mach es nur, wenn du zusätzliche Erfahrung willst."}, [37]={hint="Sammelt 2 makellose Yetihörner für Umi Rumplesnicker in Everlook.", tag="Optional"}, [38]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker", tag="Optional", desc="Die Folgequest schickt dich nach Un'Goro und Gadgetzan, nimm sie nicht an."}, [39]={npc="Beschädigte Kiste", npcObj=true}, [40]={npc="Beschädigte Kiste", npcObj=true}, [41]={npc="Jarons Wagen", npcObj=true}, [42]={npc="Jarons Wagen", npcObj=true}, [43]={hint="Klaubt Jarons Vorräte aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte."}, [44]={npc="Ranshalla", tgt="Ranshalla"}, [45]={npc="Ranshalla", tgt="Ranshalla"}, [46]={hint="Schützt Ranshalla, während sie versucht, den Altar von Elune wieder zu aktivieren. Berichtet Erelas Ambersky in Rut'theran von Eurem Fund."}}},
    ["04-57"] = {danger={[1]="Ghansurok (Elite-Schimäre der Stufe 61) patrouilliert von den befleckten Hibiskussträuchern bis zu Kaylaenas Werkstatt (etwa x55-62,5, y61,5-72,2); prüfe seine Position beim Bearbeiten der Büsche und auf dem Rückweg zur Werkstatt.", [2]="Celastrus der Bittere (Elite der Stufe 57) streift um die befleckten Hibiskussträucher; achte beim Bearbeiten der Büsche auf ihn.", [3]="Der Knochenhaufen ruft einen Elite-Schleim der Stufe 58 herbei; ohne Gruppe klick ihn kein zweites Mal an."}, grind={[1]={note="Der Nordteil der Teufelsblutnarbe; alle Quests von Felflick kämpfst du hier."}}, supply={[1]={}}, steps={[1]={text="Geh von Ranshalla nach Süden in die Flüsternde Schlucht (59.82, 74.25), folge der Schlucht nach Westen bis zum Ende und betritt so den Hyjal. Am Eingang der Schlucht stehen Elite-Frostriesen, in der Schlucht gibt es Elite-Dämonen; bleib auf der Straße und halte nicht an.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [2]={hint="Befolgt Donova Snowdens Anweisungen und meldet Euch dann wieder bei ihr.", desc="Es wird beim Weg durch die Schlucht in den Hyjal abgeschlossen; ein Umweg ist nicht nötig. Sie zählt, sobald das Questlog sie als abgeschlossen anzeigt."}, [3]={text="Betritt den Hyjal an der Südostecke und folge der Straße nach Westen."}, [4]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [5]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [6]={npc="Lockeres Zahnrad", npcObj=true, desc="Ein Zahnrad am Boden neben der Straße; klick es mit rechts an, um es aufzuheben und die Quest anzunehmen."}, [7]={npc="Ketharas", tgt="Ketharas", tag="Optional", desc="Gib sie nur ab, wenn du sie zuvor im Teufelswald angenommen hast."}, [8]={npc="Ketharas", tgt="Ketharas"}, [9]={npc="Ketharas", tgt="Ketharas"}, [10]={npc="Ketharas", tgt="Ketharas"}, [11]={npc="Ketharas", tgt="Ketharas"}, [12]={npc="Ketharas", tgt="Ketharas"}, [13]={hint="Rettet 12 Hyjaleuleneier und bringt sie zu Ketharas."}, [14]={hint="Sammelt 10 unbefleckte Samen für Ketharas."}, [15]={npc="Ketharas", tgt="Ketharas"}, [16]={npc="Ketharas", tgt="Ketharas"}, [17]={npc="Ketharas", tgt="Ketharas"}, [18]={npc="Ketharas", tgt="Ketharas"}, [19]={hint="Sammelt 2 Stücke Wildfleisch von unbefleckten Hyjalhirschen und 6 scharlachrote Wurmknollen für den Eintopf des Einsiedlers."}, [20]={hint="Pflanzt die verzauberten Samen in der Nähe der zerstörten Balliste, des zerstörten Katapults und der zerstörten Flugmaschine.", desc="Die Wracks von Balliste, Katapult und Fluggerät zählen jeweils als ein Ziel. Du musst alle drei bepflanzen. Such am Hang vor der Einsiedlerhöhle."}, [21]={npc="Ketharas", tgt="Ketharas"}, [22]={npc="Ketharas", tgt="Ketharas"}, [23]={npc="Ketharas", tgt="Ketharas"}, [24]={hint="Vergrabt die Überreste an Ketharas' Schrein."}, [25]={npc="Ketharas", tgt="Ketharas"}, [26]={npc="Ketharas", tgt="Ketharas"}, [27]={nodeA="{a:16853}", node="Tainted Foothills", desc="Folge der Straße nach Westen; der Flugpunkt liegt neben dem Außenposten der Uralten."}, [28]={npc="Fraxinus", tgt="Fraxinus"}, [29]={npc="Hyacinth", tgt="Hyacinth"}, [30]={npc="Hyacinth", tgt="Hyacinth"}, [31]={npc="Thylaen", tgt="Thylaen", tag="Gruppe empfohlen, Optional", desc="Das Ziel ist ein Elite der Stufe 57; schaffst du es solo nicht, nimm sie nicht an."}, [32]={hint="Sammelt 6 Proben unbefleckter Erde in den Ausläufern des Hyjal."}, [33]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Wenn du später nach Everlook gehst, hol dir die Teile bei Nami."}, [36]={hint="Zerstört 15 besudelte Gebüsche für Kaylaena Springwhisper bei der Werkstatt im Besudelten Vorgebirge.", desc="Dieselben Hibiskussträucher lassen auch die blutstillenden Blätter fallen; bekämpfe sie für beide Quests zusammen. Gib es in der Werkstatt ab, wenn du die Kiste lieferst."}, [37]={hint="Sammelt 12 tiefgrüne Blätter von besudelten Gebüschen in den Ausläufern des Hyjal."}, [38]={hint="Findet und vernichtet Celastrus den Bitteren und kehrt dann mit dem zerbrochenen Wedel zu Thylaen zurück.", tag="Gruppe empfohlen, Optional"}, [39]={npc="Thylaen", tgt="Thylaen", tag="Gruppe empfohlen, Optional"}, [40]={npc="Hyacinth", tgt="Hyacinth"}, [41]={npc="Hyacinth", tgt="Hyacinth"}, [42]={npc="Hyacinth", tgt="Hyacinth"}, [43]={hint="Wendet den Umschlag bei Fraxinus an."}, [44]={npc="Fraxinus", tgt="Fraxinus"}, [45]={npc="Fraxinus", tgt="Fraxinus", tag="Gruppe empfohlen, Optional", desc="Das Ziel, Rindenriss, ist ein Elite-Uralter der Stufe 56; mach es mit einer Gruppe; ohne Gruppe überspring es, die spätere Abgabe wird dann automatisch übersprungen."}, [46]={npc="Fraxinus", tgt="Fraxinus"}, [47]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [48]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [49]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [50]={npc="Felflick", tgt="Felflick"}, [51]={npc="Felflick", tgt="Felflick"}, [52]={hint="Tötet 12 Aschenakolythen.", desc="Die Notizen fallen von denselben Akolythen; kämpfe also für beide Quests gegen sie."}, [53]={hint="Findet 12 Hinweise zum Experimentieren mit Teufelsasche."}, [54]={npc="Felflick", tgt="Felflick"}, [55]={npc="Felflick", tgt="Felflick"}, [56]={hint="Sammelt 8 Teufelsschleimkristalle und 1 makellosen Teufelsschleimkristall."}, [57]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [58]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [59]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [60]={hint="Sammelt 8 Teufelsschleimschlamm."}, [61]={hint="Sammelt 10 stachelige Kiefernzapfen unter gesunden Bäumen."}, [62]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [63]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [64]={npc="Felflick", tgt="Felflick"}, [65]={npc="Felflick", tgt="Felflick"}, [66]={npc="Felflick", tgt="Felflick"}, [67]={hint="Bergt die Knochen von Frezzlie Popwhiz, Tyaeha Darkoath und Dazka Shadowsleep."}, [68]={hint="Tötet Brashann Grimdark und sucht seine Leiche nach seinem Seelenstein ab."}, [69]={npc="Felflick", tgt="Felflick"}, [70]={npc="Felflick", tgt="Felflick"}, [71]={npc="Felflick", tgt="Felflick"}, [72]={npc="Knochenhaufen", npcObj=true, desc="Wirf die Hexenmeisterknochen auf den Knochenhaufen neben dem Schleimbecken."}, [73]={npc="Knochenhaufen", npcObj=true, tag="Gruppe empfohlen, Optional", desc="Dabei wird ein Elite-Schleim der Stufe 58 herbeigerufen; ohne Gruppe überspring „Verschmolzenes Mark\" und die Folgequests."}, [74]={hint="Tötet den erweckten Teufelsascheschleim.", tag="Gruppe empfohlen, Optional"}, [75]={npc="Velician", tgt="Velician"}, [76]={npc="Felflick", tgt="Felflick", tag="Gruppe empfohlen, Optional"}, [77]={npc="Felflick", tgt="Felflick"}, [78]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [79]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [80]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [81]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [82]={hint="Verwendet die Kiefernzapfen, um die Arbeitsstationen des Kults der Ascheherrschaft zu zerstören."}, [83]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [84]={npc="Seltsame Krähe", tgt="Seltsame Krähe", desc="Gib es an der nächsten Station im westlichen Holderwild ab."}, [85]={hint="Spürt das verderbte Urtum Rindenriss auf, vernichtet es und pflanzt dann einen Samen in seinen Überresten.", tag="Gruppe empfohlen, Optional", desc="Auf dem Rückweg nach Osten zur Einsiedlerhöhle."}, [86]={npc="Ketharas", tgt="Ketharas"}, [87]={npc="Ketharas", tgt="Ketharas"}, [88]={npc="Fraxinus", tgt="Fraxinus", tag="Gruppe empfohlen, Optional"}, [89]={to="Everlook", toA="{a:2255}"}, [90]={npc="Nami", tgt="Nami", desc="Die Folgekiste hat ein Zeitlimit; nimm sie erst an, wenn du aus Moonglade zurück bist."}, [91]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper", desc="Folge von Everlook der Straße ein kurzes Stück nach Westen bis Starfall."}, [92]={text="Reite von Starfall auf der Straße nach Südwesten zur heißen Quelle und such Donova."}, [93]={npc="Donova Snowden", tgt="Donova Snowden"}, [94]={to="Moonglade", desc="Reite von der heißen Quelle zurück zum Flugpunkt in Everlook und flieg (den Flugpunkt in Moonglade hast du an {s:04-49} freigeschaltet). Ist dein Ruf bei den Holzschlundbären schon neutral, reite von der heißen Quelle nach Norden zum Eingang der Holzschlundfeste (27.70, 34.50); durch die Höhle zum Ausgang nach Moonglade ist es näher; auch wer den Flugpunkt in Moonglade noch nicht hat, nimmt diesen Weg und schaltet bei der Ankunft zuerst den Flugpunkt frei (48.10, 67.34); unter neutral wirst du angegriffen. Druiden können direkt Teleportieren: Moonglade nutzen; nach der Ankunft gehst du zum normalen Flugpunkt (48.10, 67.34) und schaltest ihn frei, damit du zurückfliegen kannst. Auch wer den Flugpunkt in Moonglade noch nicht hat, nimmt diesen Weg und schaltet bei der Ankunft zuerst den Flugpunkt frei (48.10, 67.34). Unter neutralem Ruf wirst du angegriffen. Druiden können direkt Teleportieren: Moonglade nutzen; nach der Ankunft gehst du zum normalen Flugpunkt (48.10, 67.34) und schaltest ihn frei, damit du zurückfliegen kannst."}, [95]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [96]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [97]={npc="Orokai", tgt="Orokai"}, [98]={npc="Orokai", tgt="Orokai"}, [99]={hint="Sprecht mit Orokai, wenn Ihr bereit seid, herauszufinden, was er von dem schwach leuchtenden Ast in Erfahrung gebracht hat."}, [100]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [101]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [102]={to="Everlook", toA="{a:2255}", desc="Flieg am normalen Flugpunkt in Moonglade ab (48.10, 67.34) und steig in Everlook aus, um die Kiste abzuholen."}, [103]={npc="Nami", tgt="Nami", desc="Die Batterien in der Kiste fallen nach etwa zwei Stunden aus; liefere sie direkt vom Flugpunkt aus an Kaylaena."}, [104]={to="Tainted Foothills", toA="{a:16853}", desc="Reite vom Flugpunkt direkt nach Norden zu Kaylaenas Werkstatt und liefere zuerst die Kiste."}}},
    ["04-58"] = {danger={[1]="Ghansurok (Elite-Schimäre der Stufe 61) patrouilliert östlich des Schreins von Aviana; achte beim Kampf gegen Harpyien auf ihn."}, supply={[1]={}, [2]={}}, steps={[1]={hint="Transportiert die Kiste mit Teilen und Spielereien behutsam zu Kaylaena Springwhisper auf dem Hyjal.", desc="Bring die Kiste zu Kaylaena in der Werkstatt und folge ihrem Questdialog."}, [2]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Reite vom Flugpunkt direkt nach Norden zur Werkstatt und liefere zuerst die Kiste."}, [3]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [4]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Das Material liegt in den Überresten des Horde-Lagers in Dae'gun im Norden; nimm es mit, wenn du später vorbeikommst."}, [5]={npc="Ketharas", tgt="Ketharas", desc="Reite von der Werkstatt nach Südosten zurück zur Einsiedlerhöhle."}, [6]={npc="Ketharas", tgt="Ketharas"}, [7]={npc="Ketharas", tgt="Ketharas"}, [8]={npc="Himmelsfürst Omnuron", tgt="Himmelsfürst Omnuron", desc="Reite von der Einsiedlerhöhle nach Nordwesten zum Schrein von Aviana."}, [9]={npc="Himmelsfürst Omnuron", tgt="Himmelsfürst Omnuron"}, [10]={npc="Himmelsfürst Omnuron", tgt="Himmelsfürst Omnuron"}, [11]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [12]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [13]={hint="Tötet 18 Wurmschwingenharpyien auf dem Hyjal und bringt ihre Federn zu Phoebe Highfeather."}, [14]={hint="Sammelt 8 angelaufene Hochfederarmreife von Nestern der Wurmschwingenharpyien."}, [15]={hint="Findet das Juwel des Horizonts in einem Nest der Harpyien der Wurmschwingen und bringt es zu Ketharas."}, [16]={hint="Tötet Zarrat Wurmschwinge und bringt Omnurons Speer zurück."}, [17]={npc="Verderbter Auswuchs", npcObj=true, desc="Klick mit rechts auf den Verderbten Auswuchs am Baum, um die Quest anzunehmen."}, [18]={hint="Findet und entfernt 6 verderbte Knoten von den Bäumen in der Nähe."}, [19]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [20]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [21]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [22]={npc="Himmelsfürst Omnuron", tgt="Himmelsfürst Omnuron"}, [23]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [24]={npc="Seltsame Krähe", tgt="Seltsame Krähe", desc="Du kannst sie erst auf der Brücke in der Wiege der Ruhe im Norden erledigen, nimm sie also vorerst mit."}, [25]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring", desc="Folge dem Gebirgsfuß nach Westen."}, [26]={hint="Findet einen robusten Ast, mit dem Ihr Fenwick Togglespring erreicht."}, [27]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [28]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [29]={hint="Brecht den Ast, um Fenwick Togglespring zu befreien."}, [30]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [31]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [32]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [33]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [34]={hint="Wartet, bis Ihr das persönliche Überlebenspaket sicher öffnen könnt"}, [35]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [36]={npc="Brerufa", tgt="Brerufa"}, [37]={hint="Bezwingt 9 Höhlenwächter der Totenwaldfelle und kehrt zu Brerufa zurück."}, [38]={npc="Brerufa", tgt="Brerufa"}, [39]={npc="Brerufa", tgt="Brerufa", tag="Optional, If offered", desc="Nimm sie nur an, wenn du sie sehen kannst. Gib sie nur ab, wenn du schon 8 Perlenketten hast; du musst nicht extra farmen."}, [40]={npc="Brerufa", tgt="Brerufa"}, [41]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [42]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [43]={hint="Sammelt 30 Bärenbeeren von Hyjal und kehrt zu Osi Mistpaw zurück."}, [44]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [45]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [46]={hint="Findet und sprecht mit der Ältesten Mistpaw und dem Ältesten Pinespeaker innerhalb des Baus der Baumrindenfurbolgs."}, [47]={npc="Älteste Mistpaw", tgt="Älteste Mistpaw"}, [48]={npc="Älteste Mistpaw", tgt="Älteste Mistpaw"}, [49]={npc="Ältester Pinespeaker", tgt="Ältester Pinespeaker"}, [50]={npc="Suma Mossmane", tgt="Suma Mossmane"}, [51]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, If offered", desc="Nimm sie nur an, wenn du sie sehen kannst (setzt Ruf bei der Rindenhöhle voraus)."}, [52]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, If offered", desc="Nimm sie nur an, wenn du sie sehen kannst (setzt Ruf bei der Rindenhöhle voraus). Füll den Wasserschlauch am Teich vor dem Totenwaldbau."}, [53]={hint="Sammelt 10 luftgetrocknete Kräuter überall im Bau der Baumrindenfurbolgs und bringt sie zu Fennar Mossmane.", tag="Optional"}, [54]={npc="Älteste Mistpaw", tgt="Älteste Mistpaw", tag="Optional, If offered", desc="Nimm sie nur an, wenn du sie sehen kannst. Du kannst sie erst abgeben, wenn dein Ruf bei der Rindenhöhle neutral erreicht."}, [55]={hint="Bringt 5 Eulenkörper zum Ältesten Pinespeaker im Bau der Baumrindenfurbolgs in Hyjal."}, [56]={hint="Sammelt 12 Klumpen Mondschleiermoos und kehrt zu Suma Mossmane zurück."}, [57]={hint="Tötet 8 Totemiker der Totenwaldfelle und 8 Teufelspfleger der Totenwaldfelle und kehrt zum Ältesten Pinespeaker zurück."}, [58]={hint="Füllt Fennar Mossmanes Wasserschlauch am Teich außerhalb des Baus der Totenwaldfelle.", tag="Optional", desc="Such den Teich vor dem Totenwaldbau."}, [59]={npc="Matriarchin der Baumrindenfurbolgs", tgt="Matriarchin der Baumrindenfurbolgs"}, [60]={hint="Beschafft einen Schlüssel der Totenwaldfelle von einem Wächter der Totenwaldfelle und kehrt zum Käfig des Baumrindenfurbolgs zurück."}, [61]={npc="Matriarchin der Baumrindenfurbolgs", tgt="Matriarchin der Baumrindenfurbolgs"}, [62]={npc="Matriarchin der Baumrindenfurbolgs", tgt="Matriarchin der Baumrindenfurbolgs"}, [63]={hint="Eskortiert die Matriarchin der Baumrindenfurbolgs aus dem Bau der Totenwaldfelle und kehrt zum Bau der Baumrindenfurbolgs zurück.", desc="Eine Eskortenquest; in der Gruppe wartest du, bis alle sie angenommen haben, bevor ihr startet."}, [64]={npc="Brerufa", tgt="Brerufa"}, [65]={npc="Brerufa", tgt="Brerufa", tag="Optional", desc="Gib sie nur ab, wenn du 8 Perlenketten hast."}, [66]={npc="Suma Mossmane", tgt="Suma Mossmane"}, [67]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional"}, [68]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional"}, [69]={npc="Älteste Mistpaw", tgt="Älteste Mistpaw", tag="Optional", desc="Gib sie nur ab, wenn dein Ruf neutral erreicht hat."}, [70]={npc="Ältester Pinespeaker", tgt="Ältester Pinespeaker"}, [71]={npc="Ältester Pinespeaker", tgt="Ältester Pinespeaker"}, [72]={npc="Ältester Pinespeaker", tgt="Ältester Pinespeaker", tag="Optional, If offered", desc="Nimm sie nur an, wenn du sie sehen kannst. Du kannst sie erst abgeben, wenn dein Ruf bei der Rindenhöhle freundlich erreicht."}, [73]={npc="Ältester Pinespeaker", tgt="Ältester Pinespeaker", tag="Optional", desc="Gib sie nur ab, wenn dein Ruf freundlich erreicht hat. Hast du nicht genug, heb sie vorerst auf."}, [74]={npc="Eluneth", tgt="Eluneth", desc="Geh nach Norden."}, [75]={npc="Veteran des Dritten Krieges", tgt="Veteran des Dritten Krieges"}, [76]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [77]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [78]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [79]={npc="Mirt", tgt="Mirt"}, [80]={npc="Hnaz Blunderflame", tgt="Hnaz Blunderflame", desc="Neben dem Gasthaus von Holderwild; die Eulennester liegen im Tal im Süden und lassen sich beim späteren Rückweg zu Eluneth einsammeln."}, [81]={hint="Fangt 6 entlaufene Schafe und bringt sie zurück."}, [82]={npc="Mirt", tgt="Mirt"}, [83]={npc="Geschmückte Waffenscheide", npcObj=true, desc="Der Aussichtspunkt westlich von Holderwild."}, [84]={npc="Geschmückte Waffenscheide", npcObj=true}, [85]={hint="Verwendet die geschmückte Waffenscheide, um mit dem Kriegsveteranen auf dem Aussichtspunkt in Holderwild zu sprechen und Euch seine Geschichte zu hören."}, [86]={npc="Veteran des Dritten Krieges", tgt="Veteran des Dritten Krieges"}, [87]={npc="Nicht gekennzeichnetes Grab", npcObj=true, desc="Am Straßenrand in Richtung Osten klickst du das Namenlose Grab mit rechts an, um die Quest anzunehmen."}, [88]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre"}, [89]={hint="Füllt Galvinquam Leafsyres Trinkflasche am Wasserfall ein Stück weiter den Weg hinauf.", desc="Füll mit der leeren Kalebasse aus der Quest am Wasserfall vor dir Wasser ab, nicht neben Galvinquam."}, [90]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre"}, [91]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre", desc="Bring das Gepäck zum Gipfel der Ewigkeit."}, [92]={npc="Lisbael Highfeather", tgt="Lisbael Highfeather", desc="Gib es danach am Schrein von Aviana ab."}, [93]={hint="Berührt das Krähenbildnis auf der Brücke über der Wiege der Ruhe, um die Wilde Göttin Jereman zu rufen."}, [94]={npc="Jereman", tgt="Jereman"}, [95]={npc="Jereman", tgt="Jereman"}, [96]={npc="Jereman", tgt="Jereman"}, [97]={npc="Jereman", tgt="Jereman"}, [98]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [99]={hint="Verscheucht die Stinktiere aus dem Bereich rund um Johuns Ausrüstung, ohne sie zu töten."}, [100]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [101]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [102]={hint="Bringt 9 Schwänze eines Rostlaubfuchses zu Johun \"Haudrauf\" Dillas in Hyjal."}, [103]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [104]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [105]={npc="Kala'th", tgt="Kala'th", desc="Geh nach Westen."}, [106]={npc="Kala'th", tgt="Kala'th"}, [107]={hint="Bringt die Hirsche davon ab, sich wie Raubtiere aufzuführen."}, [108]={hint="Sucht in den ausgebrannten Gebäuden der Wiege der Ruhe nach 6 Metallklammern und 30 Nägeln und bringt sie Johun \"Haudrauf\" Dillis in Hyjal."}, [109]={npc="Kala'th", tgt="Kala'th"}, [110]={npc="Marrosis", tgt="Marrosis"}, [111]={npc="Marrosis", tgt="Marrosis"}, [112]={npc="Marrosis", tgt="Marrosis"}, [113]={hint="Eliminiert 3 vergessene Soldaten und 12 Fleischschinderräuber."}, [114]={hint="Durchsucht die Umgebung nach den fehlenden Grabinhalten."}, [115]={hint="Beschafft einen Tropfen gestohlenen Lebens von der Geißel in den Ruinen auf dem Hyjal und kehrt damit zu Ketharas zurück."}, [116]={hint="Setzt die Fackel des Überlebenden beim Knochenhaufen ein und sammelt dann das Amulett des Wiedererweckers ein."}, [117]={hint="Sammelt 20 sonnengebleichte Knochen."}, [118]={hint="Holt 8 Augen des Beobachters für Eluneth."}, [119]={npc="Marrosis", tgt="Marrosis"}, [120]={npc="Eluneth", tgt="Eluneth"}, [121]={hint="Geht nach Süden ins Tal und sammelt Federn aus den Nestern der Eulen.", desc="Ein kurzes Stück südlich von Eluneth; sie fallen auch von Hyjal-Eulen. Kehr nach dem Einsammeln nach Holderwild zurück."}, [122]={npc="Hnaz Blunderflame", tgt="Hnaz Blunderflame"}, [123]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [124]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [125]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [126]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [127]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [128]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [129]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [130]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [131]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [132]={npc="Daythor Brellan", tgt="Daythor Brellan"}}},
    ["04-60"] = {danger={[1]="Ghansurok (Elite-Schimäre der Stufe 61) streift über den Grat südlich von Kaylaenas Werkstatt.", [2]="Mazzogore der Schwache (Elite der Stufe 60) patrouilliert südlich von Dae'gun; umgeh ihn beim Kampf gegen Hunde.", [3]="Ve'han Talongrasp (Elite der Stufe 60) bewacht die Nordrassil-Hütte; komm bei den Kultistenquests nicht zu nah heran."}, grind={[1]={mob="Wachposten der Teufelswache", note="Die südliche Hälfte von Dae'gun; sammle nebenbei die verlassenen Vorräte und Horde-Trümmermaterialien auf."}, [2]={note="Das Kultistenlager östlich des Gipfels der Ewigkeit; die Gipfelquests kämpfst du alle hier."}}, supply={[1]={}, [2]={}, [3]={}}, steps={[1]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas", desc="Geh auf der Straße zurück nach Osten."}, [2]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [3]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [4]={npc="Welkbart", tgt="Welkbart"}, [5]={npc="Yashiro", tgt="Yashiro"}, [6]={hint="Zündet die beiden Lagerfeuer in Dae'gun an und kehrt zu Yashiro zurück."}, [7]={text="Entzünde das Lagerfeuer im Südosten, geh weiter nach Südosten zu Renalard; gib zuerst „Kluges Wesen\" ab, nimm die Asche- und die Fuchsquest an und säubere auf dem Rückweg Dae'gun noch einmal."}, [8]={npc="Renalard", tgt="Renalard"}, [9]={npc="Renalard", tgt="Renalard"}, [10]={npc="Renalard", tgt="Renalard"}, [11]={hint="Sammelt 8 zurückgelassene Ausrüstungsgegenstände.", desc="Lock den Dämon mit dem Büschel Fuchsfell (Tuft of Fox Fur) aus der Quest weg und sammle dann 8 verlassene Vorräte auf. Die Vorräte liegen nicht neben Renalard."}, [12]={hint="Plündert die Überreste der Hordebasis und bringt 5 Stücke ausgefranster Draht, 5 Stücke Metallschrott und 5 verkalkte Exkremente zu Kaylaena."}, [13]={hint="Beschafft 6 ephemere Essenzen für Elaena Moonwhisper."}, [14]={hint="Tötet 12 Teufelswächter in Dae'gun."}, [15]={hint="Holt eine Prise von Azgalors Asche aus den Ruinen von Dae'gun auf dem Hyjal."}, [16]={hint="Betretet Dae'gun, findet einen Aussichtspunkt und erstattet dann Johun einen detaillierten Bericht."}, [17]={npc="Yashiro", tgt="Yashiro", desc="Kehr nach dem Säubern von Dae'gun zur Abgabe zu Yashiro zurück."}, [18]={npc="Yashiro", tgt="Yashiro", tag="Optional"}, [19]={hint="Kämpft Euch zusammen mit Yashiro einen Weg durch Dae'gun frei.", tag="Gruppe empfohlen, Optional", desc="Folge Yashiro, der den Weg freiräumt; sie ist abgeschlossen, wenn du am Ende Verdammniswache Xarkul (Doomguard Xarkul) besiegst."}, [20]={npc="Yashiro", tgt="Yashiro", tag="Optional", desc="Gib sie bei Yashiro dort ab, wo das Ereignis endet; das ist nicht unbedingt der Ausgangspunkt."}, [21]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [22]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Gruppe empfohlen, Optional", desc="Beide Ziele sind Elite-Dämonen der Stufe 60; ohne Gruppe überspring es, die Folgequests werden dann automatisch übersprungen."}, [23]={hint="Benutzt das Auge des unendlichen Einflusses, um Bethra'zel und Mazzogore die Macht zu entziehen und sie dann zu töten.", tag="Gruppe empfohlen, Optional"}, [24]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Gruppe empfohlen, Optional"}, [25]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [26]={npc="Welkbart", tgt="Welkbart"}, [27]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [28]={npc="Renalard", tgt="Renalard", desc="Geh nach Südosten."}, [29]={nodeA="{a:16849}", node="Summit of Eternity", desc="Geh von Renalard ein kurzes Stück den Berg nach Osten hinauf und schalte den Flugpunkt bei Fayran Elthas frei. Gib zuerst die paar Quests ab, die du auf den Berg mitgebracht hast, um dein Questlog zu entlasten."}, [30]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [31]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne", tag="Optional", desc="Gib sie nur ab, wenn du sie zuvor im Un'Goro-Krater angenommen hast."}, [32]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [33]={npc="Sebelia", tgt="Sebelia", desc="Gib das Briefpaket gleich in Everlook ab und mach dann die Postkette."}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Geh vom Gipfel der Ewigkeit nach Westen den Berg hinunter an Renalard vorbei und dann nach Süden zur Werkstatt. Ist der Bergpfad nicht passierbar, flieg zu dem Besudelten Vorgebirge und reite nach Norden."}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [36]={hint="Dreht die Getriebe und verbindet die Batterieanschlüsse an beiden Seiten von Kaylaenas Glevenschleuder."}, [37]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [38]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Gruppe empfohlen, Optional", desc="Der angelockte Ghansurok ist eine Elite-Schimäre der Stufe 61."}, [39]={hint="Geht zum Kamm südlich von Kaylaenas Werkstatt und findet einen Weg, ein ablenkendes Getöse zu machen, um die Schimäre Ghansurok so nah anzulocken, dass sie angegriffen werden kann.", tag="Gruppe empfohlen, Optional", desc="Interagiere mit der Trommel an der Klippe südlich der Werkstatt und lock die Schimäre in die Reichweite des Klingenradwerfers, damit der NSC ihn bedient; zieh sie nicht weit weg, um sie mit Gewalt zu bekämpfen."}, [40]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Gruppe empfohlen, Optional"}, [41]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather", desc="Geh von der Werkstatt ein kurzes Stück nach Südwesten zum Schrein von Aviana."}, [42]={npc="Ketharas", tgt="Ketharas", desc="Reite vom Schrein nach Südosten zurück zur Einsiedlerhöhle."}, [43]={npc="Ketharas", tgt="Ketharas"}, [44]={npc="Ketharas", tgt="Ketharas"}, [45]={npc="Ketharas", tgt="Ketharas"}, [46]={to="Everlook", toA="{a:2255}", desc="Reite von der Einsiedlerhöhle nach Westen und flieg am Flugpunkt des Besudelten Vorgebirges ab."}, [47]={npc="Gastwirt Vizzie", tgt="Gastwirt Vizzie"}, [48]={npc="Gastwirt Vizzie", tgt="Gastwirt Vizzie"}, [49]={hint="Findet 4 vermisste Post in den Hügeln nördlich von Everlook und bringt sie zurück zu Gastwirt Vizzie.", desc="Die Post liegt verstreut auf den Hügeln vor der Ewigen Warte, such sie anhand der Hinweise im Questlog; findest du sie nicht, kannst du sie vorerst auslassen."}, [50]={npc="Gastwirt Vizzie", tgt="Gastwirt Vizzie"}, [51]={npc="Gastwirt Vizzie", tgt="Gastwirt Vizzie", desc="Bring die Post zurück zum Gipfel des Hyjal und gib sie dort ab."}, [52]={to="Summit of Eternity", toA="{a:16849}", desc="Du steigst an dem Besudelten Vorgebirge um."}, [53]={npc="Sebelia", tgt="Sebelia"}, [54]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [55]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [56]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [57]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [58]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [59]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [60]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [61]={hint="Findet Dornensamen in den Wäldern am Gipfel von Hyjal und bringt sie zu Tiala Whitemane zurück."}, [62]={hint="Setzt den Stab des Berges gegen 10 Mitglieder des Schwarzdornpakts auf dem Gipfel der Ewigkeit ein, um ihre Schutzzauber zu entfernen und sie anschließend zu töten.", desc="Dieselben Kultisten zählen auch für „Den Wahn beenden\" und „Verdrehte Werkzeuge\"; setz zuerst den Stab ein, töte sie dann, und mach alle drei zusammen."}, [63]={hint="Tötet 10 Adepten der Blackthorne und 10 wildnisgezeichnete Kultisten."}, [64]={hint="Beschafft einen tückischen Ritualistenkris und einen zurückspringenden Knorrenborkenstab von den Blackthorne-Kultisten."}, [65]={hint="Sammelt 5 große Hippogryphenfedern und 3 öliges Schimärenhaar für Marn"}, [66]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [67]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [68]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [69]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [70]={hint="Pflanzt Dornensamen in der Nähe des Gasthauses, des Lagerturms und der Baumgruppe im Lager der loyalistischen Druiden."}, [71]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [72]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [73]={npc="Thisalee Crow", tgt="Thisalee Crow", desc="Geh nach der Annahme zuerst zu Marn Euhorn, um „Winde der Läuterung\" abzugeben und „Archimondes Begnadigung\" (Archimonde's Pardon) anzunehmen; mach beide auf demselben Weg."}, [74]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [75]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [76]={hint="Aktiviert die Wächtersteine im Norden, Westen und Süden rund um die Blackthorne-Kultisten.", desc="Der nördliche, westliche und südliche Stein zählen jeweils als ein Ziel; du musst alle drei aufsuchen."}, [77]={hint="Verwendet den verzauberten Zweig, um 5 Irrwische in der Nähe von Nordrassil zu befreien.", desc="Befreie das Irrlicht, das schon unter den Wurzeln steckt, und beschwöre es nicht mit einem Gegenstand auf der Lichtung. Mach sie auf demselben Weg wie „Archimondes Begnadigung\"."}, [78]={hint="Nehmt Marns Räucherwerk und lasst den Rauch die Luft um Archimondes Überreste reinigen"}, [79]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [80]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [81]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [82]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [83]={to="Rut'theran Village", toA="{a:702}", desc="Du steigst an dem Besudelten Vorgebirge und in Everlook um."}, [84]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [85]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [86]={text="Geh in Rut'theran durch das Portal nach Darnassus."}, [87]={npc="Erzdruide Fandral Staghelm", tgt="Erzdruide Fandral Staghelm"}, [88]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}}},
    ["05-d30"] = {name="Blackmaw Hold", entrance="Azshara 38.70, 33.40 (Tunneleingang, folg dem Tunnel zum Portal)", pickup="Nimm „Unter Nordrassil\" beim ersten Besuch an der Talrendisspitze an. Gib die Quest in Darnassus ab, wenn du wieder dort bist, und nimm die Folgequest an. Geh mit der Gruppe nordöstlich der Talrendisspitze zum Tunnel in Azshara. Erzmagier Timear steht an der Straße von Süderstade nach Dalaran. Lass ihn aus, wenn er nicht auf deinem Weg liegt.", pickupS={{"Nimm „Unter Nordrassil\" beim ersten Besuch an der Talrendisspitze an"}, {"Gib die Quest in Darnassus ab, wenn du wieder dort bist, und nimm die Folgequest an"}, {"Geh mit der Gruppe nordöstlich der Talrendisspitze zum Tunnel in Azshara"}, {"Erzmagier Timear steht an der Straße von Süderstade nach Dalaran"}, {"Lass ihn aus, wenn er nicht auf deinem Weg liegt"}}, tips={{k="動線", text="Tunnel → unten Wurzelkappen, Beutel und Totems sammeln → beide Abzweigungen für Welkschlund und Knochenschnauze den Ungebrochenen → Schamanenältester Bloodmane → Endboss Varrox Bleakhoof."}, {k="說明", text="Für die Zwillingsbären und die Endbossquest brauchst du neutralen Ruf bei der Holzschlundfeste. Starte „Die Bedrohung durch die Legashi\" bei Ekkal, dann sprich mit Torhüter Donnerschrei, Korsa und Gorn Einauge. Besiege Prinz Halanox draußen und gib das Außenquest ab, um die Dungeonfortsetzung freizuschalten. Tausch gefundenes Teufelsbesudeltes Fleisch gegen Samenkapseln und gib „Fütterungszeit!\" beim Fleischfressenden Peitscher hinter Schamanenältestem Bloodmane ab.", s={{"Für die Zwillingsbären und die Endbossquest brauchst du neutralen Ruf bei der Holzschlundfeste"}, {"Starte „Die Bedrohung durch die Legashi\" bei Ekkal, dann sprich mit Torhüter Donnerschrei, Korsa und Gorn Einauge"}, {"Besiege Prinz Halanox draußen und gib das Außenquest ab, um die Dungeonfortsetzung freizuschalten"}, {"Tausch gefundenes Teufelsbesudeltes Fleisch gegen Samenkapseln und gib „Fütterungszeit!\" beim Fleischfressenden Peitscher hinter Schamanenältestem Bloodmane ab"}}}}, steps={[1]={npc="Kommandantin Truesong", tgt="Kommandantin Truesong"}, [2]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}, [3]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", preText="Unter Nordrassil"}, [4]={npc="Erzmagier Timear", tgt="Erzmagier Timear", tag="Optional"}, [5]={npc="Ogtinc", tgt="Ogtinc"}, [6]={npc="Ekkal", tgt="Ekkal"}, [7]={npc="Hüter des Wissens Nok", tgt="Hüter des Wissens Nok", tag="Optional", desc="Nimm die Quest erst an, wenn dein Ruf bei der Holzschlundfeste neutral ist."}, [8]={npc="Torhüter Donnerschrei", tgt="Torhüter Donnerschrei", tag="Optional", desc="Nimm die Quest nur an, wenn du die lange Questreihe der Holzschlundfeste ohnehin machst.", preText="Der Gegenangriff der Schwarzschlundfurbolgs"}, [9]={text="Eingang: Blackmaw Hold"}, [10]={hint="Sammelt in der Schwarzschlundfeste 10 Wurzelkappen von Nordrassil für Mathrengyl Bearwalker in Darnassus.", desc="Ort: In den äußeren Wäldern und im Tunnel.", spot="In den äußeren Wäldern und im Tunnel."}, [11]={hint="Begebt Euch in die Schwarzschlundfeste und bergt 5 Schwarzschlundbeutel für Ekkal an den Ruinen von Eldarath in Azshara.", desc="Ort: In den Furbolglagern am Weg.", spot="In den Furbolglagern am Weg."}, [12]={hint="Findet das Totem von Ursoc und das Totem von Ursol in der Schwarzschlundfeste. Kehrt dann zum Hüter des Wissens Nok in Ursolan zurück.", tag="Optional", desc="Ort: Sieh im Dungeon in beiden Abzweigungen nach den Totems.", spot="Sieh im Dungeon in beiden Abzweigungen nach den Totems."}, [13]={hint="Bringt die Klauen des großen Bären und die Hauer des Ungebrochenen zu Ogtinc in Azshara.", desc="Ort: Töte in jeder Abzweigung ein Ziel.", spot="Töte in jeder Abzweigung ein Ziel."}, [14]={hint="Bergt ein Ritualtotem des Schwarzschlunds in der Schwarzschlundfeste.", tag="Optional", desc="Ort: Schamanenältester Bloodmane im Furbolgbereich.", spot="Schamanenältester Bloodmane im Furbolgbereich."}, [15]={npc="Gefiederte Anhängerhalskette", npcObj=true, tag="Optional", desc="Starte die Quest per Rechtsklick, sobald du die Halskette erbeutet hast."}, [16]={hint="Bringt Varrox Bleakhoofs Kopf zu Torhüter Donnerschrei in Ursolan.", tag="Optional", desc="Ort: Auf der Plattform des Endbosses.", spot="Auf der Plattform des Endbosses."}, [17]={npc="Ogtinc", tgt="Ogtinc"}, [18]={npc="Ekkal", tgt="Ekkal"}, [19]={npc="Hüter des Wissens Nok", tgt="Hüter des Wissens Nok", tag="Optional"}, [20]={npc="Torhüter Donnerschrei", tag="Optional"}, [21]={npc="Unele", tgt="Unele", tag="Optional"}, [22]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}, [23]={npc="Erzmagier Timear", tgt="Erzmagier Timear", tag="Optional"}}},
    ["04-59"] = {name="Westliche Pestländer", steps={[1]={bindA="{a:348}", desc="Nutze den Ruhestein nur, wenn er noch an Aerie Peak gebunden und einsatzbereit ist. Sonst nimm die Schiffsroute als Ausweichplan: Geh durch das Portal zurück nach Rut'theran, flieg nach Auberdine, fahr zuerst mit dem Schiff nach Menethil und dann auf der Nordroute weiter nach Southshore, steig dort aus und flieg dann zum Lager Chillwind."}, [2]={to="Chillwind Camp", toA="{a:3197}", desc="Überspring das, wenn du schon im Lager Chillwind bist. Fehlt das Lager Chillwind auf der Flugkarte, geh von Aerie Peak auf dem Bergweg nach Norden in die Westliche Pestländer und dann nach Westen zum Lager Chillwind."}, [3]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [4]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [5]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [6]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [7]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [8]={npc="Alchimist Arbington", tgt="Alchimist Arbington"}, [9]={npc="Alchimist Arbington", tgt="Alchimist Arbington", desc="Die Skelettfragmente droppen erst, nachdem du die Quest angenommen hast; sammle sie nebenbei, wenn du in Sorrow Hill und Andorhal Skelette tötest."}, [10]={npc="Marlene Redpath", tgt="Marlene Redpath"}, [11]={npc="Marlene Redpath", tgt="Marlene Redpath"}, [12]={hint="Bringt Josephs Ehering zu Chromie."}, [13]={hint="Bringt 15 Skelettfragmente zu Alchimist Arbington an der Chillwindspitze, Westliche Pestländer."}, [14]={npc="Chromie", tgt="Chromie"}, [15]={npc="Chromie", tgt="Chromie"}, [16]={npc="Chromie", tgt="Chromie"}, [17]={hint="Bringt die 'Annalen von Darrowshire' zu Chromie in Andorhal."}, [18]={hint="Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren."}, [19]={npc="Chromie", tgt="Chromie"}, [20]={npc="Chromie", tgt="Chromie"}, [21]={npc="Chromie", tgt="Chromie"}, [22]={hint="Sucht 5 Andorhal-Uhren, die in Schließkassetten überall im Schutt der Stadt zu finden sind. Kehrt mit ihnen zu Chromie ins Gasthaus Andorhal in den Westlichen Pestländern zurück."}, [23]={npc="Chromie", tgt="Chromie"}, [24]={npc="Chromie", tgt="Chromie"}, [25]={to="Kapelle des hoffnungsvollen Lichts", desc="Andorhal hat keinen Flugpunkt. Geh zuerst nach Süden zurück zur Chillwindspitze und flieg von dort."}, [26]={npc="Fürst Nicholas Zverenhoff", tgt="Fürst Nicholas Zverenhoff", tag="Optional, Gruppe empfohlen"}, [27]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [28]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [29]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [30]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Gruppe empfohlen"}, [31]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Gruppe empfohlen", desc="Erledigt dies, wenn eure Gruppe das nächste Mal den Untotenflügel besucht."}, [32]={npc="Leonid Barthalomew der Geachtete", tgt="Leonid Barthalomew der Geachtete", tag="Optional, Gruppe empfohlen"}, [33]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Optional, Gruppe empfohlen"}, [34]={hint="Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt."}, [35]={hint="Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe."}, [36]={npc="Aurora Skycaller", tgt="Aurora Skycaller"}, [37]={hint="Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestland-Termiten gesammelt habt, kehrt zu Nathaniel Dumah am Chillwindposten in den Westlichen Pestländern zurück."}, [38]={hint="Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Redpath in der Kapelle des hoffnungsvollen Lichts.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [39]={npc="Erdhaufen", npcObj=true}, [40]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [41]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [42]={hint="Bringt Davils Buchband und Redpaths Schild zu Carlin Redpath."}, [43]={hint="Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}, [44]={npc="Geißelkessel", npcObj=true}, [45]={npc="Geißelkessel", npcObj=true}, [46]={npc="Grafiker Renfray", tgt="Grafiker Renfray"}, [47]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [48]={npc="Alchimist Arbington", tgt="Alchimist Arbington", desc="Die Folgequest führt nach Scholomance, nimm sie nicht an."}, [49]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [50]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [51]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [52]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [53]={npc="Termitenfass", npcObj=true}, [54]={npc="Termitenfass", npcObj=true}, [55]={hint="Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Nathaniel Dumah im Chillwind-Posten in den westlichen Pestländern zurück."}, [56]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [57]={hint="Tötet 2 scharlachrote Sanitäter, 2 scharlachrote Jäger, 2 scharlachrote Magi und 2 scharlachrote Ritter, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt."}, [58]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [59]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [60]={hint="Besiegt Jägerin Radley und Chevalier Durgen, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt."}, [61]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [62]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [63]={hint="Geht nach Hearthglen, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Deepshadow in den Westlichen Pestländern zurück.", desc="Die Koordinaten sind ungefähr. Am Eingang und am Turm stehen Wachen des Scharlachroten Kreuzzugs; zieh sie einzeln."}, [64]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [65]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [66]={to="Kapelle des hoffnungsvollen Lichts", desc="Du bist schon an der Chillwindspitze, geh direkt zum Flugmeister."}, [67]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [68]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [69]={to="Ironforge"}, [70]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus"}, [71]={to="Stormwind"}, [72]={npc="Königlicher Disponent Bathrilor", tgt="Königlicher Disponent Bathrilor"}, [73]={npc="Königlicher Disponent Bathrilor", tgt="Königlicher Disponent Bathrilor"}, [74]={npc="Alte Emma", tgt="Alte Emma"}, [75]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Optional"}, [76]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw", tag="Optional"}, [77]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw", tag="Optional"}, [78]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw", tag="Optional"}, [79]={to="Lakeshire", toA="{a:69}", tag="Optional", desc="Geh nur mit „Die wahren Meister\" nach Seenhain; hast du sie nicht, flieg direkt von Sturmwind nach Morgans Wacht."}, [80]={npc="Magistrat Solomon", tgt="Magistrat Solomon"}, [81]={npc="Magistrat Solomon", tgt="Magistrat Solomon"}, [82]={to="Morgan's Vigil", toA="{a:2418}"}, [83]={npc="Marshal Maxwell", tgt="Marshal Maxwell"}, [84]={npc="Marshal Maxwell", tgt="Marshal Maxwell"}, [85]={npc="Oralius", tgt="Oralius", tag="Optional"}, [86]={hint="Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt."}, [87]={hint="Nehmt Gor'teshs abgehackten Kopf und platziert ihn auf dem Gipfel des Schreckensfelsens. Sucht nach einem weichen Erdhügel, um den Pfahl aufzustellen.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [88]={npc="Marshal Maxwell", tgt="Marshal Maxwell"}, [89]={npc="Oralius", tgt="Oralius", tag="Optional"}, [90]={text="Noch nicht Stufe 60? Lauf einmal die Blackrocktiefen. Reicht das nicht, farm Stratholme oder Scholomance."}}},
    ["05-d29"] = {name="Die Terrasse des Formers", entrance="Un'Goro-Krater 48.10, 6.10 (Wegmarke außen am Titanenbau)", pickup="Sprich ab Stufe 55 mit Thorius in der Halle der Forscher in Eisenschmiede. Bist du nach Un'Goro noch nicht 55, warte bis zum nächsten Stadtbesuch. Nimm das Schiff auf den anderen Kontinent und geh von Marshals Zuflucht nach Norden bergauf zur Instanz.", pickupS={{"Sprich ab Stufe 55 mit Thorius in der Halle der Forscher in Eisenschmiede"}, {"Bist du nach Un'Goro noch nicht 55, warte bis zum nächsten Stadtbesuch"}, {"Nimm das Schiff auf den anderen Kontinent und geh von Marshals Zuflucht nach Norden bergauf zur Instanz"}}, tips={{k="動線", text="Tagebuch am Eingangsbecken → unterwegs kartieren und Ravasaurier töten → Giftkamm → Landmarken und Seiten prüfen."}, {k="說明", text="Alle drei Quests passen in einen Lauf. Bring Machtkristalle nur mit, wenn die Gruppe zusätzliche Bosse machen will.", s={{"Alle drei Quests passen in einen Lauf"}, {"Bring Machtkristalle nur mit, wenn die Gruppe zusätzliche Bosse machen will"}}}}, steps={[1]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [2]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [3]={text="Eingang: Die Terrasse des Formers"}, [4]={npc="Partially Digested Journal", npcObj=true, desc="Klick nach dem Betreten das Tagebuch im Lager am ersten Becken an."}, [5]={hint="Sammelt 15 teilweise verdaute Tagebuchseiten von der Terrasse des Formers.", desc="Ort: Auf demselben Weg wie die Jagdquest für Ravasaurier.", spot="Auf demselben Weg wie die Jagdquest für Ravasaurier."}, [6]={hint="Tötet 6 Ravasaurusmatriarchinnen, 9 Eisenhautravasaurier und Giftkämme auf der Terrasse des Formers.", desc="Ort: Die Ravasaurier stehen entlang des Weges.", spot="Die Ravasaurier stehen entlang des Weges."}, [7]={hint="Findet interessante Orientierungspunkte auf der Terrasse des Formers und füllt bei jedem Punkt die Forscherkarte aus.", desc="Ort: Benutz das Kartierungswerkzeug an jeder der fünf Landmarken einmal.", spot="Benutz das Kartierungswerkzeug an jeder der fünf Landmarken einmal."}, [8]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [9]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [10]={npc="Kurator Thorius", tgt="Kurator Thorius"}}},
    ["05-d28"] = {name="Scholomance", entrance="Westliche Pestländer 68.90, 72.80 (unterirdischer Eingang von Caer Darrow)", pickup="Sprich mit Weldon im Zugwindlager und mit Betina an der Kapelle des hoffnungsvollen Lichts. Geh vor dem Dungeon zu Eva an der Brücke von Caer Darrow. Hast du die Westlichen Pestländer schon verlassen, flieg zum Zugwindlager zurück.", pickupS={{"Sprich mit Weldon im Zugwindlager und mit Betina an der Kapelle des hoffnungsvollen Lichts"}, {"Geh vor dem Dungeon zu Eva an der Brücke von Caer Darrow"}, {"Hast du die Westlichen Pestländer schon verlassen, flieg zum Zugwindlager zurück"}}, tips={{k="動線", text="Veranda → Urkunden in der ersten Halle → Welpenraum → Blutrippe → Ras Frostraunen → sechs untere Räume → Dunkelmeister Gandling."}, {k="說明", text="Ein Skelettschlüssel für die Gruppe reicht. Mach die Vorquests in Gadgetzan und am Feuerfedergrat nur für einen eigenen Schlüssel. Beim ersten Lauf bieten sich die Urkunden, die Welpen und der Doktor an. Für „Dämmerungstrickfalle\" brauchst du beide Eierquests in der oberen Blackrockspitze. Ras' lange Questreihe führt auch nach Stromgarde und in Stratholmes Untotenflügel.", s={{"Ein Skelettschlüssel für die Gruppe reicht"}, {"Mach die Vorquests in Gadgetzan und am Feuerfedergrat nur für einen eigenen Schlüssel"}, {"Beim ersten Lauf bieten sich die Urkunden, die Welpen und der Doktor an"}, {"Für „Dämmerungstrickfalle\" brauchst du beide Eierquests in der oberen Blackrockspitze"}, {"Ras' lange Questreihe führt auch nach Stromgarde und in Stratholmes Untotenflügel"}}}}, steps={[1]={npc="Weldon Barov", tgt="Weldon Barov"}, [2]={npc="Betina Bigglezink", tgt="Betina Bigglezink"}, [3]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff"}, [4]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist", tag="Optional"}, [5]={hint="Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Sorrow Hill.", tag="Optional"}, [6]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist", tag="Optional"}, [7]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist", tag="Optional"}, [8]={hint="Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.", tag="Optional"}, [9]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist", tag="Optional"}, [10]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist", tag="Optional"}, [11]={npc="Alchimist Arbington", tgt="Alchimist Arbington", tag="Optional"}, [12]={npc="Alchimist Arbington", tgt="Alchimist Arbington", tag="Optional"}, [13]={hint="Bringt 15 Skelettfragmente zu Alchimist Arbington an der Chillwindspitze, Westliche Pestländer.", tag="Optional"}, [14]={npc="Alchimist Arbington", tgt="Alchimist Arbington", tag="Optional"}, [15]={npc="Alchimist Arbington", tgt="Alchimist Arbington", tag="Optional", preText="Skelettfragmente"}, [16]={hint="Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goodsteel in Gadgetzan.", tag="Optional"}, [17]={npc="Krinkle Goodsteel", tgt="Krinkle Goodsteel", tag="Optional"}, [18]={npc="Krinkle Goodsteel", tgt="Krinkle Goodsteel", tag="Optional"}, [19]={hint="Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.", tag="Optional"}, [20]={npc="Alchimist Arbington", tgt="Alchimist Arbington", tag="Optional"}, [21]={npc="Alchimist Arbington", tgt="Alchimist Arbington", tag="Optional"}, [22]={hint="Zerstört Araj den Beschwörer und bringt Arajs Skarabäus zum Alchimisten Arbington an der Chillwindspitze in den westlichen Pestländern.", tag="Optional"}, [23]={npc="Alchimist Arbington", tgt="Alchimist Arbington", tag="Optional"}, [24]={npc="Alchimist Arbington", tgt="Alchimist Arbington", tag="Optional"}, [25]={npc="Alchimist Arbington", tgt="Alchimist Arbington", tag="Optional"}, [26]={text="Voraussetzung: Dämmerungstrickfalle", tag="Optional"}, [27]={text="Voraussetzung: Der Lich Ras Frostraunen", tag="Optional"}, [28]={text="Eingang: Scholomance"}, [29]={hint="Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist.", desc="Ort: Auf den Tischen oder Bänken in den Räumen.", spot="Auf den Tischen oder Bänken in den Räumen."}, [30]={hint="Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts zurück.", desc="Ort: Geh von der Veranda durch die Beschwörungskammer zu den Welpen.", spot="Geh von der Veranda durch die Beschwörungskammer zu den Welpen."}, [31]={npc="Gesunde Großdrachenschuppe", npcObj=true, tag="Optional"}, [32]={hint="Sucht nach Jandice Barov in der Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff.", tag="Optional", desc="Ort: In der versunkenen Gruft unter der ersten Halle.", spot="In der versunkenen Gruft unter der ersten Halle."}, [33]={hint="Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren.", tag="Optional", desc="Ort: Auf der Veranda des Dungeons.", spot="Auf der Veranda des Dungeons."}, [34]={hint="Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Bigglezink zurück.", tag="Optional", desc="Ort: Töte Blutrippe für den Schlüssel und kehre in den Beobachtungsraum zurück.", spot="Töte Blutrippe für den Schlüssel und kehre in den Beobachtungsraum zurück."}, [35]={hint="Sucht Ras Frostraunen in der Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduke.", tag="Optional", desc="Ort: Im Alchemielabor vor den letzten sechs Räumen.", spot="Im Alchemielabor vor den letzten sechs Räumen."}, [36]={hint="Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt.", desc="Ort: Im Raum des Doktors liegen beide sterblichen Überreste.", spot="Im Raum des Doktors liegen beide sterblichen Überreste."}, [37]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff"}, [38]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", tag="Optional", desc="Töte Jandice beim nächsten Durchlauf.", preText="Doktor Theolen Krastinov, der Schlächter"}, [39]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", tag="Optional"}, [40]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", tag="Optional", desc="Kehre zum Beschwören zur Veranda zurück, wenn dieselbe Gruppe weitermacht.", preText="Krastinovs Tasche der Schrecken"}, [41]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", tag="Optional"}, [42]={npc="Magistrat Marduke", tgt="Magistrat Marduke", tag="Optional", desc="Leg die Spektralessenz an, damit du den Magistrat sehen kannst."}, [43]={npc="Weldon Barov", tgt="Weldon Barov"}, [44]={npc="Betina Bigglezink", tgt="Betina Bigglezink"}, [45]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional"}, [46]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional"}}},
    ["05-d27"] = {name="Obere Blackrockspitze", entrance="Brennende Steppe 29.40, 38.30 (Südeingang zum Blackrock)", pickup="Nimm auf der Allianzroute durch die Brennende Steppe die Quests in Morgans Wacht und am Flammenkamm an. Fehlt dir eine Stufe, hol sie vor dem Gruppenlauf nach. Gib nach der unteren Spitze „General Drakkisaths Befehl\" in Morgans Wacht ab und nimm die Quest für den Endboss der oberen Spitze an.", pickupS={{"Nimm auf der Allianzroute durch die Brennende Steppe die Quests in Morgans Wacht und am Flammenkamm an"}, {"Fehlt dir eine Stufe, hol sie vor dem Gruppenlauf nach"}, {"Gib nach der unteren Spitze „General Drakkisaths Befehl\" in Morgans Wacht ab und nimm die Quest für den Endboss der oberen Spitze an"}}, tips={{k="動線", text="Gemeinsames Portal → links hinauf zur verschlossenen Tür → Feuerwache Glutseher → Krähenhorst → Arena → Drakkisath."}, {k="說明", text="Gleicher Eingang wie zur unteren Spitze. Jemand in der Gruppe braucht das Siegel des Aufstiegs für die Tür. Erledige die beiden Eierquests in zwei Läufen; die Folgequest führt nach Scholomance.", s={{"Gleicher Eingang wie zur unteren Spitze"}, {"Jemand in der Gruppe braucht das Siegel des Aufstiegs für die Tür"}, {"Erledige die beiden Eierquests in zwei Läufen; die Folgequest führt nach Scholomance"}}}}, steps={[1]={npc="Mayara Brightwing", tgt="Mayara Brightwing"}, [2]={text="Voraussetzung: General Drakkisaths Befehl", tag="Optional"}, [3]={text="Voraussetzung: Das Großdrachenauge", tag="Optional"}, [4]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional", preText="General Drakkisaths Befehl"}, [5]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [6]={hint="Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe.", tag="Optional"}, [7]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [8]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [9]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="Optional"}, [10]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="Optional"}, [11]={hint="Bringt Felnok Steelspring 8 unbeschädigte Hörner einer Eiswindschimäre.", tag="Optional"}, [12]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="Optional"}, [13]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="Optional"}, [14]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [15]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional", preText="Rückkehr zu Tinkee"}, [16]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional", desc="Plane einen zweiten Durchlauf ein.", preText="Ei-Frosten"}, [17]={npc="Lorax", tgt="Lorax", tag="Optional", desc="Nur für Schmiede relevant."}, [18]={npc="Lorax", tgt="Lorax", tag="Optional"}, [19]={npc="Lorax", tgt="Lorax", tag="Optional", desc="Nur für Schmiede relevant.", preText="Lorax' Geschichte"}, [20]={npc="Haleh", tgt="Haleh", tag="Optional", desc="Nimm die Quest mit in den Dungeon, wenn du Onyxias Zutrittsreihe machst.", preText="Das Großdrachenauge"}, [21]={text="Eingang: Obere Blackrockspitze"}, [22]={hint="Bringt Mayara Brightwing in der brennenden Steppe Doomriggers Schnalle.", desc="Ort: Such nach der Feuerwache Glutseher im Krähenhorst nach der Kiste.", spot="Such nach der Feuerwache Glutseher im Krähenhorst nach der Kiste."}, [23]={hint="Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst.", tag="Optional", desc="Ort: Im Krähenhorst der oberen Spitze.", spot="Im Krähenhorst der oberen Spitze."}, [24]={hint="Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe.", tag="Optional", desc="Ort: Im Krähenhorst der oberen Spitze.", spot="Im Krähenhorst der oberen Spitze."}, [25]={hint="Begebt Euch zur Blackrockspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein.", tag="Optional", desc="Ort: Im Schmelzofen der oberen Spitze.", spot="Im Schmelzofen der oberen Spitze."}, [26]={npc="Pip Quickwit", tgt="Pip Quickwit", tag="Optional", desc="Such Pip nach dem Arenaereignis."}, [27]={npc="Awbee", tgt="Awbee", tag="Optional", desc="Such Awbee nach der Arena auf dem oberen Balkon."}, [28]={hint="Begebt Euch zur Blackrockspitze und schaltet General Drakkisath aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.", tag="Optional", desc="Ort: Im Raum des Endbosses der oberen Spitze.", spot="Im Raum des Endbosses der oberen Spitze."}, [29]={hint="Ihr müsst das Blut des schwarzen Großdrachen-Helden von General Drakkisath bekommen.", tag="Optional", desc="Ort: Im Raum des Endbosses der oberen Spitze.", spot="Im Raum des Endbosses der oberen Spitze."}, [30]={npc="Mayara Brightwing", tgt="Mayara Brightwing"}, [31]={npc="Mayara Brightwing", tgt="Mayara Brightwing", tag="Optional"}, [32]={npc="Graf Remington Ridgewell", tgt="Graf Remington Ridgewell", tag="Optional"}, [33]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [34]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [35]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [36]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional", preText="Eiersammlung"}, [37]={npc="Leonid Barthalomew der Geachtete", tgt="Leonid Barthalomew der Geachtete", tag="Optional"}, [38]={npc="Leonid Barthalomew der Geachtete", tgt="Leonid Barthalomew der Geachtete", tag="Optional", preText="Leonid Barthalomew"}, [39]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional"}, [40]={npc="Lorax", tgt="Lorax", tag="Optional"}, [41]={npc="Malyfous Darkhammer", tgt="Malyfous Darkhammer", tag="Optional"}, [42]={npc="Haleh", tgt="Haleh", tag="Optional"}, [43]={npc="Haleh", tgt="Haleh", tag="Optional"}}},
    ["05-d13"] = {name="Stratholme", entrance="Östliche Pestländer 26.52, 10.36 (Scharlachrotes Haupttor; Dienstboteneingang zum Untotenflügel bei 43.50, 19.40)", steps={[1]={text="Fliegt zum Zugwindlager, wenn ihr für „Von Liebe und Familie\" zur Malerin auf Caer Darrow in den Westlichen Pestländern müsst. Habt ihr die Quest bereits oder braucht nur die Quests der Kapelle, trefft direkt eure Gruppe."}, [2]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [3]={hint="Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt.", tag="Dungeon-Vorquest"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [5]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [6]={hint="Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück.", tag="Dungeon-Vorquest"}, [7]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [8]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [9]={hint="Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt.", tag="Dungeon-Vorquest"}, [10]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [11]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [12]={hint="Hört Euch an, was Tirion Fordring zu sagen hat.", tag="Dungeon-Vorquest"}, [13]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [14]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [15]={hint="Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", tag="Dungeon-Vorquest"}, [16]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [17]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [18]={hint="Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", tag="Dungeon-Vorquest"}, [19]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [20]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [21]={npc="Grafiker Renfray", tgt="Grafiker Renfray", tag="Dungeon-Vorquest"}, [22]={npc="Grafiker Renfray", tgt="Grafiker Renfray"}, [23]={npc="Fürst Nicholas Zverenhoff", tgt="Fürst Nicholas Zverenhoff", tag="Optional, Gruppe empfohlen"}, [24]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Gruppe empfohlen"}, [25]={npc="Leonid Barthalomew der Geachtete", tgt="Leonid Barthalomew der Geachtete", tag="Optional, Gruppe empfohlen"}, [26]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Optional, Gruppe empfohlen"}, [27]={text="Brecht von der Kapelle des hoffnungsvollen Lichts mit eurer Gruppe nach Stratholme auf. Die Eingangsmarkierung zeigt das scharlachrote Haupttor zum Markt und zur Bastion. Für den Untotenflügel trefft im Osten ein Gruppenmitglied, das den Dienstboteneingang öffnen kann."}, [28]={text="Eingang: Stratholme"}, [29]={hint="Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Heiliges Wasser von Stratholme. Kehrt zu Leonid Barthalomew dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt.", tag="Optional, Gruppe empfohlen", spot="Durchsucht in beiden Flügeln die Vorratskisten an den Straßen. Hebt fünf Flaschen heiliges Wasser von Stratholme für die Abgabe auf und ersetzt verbrauchte Flaschen."}, [30]={hint="Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt.", tag="Optional, Gruppe empfohlen", spot="Sammelt verseuchte Fleischproben, während eure Gruppe einen der beiden Flügel räumt. Hebt sie für den nächsten Besuch auf und kehrt mit zwanzig Stück zur Kapelle zurück."}, [31]={hint="Sucht Ezra Grimms Raucherladen in Stratholme und bergt einen Kasten von Grimms Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist.", tag="Optional, Gruppe empfohlen", spot="Geht im Scharlachroten Flügel vom Haupttor zum Markt. Öffnet die Kiste am Tabakladen, besiegt Ezra Grimm und plündert eine Schachtel seines Premiumtabaks. Macht das ein andermal, wenn eure Gruppe nur den Untotenflügel besucht."}, [32]={hint="Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der Scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.", spot="Besiegt zuerst Galford. Fragt eure Gruppe, ob alle, die das Gemälde für „Von Liebe und Familie\" brauchen, es hinter dem Bild der zwei Monde eingesammelt haben. Verbrennt erst dann das Archiv. Benötigt niemand das Gemälde, könnt ihr das Archiv sofort verbrennen."}, [33]={hint="Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv.", tag="Optional, Gruppe empfohlen", spot="Besiegt zuerst Galford. Fragt eure Gruppe, ob alle, die das Gemälde für „Von Liebe und Familie\" brauchen, es hinter dem Bild der zwei Monde eingesammelt haben. Verbrennt erst dann das Archiv. Benötigt niemand das Gemälde, könnt ihr das Archiv sofort verbrennen."}, [34]={npc="Kopf von Balnazzar", npcObj=true, tag="Optional, Gruppe empfohlen", desc="Gebt zuerst „Der Archivar\" ab. Startet danach die Quest per Rechtsklick auf den selbst erbeuteten Kopf von Balnazzar."}, [35]={hint="Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück.", tag="Optional, Gruppe empfohlen", spot="Durchsuche die drei Ziggurats im Untotenflügel nach der kleinen Truhe und nimm die Aufzeichnungen selbst heraus."}, [36]={hint="Zieht nach Stratholme und vernichtet Baron Rivendare. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück.", tag="Optional, Gruppe empfohlen", spot="Durchquere das Schlachthaus im Untotenflügel, besiege Baron Totenschwur und plündere seinen Kopf selbst."}, [37]={hint="Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei!", tag="Optional, Gruppe empfohlen", spot="Suche auf den Straßen von Stratholme nach geisterhaften Bürgern. Benutze Egans Blaster zuerst auf einen Bürger und dann auf die erschienene Seele. Befreie fünfzehn Seelen."}, [38]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Tirion Fordring ist in der Hütte am Flussufer im Westen der Östlichen Pestländer."}, [39]={text="Kehrt zur Kapelle des Hoffnungsvollen Lichts zurück. Habt ihr das Gemälde für „Von Liebe und Familie\", bringt es zuerst zu Tirion am westlichen Flussufer in den Östlichen Pestländern und kehrt dann zur Kapelle zurück."}, [40]={npc="Fürst Nicholas Zverenhoff", tgt="Fürst Nicholas Zverenhoff", tag="Optional, Gruppe empfohlen"}, [41]={npc="Kopf von Balnazzar", npcObj=true, tag="Optional, Gruppe empfohlen", desc="Gebt zuerst „Der Archivar\" ab. Startet danach die Quest per Rechtsklick auf den selbst erbeuteten Kopf von Balnazzar."}, [42]={npc="Fürst Nicholas Zverenhoff", tgt="Fürst Nicholas Zverenhoff", tag="Optional, Gruppe empfohlen"}, [43]={npc="Fürst Nicholas Zverenhoff", tgt="Fürst Nicholas Zverenhoff", tag="Optional, Gruppe empfohlen", desc="Erledigt dies, wenn eure Gruppe das nächste Mal den Untotenflügel besucht."}, [44]={npc="Fürst Nicholas Zverenhoff", tgt="Fürst Nicholas Zverenhoff", tag="Optional, Gruppe empfohlen"}, [45]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Gruppe empfohlen"}, [46]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Gruppe empfohlen", desc="Erledigt dies, wenn eure Gruppe das nächste Mal den Untotenflügel besucht."}, [47]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Gruppe empfohlen"}, [48]={npc="Leonid Barthalomew der Geachtete", tgt="Leonid Barthalomew der Geachtete", tag="Optional, Gruppe empfohlen"}, [49]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Optional, Gruppe empfohlen"}, [50]={npc="Egan", tgt="Egan", tag="Optional, Gruppe empfohlen"}, [51]={to="Ironforge"}}},
    ["05-d12"] = {name="Blackrocktiefen", entrance="Sengende Schlucht 34.80, 85.30", pickup="Nimm Kharan Mighthammer an, sobald du Die glimmenden Ruinen von Thaurissan in Ironforge abgegeben hast. Die Quests der Brennenden Steppe nimmst du in der Gegend von Morgans Wacht an.", pickupS={{"Nimm Kharan Mighthammer an, sobald du Die glimmenden Ruinen von Thaurissan in Ironforge abgegeben hast"}, {"Die Quests der Brennenden Steppe nimmst du in der Gegend von Morgans Wacht an"}}, steps={[1]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus", tag="Dungeon-Vorquest"}, [2]={hint="Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan.", tag="Dungeon-Vorquest"}, [3]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus", tag="Dungeon-Vorquest"}, [4]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus", tag="Dungeon-Vorquest"}, [5]={hint="Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt.", tag="Dungeon-Vorquest"}, [6]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus", tag="Dungeon-Vorquest"}, [7]={npc="König Magni Bronzebeard", tgt="König Magni Bronzebeard", desc="Die Voraussetzung ist Ruinen von Thaurissan (Die glimmenden Ruinen von Thaurissan); nimm sie an, nachdem du in Westliche Pestländer von Kapitel 04 in Ironforge abgegeben hast."}, [8]={npc="Ragnar Donnerbräu", tgt="Ragnar Donnerbräu", tag="Optional", desc="Gib sie erst ab, wenn du sie in den Verwüsteten Landen angenommen hast."}, [9]={npc="Ragnar Donnerbräu", tgt="Ragnar Donnerbräu", tag="Optional", desc="Kharanos liegt nicht auf dem Weg; überspring es, wenn du den Umweg nicht machen willst."}, [10]={npc="Oralius", tgt="Oralius"}, [11]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [12]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [13]={hint="Lasst Velarok Windblade seine Geschichte erzählen.", tag="Dungeon-Vorquest"}, [14]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [15]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [16]={hint="Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Velarok Windblade.", tag="Dungeon-Vorquest"}, [17]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [18]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [19]={hint="Bringt 8 mit Thorium beschichtete Dolche zu Velarok Windblade.", tag="Dungeon-Vorquest"}, [20]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [21]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [22]={hint="Bringt ein Symbol von Ragnaros zu Velarok Windblade.", tag="Dungeon-Vorquest"}, [23]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [24]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [25]={hint="Wartet bis Velarok Windblade die Fackel der Vergeltung vollendet hat.", tag="Dungeon-Vorquest"}, [26]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [27]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [28]={npc="Fackel der Vergeltung", npcObj=true, tag="Dungeon-Vorquest"}, [29]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [30]={npc="Knappe Maltrake", tgt="Knappe Maltrake", tag="Dungeon-Vorquest"}, [31]={npc="Knappe Maltrake", tgt="Knappe Maltrake", tag="Dungeon-Vorquest"}, [32]={hint="Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt.", tag="Dungeon-Vorquest"}, [33]={npc="Knappe Maltrake", tgt="Knappe Maltrake", tag="Dungeon-Vorquest"}, [34]={npc="Hort des Schwarzdrachenschwarms", npcObj=true, tag="Dungeon-Vorquest"}, [35]={npc="Hort des Schwarzdrachenschwarms", npcObj=true, tag="Dungeon-Vorquest"}, [36]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous", tag="Dungeon-Vorquest"}, [37]={hint="Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Velarok Windblade erhalten habt.", tag="Dungeon-Vorquest"}, [38]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous", tag="Dungeon-Vorquest"}, [39]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous"}, [40]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Dungeon-Vorquest"}, [41]={hint="Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist.", tag="Dungeon-Vorquest"}, [42]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Dungeon-Vorquest"}, [43]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Dungeon-Vorquest"}, [44]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Dungeon-Vorquest"}, [45]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Dungeon-Vorquest"}, [46]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Dungeon-Vorquest"}, [47]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Dungeon-Vorquest"}, [48]={hint="Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon.", tag="Dungeon-Vorquest"}, [49]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Dungeon-Vorquest"}, [50]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Dungeon-Vorquest"}, [51]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Dungeon-Vorquest"}, [52]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Dungeon-Vorquest"}, [53]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Dungeon-Vorquest"}, [54]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Dungeon-Vorquest"}, [55]={hint="Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt.", tag="Dungeon-Vorquest"}, [56]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Dungeon-Vorquest"}, [57]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [58]={text="Folge von Morgans Wacht der Straße durch die Brennende Steppe nach Westen in den Blackrock."}, [59]={text="Eingang: Blackrocktiefen"}, [60]={npc="Kharan Mighthammer", tgt="Kharan Mighthammer"}, [61]={npc="Kharan Mighthammer", tgt="Kharan Mighthammer", tag="Optional, Gruppe empfohlen"}, [62]={hint="Lasst Kharan Mighthammer seine Geschichte erzählen.", tag="Optional, Gruppe empfohlen", spot="Hört euch Kharans ganze Geschichte an."}, [63]={npc="Kharan Mighthammer", tgt="Kharan Mighthammer", tag="Optional, Gruppe empfohlen"}, [64]={hint="Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept.", tag="Optional"}, [65]={hint="Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen."}, [66]={hint="Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe."}, [67]={hint="Begebt Euch in die Blackrocktiefen und tötet Bael'Gar."}, [68]={npc="Marshal Windsor", tgt="Marshal Windsor", tag="Optional"}, [69]={npc="Marshal Windsor", tgt="Marshal Windsor", tag="Optional, Gruppe empfohlen", desc="Abgabe bei Feldmarschall Maxwell in der Brennenden Steppe. Nicht annehmen, wenn du nicht mehr in die Brennende Steppe zurückkehrst."}, [70]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional, Gruppe empfohlen"}, [71]={npc="Oralius", tgt="Oralius"}, [72]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [73]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous"}, [74]={npc="Ragnar Donnerbräu", tgt="Ragnar Donnerbräu", tag="Optional"}}},
  },
  quests = {
    [5] = {n="Jitters' knurrender Magen", d="Sprecht mit Küchenchef Grual."},
    [6] = {n="Kopfgeld auf Garrick Padfoot", d="Tötet Garrick Padfoot und bringt seinen Kopf zu Deputy Willem in der Nähe der Abtei von Nordhain.", tgo={{"Garrick Padfoot"}}},
    [7] = {n="Säuberung im Koboldlager", d="Tötet 10 von dem Koboldgezücht und kehrt dann zu Marshal McBride zurück.", tgo={{"Koboldgezücht"}}},
    [9] = {n="Tod auf den Feldern", d="Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet.", tgo={{"Erntebehüter"}}},
    [10] = {n="Die Erlösung von Scrimshank", d="Erforscht das Schicksal von Unterfeldmesser Scrimshank und bringt entweder ihn oder seine Feldmesserausrüstung nach Gadgetzan zum Leitenden Feldmesser Fizzledowser.", objs={"Scrimshanks Feldmesser-Ausstattung"}},
    [12] = {n="Die Volksmiliz", d="Gryan Stoutmantle möchte, dass Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", tgo={{"Fallensteller der Defias"}, {"Schmuggler der Defias"}}},
    [13] = {n="Die Volksmiliz", d="Gryan Stoutmantle möchte, dass Ihr 15 Plünderer der Defias und 15 Ausplünderer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", tgo={{"Plünderer der Defias"}, {"Ausplünderin der Defias"}}},
    [15] = {n="Überprüfung der Echokammmine", d="Tötet 10 Koboldtagelöhner und erstattet dann Marshal McBride Euren Bericht.", tgo={{"Koboldtagelöhner"}}},
    [17] = {n="Reagenzsuche in Uldaman", d="Bringt zwölf magenta Funguskappen nach Thelsamar zu Ghak Healtouch.", objs={"Magenta Kappengruppen"}},
    [18] = {n="Bruderschaft der Diebe", d="Bringt 12 rote Sackleinenkopftücher zu Deputy Willem in der Nähe der Abtei von Nordhain.", tgo={{"Rohling der Defias"}}},
    [19] = {n="Tharil'zun", d="Bringt den Kopf von Tharil'zun ins Rotkammgebirge zu Marshal Marris.", tgo={{"Tharil'zun"}}},
    [20] = {n="Bedrohung durch die Blackrock", d="Bringt 10 kampferprobte Äxte nach Seenhain zu Marshal Marris.", tgo={{"Held der Blackrock", "Schattenzauberer der Blackrock", "Renegat der Blackrock", "Grunzer der Blackrock", "Kundschafter der Blackrock", "Fährtenleser der Blackrock", "Späher der Blackrock", "Wachposten der Blackrock"}}},
    [21] = {n="Scharmützel in der Echokammmine", d="Tötet 12 Koboldhilfsarbeiter und kehrt dann zu Marshal McBride in der Abtei von Nordhain zurück.", tgo={{"Koboldhilfsarbeiter"}}},
    [26] = {n="Eine wertvolle Lektion", d="Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade."},
    [29] = {n="Prüfung des Sees", d="Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.\nIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", objs={"Der Schrein von Remulos"}},
    [33] = {n="Wölfe an der Grenze", d="Bringt Eagan Peltskinner, den Ihr vor der Abtei von Nordshire findet, 8 Stücke zähes Wolfsfleisch.", tgo={{"Wilder Waldwolf", "Junger Wolf", "Struppiger Waldwolf", "Struppiger junger Wolf"}}},
    [34] = {n="Ein ungebetener Gast", d="Martie Jainrose aus Seenhain möchte, dass Ihr Stopfwanst tötet. Bringt ihr den Hauer des Ebers zum Beweis.", tgo={{"Stopfwanst"}}},
    [35] = {n="Weitere Sorgen", d="Marshal Dughan möchte, dass Ihr mit Wache Thomas sprecht."},
    [36] = {n="Westfall-Eintopf", d="Verna Furlbrow möchte, dass Ihr ihr Rezept für Westfall-Eintopf bei Salma Saldean abliefert."},
    [37] = {n="Suche nach den vermissten Wachen", d="Wache Thomas möchte, dass Ihr den Fluss in Richtung Norden nach Rolf und Malakai, den beiden vermissten Wachen, absucht."},
    [39] = {n="Zustellung von Thomas' Bericht", d="Erstattet Marshal Dughan in Goldhain Bericht."},
    [40] = {n="Gefahr aus dem Wasser", d="Remy \"Zweifach\" möchte, dass Ihr in Goldhain mit Marshal Dughan sprecht."},
    [45] = {n="Rolfs Schicksal", d="Durchsucht das Murlocdorf nach Rolf - oder nach Anzeichen für seinen Tod."},
    [47] = {n="Tauschhandel mit Goldstaub", d="Bringt 10 Einheiten Goldstaub nach Goldhain zu Remy \"Zweifach\". Goldstaub findet Ihr bei den Kobolden im Wald von Elwynn.", tgo={{"Koboldminenarbeiter", "Goldzahn", "Koboldtunnelgräber", "Koboldgeomant", "Nimsy", "Geoformerin Yip"}}},
    [52] = {n="Grenzschutz", d="Tötet 8 Streuner und 5 junge Waldbären und kehrt dann zu Wache Thomas an der östlichen Elwynn-Brücke zurück.", tgo={{"Streuner"}, {"Junger Waldbär"}}},
    [54] = {n="Meldung in Goldhain", d="Liefert Marshal McBrides Unterlagen bei Marshal Dughan in Goldhain ab."},
    [55] = {n="Morbent Fel", d="Verwendet Morbents Bann gegen Morbent Fel, tötet Morbent Fel und bringt Morbents Bann anschließend zu Sven in dessen Lager zurück.", tgo={{"Morbent Fel"}}},
    [56] = {n="Die Nachtwache", d="Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr 8 Skelettkrieger und 6 Skelettmagier tötet.", tgo={{"Skelettkrieger"}, {"Skelettmagier"}}},
    [57] = {n="Die Nachtwache", d="Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr 15 Skelettsatanskreaturen und 15 Skelettschrecken tötet.", tgo={{"Skelettsatanskreatur"}, {"Skelettschrecken"}}},
