    [226] = {n="Wölfe auf den Fersen", d="Tötet 12 verhungernde Terrorwölfe und 8 tollwütige Terrorwölfe und kehrt dann zu Lars in Svens Lager an der westlichen Grenze des Dämmerwalds zurück.", tgo={{"Ausgehungerter Terrorwolf"}, {"Tollwütiger Terrorwolf"}}},
    [227] = {n="Morgan Ladimore", d="Sprecht in Dunkelhain mit Kommandantin Althea Ebonlocke."},
    [230] = {n="Svens Lager", d="Bringt das Buch von Svens Hof zu Sven."},
    [233] = {n="Postbeförderung im Coldridgetal", d="Liefert den Stapel Briefe bei Talin Keeneye ab."},
    [234] = {n="Postbeförderung im Coldridgetal", d="Liefert den Brief bei Grelin Whitebeard ab."},
    [237] = {n="Verteidigung der Länder des Königs", d="Gebirgsjäger Gravelgaw im südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher tötet und ihm anschließend Bericht erstattet.", tgo={{"Schädelhauer der Splittersteintroggs"}, {"Seher der Splittersteintroggs"}}},
    [240] = {n="Rückkehr zu Jitters", d="Kehrt mit den schwärzlichen Krebsküchlein zu Jitters zurück."},
    [244] = {n="Eindringende Gnolle", d="Erstattet Deputy Feldon Bericht."},
    [245] = {n="Gefahr auf acht Beinen", d="Erledigt 15 Zwerggiftweberspinnen und meldet Euch dann wieder bei Behüter Dodds im Dämmerwald.", tgo={{"Zwerggiftweberspinne"}}},
    [246] = {n="Einschätzung der Gefahr", d="Tötet 10 Bastarde der Rotkammgnolle und 6 Wilderer der Rotkammgnolle und meldet Euch anschließend wieder bei Deputy Feldon in Seenhain.", tgo={{"Bastard der Rotkammgnolle"}, {"Wilderer der Rotkammgnolle"}}},
    [248] = {n="Weitere Beobachtungen", d="Steigt in den unversehrten Wachturm neben der Burg Steinwacht hinauf.\nFindet einen passenden Behälter für die Glyphe von Azora und legt diese dort ab."},
    [250] = {n="Eine dunkle Bedrohung", d="Untersucht den Bereich um die östliche Dammrampe und bringt Chefingenieur Hinderweir einen Hinweis, der Auskunft darüber geben könnte, was die Dunkeleisenzwerge vorhaben."},
    [257] = {n="Das Prahlen eines Jägers", d="Tötet 6 Bergbussarde und kehrt innerhalb von 15 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück.", tgo={{"Bergbussard"}}},
    [258] = {n="Die Herausforderung eines Jägers", d="Tötet 5 alte Bergeber und kehrt innerhalb von 12 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück.", tgo={{"Alter Bergeber"}}},
    [261] = {n="Auf dem Scharlachroten Pfad", d="Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück.", tgo={{"Untoter Verheerer"}}},
    [262] = {n="Die Schattengestalt", d="Nehmt das Buch, das Ihr auf Svens Hof gefunden habt, und zeigt es den Einwohnern von Dunkelhain."},
    [263] = {n="Verteidigung der Länder des Königs", d="Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs tötet.", tgo={{"Schamane der Splittersteintroggs"}, {"Knochenknacker der Splittersteintroggs"}}},
    [265] = {n="Die Schattensuche geht weiter", d="Überprüft, ob andere Einwohner Hinweise auf die schattenhafte Gestalt haben."},
    [266] = {n="Nachforschungen im Gasthaus", d="Sucht im Gasthaus nach Hinweisen auf die schattenhafte Gestalt."},
    [267] = {n="Die Bedrohung durch die Troggs", d="Bringt Captain Rugelfuss im südlichen Wachturm 8 Trogg-Steinzähne.", tgo={{"Splittersteintrogg", "Späher der Splittersteintroggs", "Schädelhauer der Splittersteintroggs", "Knochenknacker der Splittersteintroggs", "Geomant der Splittersteintroggs", "Seher der Splittersteintroggs", "Buddler der Splittersteintroggs", "Schamane der Splittersteintroggs"}}},
    [268] = {n="Rückkehr zu Sven", d="Kehrt mit Jitters' vollständigem Tagebuch zu Sven zurück."},
    [269] = {n="Auf der Suche nach Weisheit", d="Gebt Bischof Farthing in Stormwind Jitters' vollständiges Tagebuch."},
    [270] = {n="Die verlorene Flotte", d="Geht zum Hafen von Menethil im Sumpfland und sprecht mit Glorin Steelbrow."},
    [272] = {n="Prüfung des Seelöwen", d="Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.\nFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.\nBringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade.", objs={"Der Schrein von Remulos"}},
    [275] = {n="Schwärendes Land", d="Tötet 12 Moorkrabbler und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", tgo={{"Moorkrabbler"}}},
    [276] = {n="Stapfende Pfoten", d="Tötet 15 Gnolle der Moosfelle sowie 10 Bastarde der Moosfelle und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", tgo={{"Gnoll der Moosfelle"}, {"Bastard der Moosfelle"}}},
    [277] = {n="Feuer-Tabu", d="Bringt Rethiel dem Sumpfhüter 9 kunstlose Feuersteine.", tgo={{"Nebelwirker der Moosfelle", "Moorläufer der Moosfelle", "Fallensteller der Moosfelle", "Schläger der Moosfelle", "Mystiker der Moosfelle", "Alpha der Moosfelle", "Knochennager"}}},
    [279] = {n="Klauen aus der Tiefe", d="Tötet 12 Murlocs der Blaukiemen.\nErschlagt Gobbler und nehmt Euch seinen Kopf.\nBringt Gobblers Kopf zu Karl Boran in den Hafen von Menethil", tgo={{"Murloc der Blaukiemen"}, {"Gobbler"}}},
    [281] = {n="Waren-Wiederbeschaffung", d="Durchsucht die Kisten und Fässer in den Murloclagern an der Küste."},
    [282] = {n="Senirs Beobachtungen", d="Sprecht mit Gebirgsjäger Thalos."},
    [284] = {n="Die Suche geht weiter", d="Sucht nach der Menethil-Statuette."},
    [285] = {n="Suche in weiteren Hütten", d="Sucht weiter in den Hütten der Murlocs nach der Menethil-Statuette."},
    [286] = {n="Rückgabe der Statuette", d="Bringt Karl Boran die Menethil-Statuette."},
    [288] = {n="Die Dritte Flotte", d="Spendiert dem ersten Maat Fitzsimmons einen Krug Met."},
    [289] = {n="Die verfluchte Crew", d="Vernichtet 13 verfluchte Seeleute, 5 verfluchte Matrosen und den ersten Maat Snellig. Bringt Snelligs Schnupftabakdose zum ersten Maat Fitzsimmons im Hafen von Menethil.", tgo={{"Verfluchter Seemann"}, {"Verfluchter Marinesoldat"}, {"Erster Maat Snellig"}}},
    [290] = {n="Brechen des Fluchs", d="Besorgt den Geldkassettenschlüssel der INTREPID von Kapitän Halyndor.\nVerwendet den Schlüssel, um die Geldkassette der INTREPID zu öffnen.", tgo={{"Kapitän Halyndor"}}},
    [292] = {n="Das Auge von Paleth", d="Bringt Glorin Steelbrow das verfluchte Auge von Paleth."},
    [293] = {n="Die Reinigung des Auges", d="Bringt Erzbischof Benedictus das verfluchte Auge von Paleth. Ihr findet Benedictus in der Kathedrale des Lichts, in der Stadt Stormwind."},
    [294] = {n="Ormers Rache", d="Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr 10 scheckige Kreischer und 10 scheckige Raptoren tötet.", tgo={{"Scheckiger Raptor"}, {"Scheckiger Kreischer"}}},
    [295] = {n="Ormers Rache", d="Ormer Ironbraid möchte, dass Ihr 10 scheckige Sensenklauen- und 10 scheckige Scharfzahnraptoren tötet und dann zu ihm zu Whelgars Ausgrabungsstätte zurückkommt.", tgo={{"Scheckige Sensenklaue"}, {"Scheckiger Scharfzahn"}}},
    [296] = {n="Ormers Rache", d="Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr Sarlatan tötet und mit einer seiner Krallen zu ihm zurückkehrt, sobald Ihr die Aufgabe erledigt habt.", tgo={{"Sarlatan"}}},
    [297] = {n="Götzen sammeln", d="Bringt Magmar Fellhew 8 verzierte Steingötzen.", tgo={{"Geomant der Splittersteintroggs", "Buddler der Splittersteintroggs", "Berserkertrogg"}}},
    [298] = {n="Bericht über den Fortschritt der Ausgrabungen", d="Bringt Ironbands Fortschrittsbericht zu Jern Hornhelm in Thelsamar."},
    [299] = {n="Enthüllung der Vergangenheit", d="Ausgrabungsleiter Whelgar wünscht, dass Ihr die Ausgrabungsstätte nach den 4 fehlenden Tafel-Fragmenten durchkämmt, Ados, Modr, Golm und Neru.", objs={"Uraltes Relikt", "Lockere Erde"}},
    [301] = {n="Meldung in Ironforge", d="Bringt Ironbands Fortschrittsbericht zu Ausgrabungsleiter Stormpike."},
    [303] = {n="Der Dunkeleisenkrieg", d="Motley Garmason in Dun Modr möchte, dass Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet.", tgo={{"Dunkeleisenzwerg"}, {"Tunnelgräber der Dunkeleisenzwerge"}, {"Saboteur der Dunkeleisenzwerge"}, {"Demolierer der Dunkeleisenzwerge"}}},
    [304] = {n="Eine grausige Aufgabe", d="Tötet Balgaras den Niederträchtigen und bringt Longbraid dem Grimmigen vor Dun Modr sein Ohr.", tgo={{"Balgaras der Niederträchtige"}}},
    [305] = {n="Auf der Suche nach dem Ausgrabungstrupp", d="Tarrel Rockweaver möchte, dass Ihr zur Ausgrabungsstätte reist und dort Kontakt mit Merrin Rockweaver aufnehmt."},
    [306] = {n="Auf der Suche nach dem Ausgrabungstrupp", d="Kehrt mit Merrins Nachricht zu Tarrel Rockweaver zurück."},
    [307] = {n="Schmutzige Pfoten", d="Geht zur Silberbachmine und sucht 4 Sätze Bergarbeiter-Ausstattung zusammen.\nKehrt dann zu Gebirgsjäger Stormpike zurück.", objs={"Kisten der Minenarbeiterliga"}},
    [310] = {n="Bittere Rivalen", d="Vertauscht im Keller der Brauerei Donnerbräu in Kharanos ein Fass Donnerbier mit einem Fass Gerstenbräu."},
    [312] = {n="Tundra MacGranns gestohlene Vorräte", d="Holt Tundra MacGranns Trockenfleisch aus dem gestohlenen Fleisch-Spind in der Höhle von Eisbart dem Alten.", objs={"MacGranns Fleisch-Spind"}},
    [313] = {n="Der altgediente Bau", d="Sammelt 8 Wendigomähnen und bringt sie Pilot Stonegear.", tgo={{"Junger Wendigo", "Wendigo", "Edan der Heuler", "Eisbart der Alte", "Vagash", "Wendigoschamane", "Wendigoältester", "Eisheuler"}}},
    [314] = {n="Die Herde beschützen", d="Rudra Amberstill möchte, dass Ihr Vagash erschlagt und einen seiner Fangzähne zu ihr auf die Widder-Ranch bringt.", tgo={{"Vagash"}}},
    [317] = {n="Vorräte für Jetsteam", d="Sammelt 4 Brocken Eberfleisch und 2 dicke Bärenfelle und liefert sie bei Pilot Bellowfiz in Steelgrills Depot ab.", tgo={{"Steinhauereber", "Langschnauze", "Geiferzahn", "Prinzessin", "Gefolgsschwein", "Junger Geiferzahn", "Steinhauteber", "Großer Geiferzahn"}, {"Junger Schwarzbär", "Eisklauenbär", "Schwarzbär"}}},
    [318] = {n="Immerschimmer", d="Besorgt von Rejold Gerstenbräu in Brewnall ein Fässlein Immerschimmer."},
    [319] = {n="Ein Gefallen für etwas Immerschimmer", d="Tötet 6 Eisklauenbären, 8 alte Klippeneber sowie 8 Schneeleoparden und kehrt dann zu Rejold Gerstenbräu nach Brewnall zurück.", tgo={{"Eisklauenbär"}, {"Alter Klippeneber"}, {"Schneeleopard"}}},
    [320] = {n="Rückkehr zu Bellowfiz", d="Gebt Pilot Bellowfiz in Steelgrills Depot das Fässlein mit Immerschimmer."},
    [321] = {n="Lichtgeschmiedetes Eisen", d="Durchsucht das Wrack der FLYING OSPREY im Sumpfland."},
    [322] = {n="Gesegnete Waffe", d="Bringt Grimand Elmore in Stormwind die Kiste mit Lichtschmiedeblöcken."},
    [323] = {n="Bewährungsprobe", d="Vernichtet 15 Skeletträuber, 3 Skelettheiler sowie 3 Skelettwärter und kehrt danach zu Sven zurück.", tgo={{"Skeletträuber"}, {"Skelettheiler"}, {"Skelettwärter"}}},
    [324] = {n="Die verlorenen Blöcke", d="Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Steelbrow im Sumpfland zurück.", tgo={{"Räuber der Blaukiemen"}}},
    [325] = {n="Bewaffnet und bereit", d="Bringt Morbents Bann zu Sven im Dämmerwald."},
    [335] = {n="Ein nobles Bräu", d="Zardeth Blackclaw möchte, dass Ihr ihm eine Tilloaträne aus Dunkelhain und eine Bisamwurzel aus dem Sumpfland bringt.", objs={"Tilloaträne", "Bisamwurzel"}},
    [336] = {n="Ein nobles Bräu", d="Bringt Lord Wishock in der Halle der Bittsteller das Blackclaw-Starkbier."},
    [338] = {n="Die Grünen Hügel des Schlingendorntals", d="Sammelt die fehlenden Seiten des Manuskripts von \"Die Grünen Hügel des Schlingendorntals\". Wenn alle vier Kapitel vollständig sind, bringt sie zu Barnil zurück."},
