    [348] = {n="Schlingendornfieber", d="Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizracket.", tgo={{"Mokk der Wilde"}}},
    [349] = {n="Schlingendornfieber", d="Beute von: Nebeltalgorilla, Dschungeldonnerer, Wütender Silberrücken", tgo={{"Nebeltalgorilla", "Dschungeldonnerer", "Wütender Silberrücken", "Alter Nebeltalgorilla", "Silberrückenpatriarch", "König Mukla", "Blaumähnengorilla", "Groddoc-Affe"}}},
    [350] = {n="Auf einen alten Freund verlassen", d="Sprecht mit Elling Trias in Stormwind."},
    [351] = {n="Findet OOX-17/TN!", d="Bringt das Notsignal zum Leitroboter von Oglethorpe."},
    [353] = {n="Stormpikes Lieferung", d="Bringt das Päckchen für Stormpike zu Gebirgsjäger Stormpike am Loch Modan."},
    [373] = {n="Der nie verschickte Brief", d="Bringt den Brief nach Stormwind zum Stadtarchitekten Baros Alexston."},
    [377] = {n="Verbrechen und Strafe", d="Ratsherr Millstipe von Dunkelhain will, dass Ihr ihm die Hand von Dextren Ward bringt.", tgo={{"Dextren Ward"}}},
    [378] = {n="Tief empfundener Zorn", d="Motley Garmason in Dun Modr verlangt Kam Deepfurys Kopf.", tgo={{"Kam Deepfury"}}},
    [384] = {n="Eberrippchen in Biersauce", d="Ragnar Donnerbräu in Kharanos benötigt 6 Klippeneberrippchen und einen Krug Rhapsody-Malzbier.", tgo={{"Klippeneber", "Großer Klippeneber", "Alter Klippeneber", "Vernarbter Klippeneber"}, {}}},
    [385] = {n="Krokiliskenjagd", d="Besorgt 5 Stücke Krokiliskenfleisch und 6 Krokiliskenhäute für Marek Ironheart in der Weitschreiter-Lodge.", tgo={{"Salzwasserkrokilisk", "Sumpflandkrokilisk", "Junger Sumpflandkrokilisk", "Lochkrokilisk", "Riesiger Sumpflandkrokilisk", "Großer Lochkrokilisk", "Alter Salzwasserkrokilisk", "Schaudermagenkrokilisk"}, {"Salzwasserkrokilisk", "Sumpflandkrokilisk", "Junger Sumpflandkrokilisk", "Lochkrokilisk", "Riesiger Sumpflandkrokilisk", "Großer Lochkrokilisk", "Alter Salzwasserkrokilisk", "Schaudermagenkrokilisk"}}},
    [386] = {n="Verbrechen lohnt sich nicht", d="Bringt Wache Berton in Seenhain den Kopf von Targorr dem Schrecklichen.", tgo={{"Targorr der Schreckliche"}}},
    [387] = {n="Niederschlagung des Aufstandes", d="Aufseher Thelwater aus Stormwind will, dass Ihr im Verlies 10 gefangene Defias, 8 eingekerkerte Defias und 8 Aufrührer der Defias tötet.", tgo={{"Gefangener Defias"}, {"Eingekerkerter Defias"}, {"Aufrührer der Defias"}}},
    [388] = {n="Die Farbe von Blut", d="Nikova Raskol von Stormwind will, dass Ihr 10 rote Wollkopftücher für sie sammelt.", tgo={{"Dextren Ward", "Gefangener Defias", "Inhaftierter Defias", "Verurteilter Defias", "Eingekerkerter Defias", "Aufrührer der Defias", "Bazil Thredd", "Bruegal Eisenfaust"}}},
    [389] = {n="Bazil Thredd", d="Sprecht mit Aufseher Thelwater im Verlies."},
    [391] = {n="Aufstand im Verlies", d="Tötet Bazil Thredd und bringt seinen Kopf mit zurück zu Aufseher Thelwater im Verlies.", tgo={{"Bazil Thredd"}}},
    [392] = {n="Der seltsame Besucher", d="Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Baros Alexston."},
    [393] = {n="Schatten der Vergangenheit", d="Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Meister Mathias Shaw."},
    [394] = {n="Der Kopf des Ganzen", d="Sprecht mit Mathias Shaw in Stormwind."},
    [395] = {n="Das Ende der Bruderschaft", d="Sprecht mit Baros Alexston in Stormwind."},
    [396] = {n="Eine Audienz beim König", d="Liefert Baros Alexstons Bericht über die Bruderschaft der Defias bei König Varian Wrynn in der Burg Stormwind ab."},
    [400] = {n="Werkzeuge für Steelgrill", d="Liefert Beldin Steelgrill seine Werkzeuge."},
    [416] = {n="Rattenfang", d="Bringt Gebirgsjäger Kadrell in Thelsamar 12 Tunnelrattenohren.", tgo={{"Gezücht der Tunnelratten", "Späher der Tunnelratten", "Geomant der Tunnelratten", "Buddler der Tunnelratten", "Futterwühler der Tunnelratten", "Feldmesser der Tunnelratten", "Kobold der Tunnelratten"}}},
    [417] = {n="Pilotenrache", d="Tötet Marterklaue.\nBringt Pilot Hammerfoot die räudige Klaue des Bären und Hildelves Tagebuch.", tgo={{"Marterklaue"}}},
    [419] = {n="Der vermisste Pilot", d="Findet Pilot Hildelve."},
    [420] = {n="Senirs Beobachtungen", d="Überbringt Senir Whitebeard in Kharanos Grelins Bericht."},
    [432] = {n="Diese verfluchten Troggs!", d="Tötet für Großknecht Stonebrow im Gol'Bolar Steinbruch 6 Schädelhauer der Felsenkiefer.", tgo={{"Schädelhauer der Felsenkiefer"}}},
    [433] = {n="Im Dienste des Volkes", d="Tötet für Senator Mehr Stonehallow im Gol'Bolar Steinbruch 10 Knochenknacker der Felsenkiefer.", tgo={{"Knochenknacker der Felsenkiefer"}}},
    [434] = {n="Der Angriff!", d="Bleibt im Garten, bis Lord Gregor Lescovar und Marzon die Stille Klinge ihr Gespräch beendet haben. Schaltet sie danach beide aus, bevor Ihr nach Stormwind zu Elling Trias zurückkehrt.", tgo={{"Lord Gregor Lescovar"}, {"Marzon die Stille Klinge"}}},
