    [1920] = {n="Untersuchungen im Blauen Eremiten", d="Nehmt Euch die Inkantation der Manifestation und die Truhe mit Verwahrungskästen vom Tisch, hinter Jennea Cannon. Bringt 3 gefüllte Verwahrungskästen zu Jennea im Magiersanktum.", objs={"Gefüllte Verwahrungskästen", "Truhe mit Verwahrungskästen", "Inkantation der Manifestation"}},
    [1921] = {n="Materialsammlung", d="Bringt 10 Leinentücher und 6 aufgeladene Rissedelsteine zu Wynne Larson in Stormwind.", objs={"Versteckte Geldkassette", "Ramponierte Truhe", "Ramponierte Truhe", "Kisten der Minenarbeiterliga"}},
    [1938] = {n="Urs Abhandlung über Schattenmagie", d="Bringt 'Urs Abhandlung über Schattenmagie' zu Zaubermeister Andromath in Stormwind.", objs={"Urs Abhandlung über Schattenmagie"}},
    [1940] = {n="Makellose Spinnenseide", d="Bringt 8 Rollen makelloser Spinnenseide zu Wynne Larson in Stormwind.", tgo={{"Junges einer Schwarzen Witwe", "Aaskrabbler"}}},
    [1941] = {n="Managewirkte Robe"},
    [1942] = {n="Astralknotengewand"},
    [1947] = {n="Reise in die Marschen", d="Sprecht mit Tabetha."},
    [1948] = {n="Gegenstände der Macht", d="Bringt 1 Stück Jade und den vom Blitz aufgeladenen Dornbusch zu Tabetha in den Marschen von Dustwallow.", objs={"Zinnvorkommen", "Goldvorkommen", "Eisenvorkommen", "Vom Blitz aufgeladener Dornbusch"}},
    [1949] = {n="Verborgene Geheimnisse", d="Sprecht mit Magus Tirth in der schimmernden Ebene."},
    [1950] = {n="Der Knüller schlechthin", d="Bringt den Satz für Tirths Geldkassette in Erfahrung und kehrt zu Tirth zurück.", tgo={{"Eisenherz Johnson"}}},
    [1951] = {n="Rituale der Macht", d="Bringt das Buch 'Rituale der Macht' zu Tabetha in den Marschen von Dustwallow.", objs={"Rituale der Macht"}},
    [1952] = {n="Der Zauberstab des Magiers", d="Sprecht nach ihrem Ritual mit Tabetha."},
    [1953] = {n="Rückkehr in die Marschen", d="Sprecht mit Tabetha."},
    [1954] = {n="Die Höllenkugel", d="Bringt eine Höllenkugel zu Tabetha in den Marschen von Dustwallow.", tgo={{"Beschwörer der Burning Blade"}}},
    [1955] = {n="Die Austreibung", d="Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", tgo={{"Dämon der Kugel"}}},
    [1956] = {n="Macht in Uldaman", d="Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Marschen von Dustwallow zu Tabetha.", tgo={{"Obsidianschildwache"}}},
    [1957] = {n="Manawogen", d="Vernichtet 12 Manawogen innerhalb des Zeitlimits.", tgo={{"Manawoge"}}},
    [1958] = {n="Himmlische Macht"},
    [2038] = {n="Bingles' verschwundene Werkzeuge", d="Sucht Bingles' Werkzeuge und bringt sie ihm zurück. Es sind:\nBingles' Schraubenschlüssel, Bingles' Schraubendreher, Bingles' Hammer und Bingles' Sprengstofftube.", objs={"Bingles' Werkzeugeimer", "Bingles Superspreng"}},
    [2039] = {n="Sucht Bingles", d="Sucht Bingles Blastenheimer am Loch Modan."},
    [2040] = {n="Unterirdischer Angriff", d="Holt das Gnoam-Sprecklesprocket aus den Todesminen und bringt es Shoni der Schtillen in Stormwind.", tgo={{"Sneeds Schredder"}}},
    [2118] = {n="Verseuchtes Land", d="Fangt einen lebenden tollwütigen Distelbären und bringt ihn zu Tharnariun.", tgo={{"Tollwütiger Distelbär"}}},
    [2138] = {n="Ausrottung der Infizierten", d="Befreit den Wald von 20 tollwütigen Distelbären und kehrt dann zu Tharnariun Treetender in Dunkelküste zurück.", tgo={{"Tollwütiger Distelbär"}}},
    [2139] = {n="Tharnariuns Hoffnung", d="Sucht und tötet die Höhlenmutter.", tgo={{"Höhlenmutter"}}},
    [2158] = {n="Ruhe und Entspannung", d="Sprecht im Gasthaus Zur Höhle des Löwen mit Gastwirt Farley."},
    [2159] = {n="Dolanaar-Lieferung", d="Bringt die Dolanaar-Lieferung zu Gastwirt Keldamyr."},
    [2160] = {n="Vorräte für Tannok", d="Bringt die Kiste mit Gasthausvorräten zu Tannok Frosthammer in Kharanos."},
    [2198] = {n="Die zerrissene Halskette", d="Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren."},
    [2199] = {n="Lehren haben ihren Preis", d="Bringt fünf Silberbarren zu Talvash del Kissel in Ironforge.", objs={"Ramponierte Truhe", "Ramponierte Truhe", "Robuste Truhe"}},
    [2200] = {n="Rückkehr nach Uldaman", d="Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt."},
    [2201] = {n="Suche nach den Edelsteinen", d="Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat.\nAus dem Tagebuch, wisst Ihr...\n* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.\n* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.\n* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen.", tgo={{}, {"Grimlok"}, {}}, objs={"Schattenschmiedecache", "Verdächtige Urne"}},
    [2204] = {n="Restaurierung der Halskette", d="Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Ironforge ab.", tgo={{"Archaedas"}}},
    [2205] = {n="Aufsuchen des SI: 7", d="Liefert Keryn Sylvius' Päckchen an Meister Mathias Shaw in der Kaserne von Stormwind."},
    [2206] = {n="Schneller Eingriff", d="Sucht den Dockmeister der Defias und beschafft den Lieferzeitplan für Meister Mathias Shaw.", tgo={{"Dockmeister der Defias"}}},
    [2218] = {n="Straße der Rettung", d="Sprecht mit Hulfdan Blackbeard in Ironforge."},
    [2238] = {n="Einfache List", d="Sucht Onin MacHammar bei Gnomeregan."},
    [2239] = {n="Onins Bericht", d="Bringt Onins Bericht zu Hulfdan in Ironforge."},
    [2240] = {n="Die geheime Kammer", d="Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Stormpike Bericht."},
    [2241] = {n="Der Apfel fällt", d="Bringt Jannoks Rose zu Syurna in Darnassus."},
    [2242] = {n="Das Schicksal ruft", d="Sucht Sethir den Uralten und bringt alle Hinweise, die Ihr finden könnt, zu Syurna.", tgo={{"Sethir der Uralte"}}},
    [2278] = {n="Die Platinscheiben", d="Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon.", tgo={{"Bewahrer der Lehren von Norgannon"}}},
    [2279] = {n="Die Platinscheiben", d="Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga nach Ironforge."},
    [2281] = {n="Rendezvous im Rotkammgebirge", d="Geht nach Seenhain im Rotkammgebirge und sprecht mit Lucius."},
    [2282] = {n="Althers Mühle", d="Öffnet Lucius' Schließkassette, nehmt die Marke der Diebeskunst heraus und bringt sie zu Lucius nach Seenhain.", objs={"Lucius' Schließkassette"}},
    [2358] = {n="Hörner von Nez'ra", d="Bringt die Hörner von Nez'ra zu Arantir nach Seenhain.", tgo={{"Gath'Ilzogg", "Held der Blackrock", "Schattenzauberer der Blackrock", "Renegat der Blackrock", "Grunzer der Blackrock", "Kundschafter der Blackrock", "Tharil'zun", "Fährtenleser der Blackrock"}}},
    [2359] = {n="Klavens Turm", d="Stehlt den Turmschlüssel der Defias, brecht in den Turm der Defias ein und stellt fest, was sich in der Dämmerwaldtruhe befindet. Bringt Mathias Shaw in Stormwind dann alle Informationen über das, was Ihr herausgefunden habt. Lest Kearnens Tagebuch, um neue Erkenntnisse über den Turm zu erlangen.", tgo={{}, {"Missgestaltete Drohne der Defias"}}, objs={"Dämmerwaldtruhe"}},
    [2360] = {n="Mathias und die Defias", d="Reist nach Westfall und sucht Agentin Kearnen. Sie wird Euch Bericht erstatten."},
    [2361] = {n="Restaurierung der Halskette"},
    [2398] = {n="Die verschollenen Zwerge", d="Sucht in Uldaman nach Baelog."},
    [2399] = {n="Die sprießenden Wedel"},
    [2418] = {n="Kraftsteine", d="Bringt Rigglefuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum.", tgo={{"Feldmesser der Schattenschmiede", "Grobian der Schattenschmiede", "Buddler der Schattenschmiede", "Reliktjäger der Schattenschmiede", "Dunkelzauberer der Schattenschmiede", "Archäologe der Schattenschmiede", "Geologe der Schattenschmiede", "Wegelagerer der Schattenschmiede"}, {"Feldmesser der Schattenschmiede", "Grobian der Schattenschmiede", "Buddler der Schattenschmiede", "Reliktjäger der Schattenschmiede", "Dunkelzauberer der Schattenschmiede", "Archäologe der Schattenschmiede", "Geologe der Schattenschmiede", "Wegelagerer der Schattenschmiede"}}},
    [2438] = {n="Der smaragdgrüne Traumfänger", d="Bringt den smaragdgrünen Traumfänger zu Tallonkai Swiftroot in Dolanaar.", objs={"Tallonkais Kommode"}},
    [2439] = {n="Die Platinscheiben", d="Bringt Euren Belohnungsgutschein zu Dinita Stonemantle im Gewölbe von Ironforge."},
    [2459] = {n="Ferocitas der Traumfresser", d="Tallonkai Swiftroot aus Dolanaar möchte, dass Ihr 7 Mystiker der Knarzklauen tötet und das verlorene Juwel findet.", tgo={{"Mystiker der Knarzklauen"}, {}}},
    [2500] = {n="Reagenzien-Suche im Ödland", d="Beschafft die Reagenzien, die Ghak Healtouch aus dem Ödland braucht, und bringt sie ihm nach Thelsamar.", tgo={{"Verhungernder Bussard", "Bussard", "Riesenbussard", "Entflogener Bussard"}, {"Klippenkojote", "Wilder Klippenkojote", "Alter Klippenkojote", "Tollwütiger Klippenkojote"}, {"Felselementar", "Kleiner Felselementar", "Großer Felselementar", "Botschafter Infernus", "Rumpler", "Wütender Felselementar", "Fam'retor-Wächter", "Smoldar"}}},
    [2518] = {n="Tränen des Mondes", d="Priesterin A'moora vom Tempel des Mondes in Darnassus möchte, dass Ihr ihr Lady Sathrahs silbrige Spinndrüsen bringt.", tgo={{"Lady Sathrah"}}},
    [2519] = {n="Der Tempel des Mondes", d="Schwester Aquinne möchte, dass Ihr im Tempel des Mondes mit Priesterin A'moora sprecht."},
    [2520] = {n="Sathrahs Opferung", d="Priesterin A'moora möchte, dass Ihr Lady Sathrahs silbrige Spinndrüsen am Brunnen innerhalb des Tempels ablegt und dann zu ihr zurückkehrt.", objs={"Brunnen des Tempels des Mondes"}},
    [2581] = {n="Kicherfangunterkiefer", d="Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange.", tgo={{"Verhungernder Kicherfang", "Kicherfanghyäne", "Verheerer"}, {"Aschmähneneber", "Hölleneber", "Suhlaman"}, {"Skorpokstecher", "Clack der Häscher"}}},
    [2583] = {n="Lebenskraft des Ebers", d="Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn.", tgo={{"Aschmähneneber", "Hölleneber", "Suhlaman"}, {"Skorpokstecher", "Clack der Häscher"}, {"Rotsteinbasilisk", "Rotsteinkristallhaut", "Todesauge"}}},
    [2585] = {n="Der Entscheidungsschlag", d="Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge.", tgo={{"Skorpokstecher", "Clack der Häscher"}, {"Schwarzer Töter", "Knochenpflücker"}, {"Aschmähneneber", "Hölleneber", "Suhlaman"}}},
    [2601] = {n="Der Biss des Basilisken", d="Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen.", tgo={{"Rotsteinbasilisk", "Rotsteinkristallhaut", "Todesauge"}, {"Schwarzer Töter", "Knochenpflücker"}}},
    [2603] = {n="Lebensenergie des Geiers", d="Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer.", tgo={{"Schwarzer Töter", "Knochenpflücker"}, {"Verhungernder Kicherfang", "Kicherfanghyäne", "Verheerer"}}},
    [2605] = {n="Der durstige Goblin", d="Beschafft Euch eine volle Taudrüse und bringt sie nach Gadgetzan zu Marin Noggenfogger.", tgo={{"Disteltausammler"}}},
    [2606] = {n="Dem guten Geschmacke", d="Marin Noggenfogger möchte, dass Ihr in Gadgetzan mit Sprinkle sprecht."},
    [2607] = {n="Die Berührung von Zanzil", d="Sprecht im Keller der Kaserne mit Doc Mixilpixil."},
    [2608] = {n="Die Berührung von Zanzil", d="Ihr solltet Euch /hinlegen, damit Doc Mixilpixil Euch untersuchen kann. Denn wie soll er ein Heilmittel finden, wenn er die Ursache nicht finden kann?"},
    [2609] = {n="Die Berührung von Zanzil", d="Bringt Doc Mixilpixil 1 Bündel einfache Wildblumen, 1 verbleite Phiole, 1 Bronzeröhre und 1 Rolle blassgelben Seidenfaden. So eine 'Itis' heilt sich nicht von selbst, junger Herr.", tgo={{"Bernard Gump", "Felicia Gump"}, {"Edna Mullby", "Maria Lumere", "Sloan McCoy", "Keldric Boucher", "Jasper Fel", "Eldraeith"}, {}, {}}, objs={"Kasten mit verschiedenen Ersatzteilen", "Spule des Lichts Chartreuse Seidenfaden"}},
    [2641] = {n="Sprinkles Geheimzutat", d="Sprinkle in Gadgetzan möchte, dass Ihr einen violetten Tragan sucht und ihr bringt.", objs={"Violetter Tragan"}},
    [2661] = {n="Lieferung für Marin", d="Sprinkle möchte, dass Ihr das violette Pulver nach Gadgetzan zu Marin Noggenfogger bringt."},
    [2662] = {n="Noggenfogger-Elixier", d="Marin Noggenfogger möchte, dass Ihr ihn nochmals ansprecht, wenn er sein Elixier fertig gestellt hat."},
    [2745] = {n="Eindringen ins Schloss", d="Sprecht in Schloss Stormwind mit Tyrion."},
    [2746] = {n="Nicht unwichtige Gegenstände", d="Bringt 3 Stück Seidenstoff und 2 frische Äpfel von Clara nach Stormwind zu Tyrion.", objs={"Alteracgranit", "Ramponierte Truhe", "Robuste Truhe", "Claras frische Äpfel"}},
    [2766] = {n="Findet OOX-22/FE!", d="Bringt das Notrufsignal zu Oglethorpes Leitroboter in einer Höhle in der Nähe des Wildschrammtals."},
    [2767] = {n="Die Rettung von OOX-22/FE", d="Eskortiert OOX-22/FE zum Dock an der Vergessenen Küste und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay."},
    [2768] = {n="Wünschel-mato-Rute", d="Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgewhizzle.", tgo={{"Sergeant Bly"}}},
    [2770] = {n="Gahz'rilla", d="Bringt Wizzle Brassbolts in der schimmernden Ebene Gahz'rillas energiegeladene Schuppe.", tgo={{"Gahz'rilla"}}},
    [2781] = {n="GESUCHT: Kalif Skorpidstich", d="Bringt Chefingenieur Bilgewhizzle in Gadgetzan den Kopf von Kalif Skorpidstich.", tgo={{"Kalif Skorpidstich"}}},
    [2821] = {n="Das Zeichen der Qualität", d="Bringt Pratt McGrubben in der Festung Feathermoon 10 dicke Yetibälge.", tgo={{"Wildschrammyeti", "Titanischer Wildschrammyeti", "Wütender Wildschrammyeti", "Blutschrei der Pirscher", "Lauernder Wildschrammyeti"}}},
    [2844] = {n="Der Riesenwächter", d="Findet das verlorene Nachtelfen-Mädchen."},
    [2845] = {n="Streunende Shay", d="Nehmt Shays Glocke aus der Truhe.\nBegleitet Shay Leafrunner zu Felsbeißers Lager.", objs={"Shays Truhe"}},
    [2846] = {n="Tiara der Tiefen", d="Bringt die Tiara der Tiefen zu Tabetha in den Marschen von Dustwallow.", tgo={{"Wasserbeschwörerin Velratha"}}},
    [2864] = {n="Tran'rek", d="Sprecht mit Tran'rek in Gadgetzan."},
    [2865] = {n="Skarabäuspanzerschalen", d="Bringt Tran'rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen.", tgo={{"Skarabäus"}}},
    [2866] = {n="Die Ruinen von Solarsal", d="Erforscht die Ruinen von Solarsal und findet etwas über die Anwesenheit der Naga dort heraus."},
    [2867] = {n="Kehrt zur Festung Feathermoon zurück", d="Kehrt zu Shandris Feathermoon in der Festung Feathermoon zurück und berichtet von Euren Entdeckungen."},
    [2869] = {n="Gegen die Hasskämme", d="Bringt Latronicus Moonspear in der Festung Feathermoon 10 Nagaschuppen der Hasskämme.", tgo={{"Krieger der Hasskämme", "Wellenreiter der Hasskämme", "Schlangenwache der Hasskämme", "Myrmidone der Hasskämme", "Kreischer der Hasskämme", "Zauberhexerin der Hasskämme", "Sirene der Hasskämme", "Lady Szallah"}}},
    [2870] = {n="Gegen Lord Shalzaru", d="Vernichtet Lord Shalzaru und bringt dann Latronicus Moonspear in der Festung Feathermoon das geheimnisvolle Relikt, das er entdeckt hat.", tgo={{"Lord Shalzaru"}}},
    [2871] = {n="Überbringung des Relikts", d="Bringt das geheimnisvolle Relikt zu Vestia Moonspear in der Festung Feathermoon."},
    [2872] = {n="Stoleys Schuld", d="Sprecht mit Stoley in Steamwheedle."},
    [2873] = {n="Stoleys Lieferung", d="Bringt Stoleys Lieferung zu Stoley nach Steamwheedle.", objs={"Gestohlene Fracht"}},
    [2874] = {n="Lieferung für MacKinley", d="Bringt Stoleys Flasche zu \"Seewolf\" MacKinley in Booty Bay."},
    [2875] = {n="GESUCHT: Andre Feuerbart", d="Bringt Sicherheitschef Bilgewhizzle in Steamwheedle Andres Kopf.", tgo={{"Andre Feuerbart"}}},
    [2877] = {n="Skulk Rock-Aufräumen", d="Tötet 10 grüne Schlämme sowie 10 jadegrüne Brühschlammer und meldet Euch dann wieder bei Fraggar Thundermantle in Aerie Peak.", tgo={{"Grüner Schlamm"}, {"Jadegrüner Brühschlammer"}}},
    [2879] = {n="Der Stock von Equinex", d="Aktiviert Troyas Stock und findet den Equinex-Monolithen.", objs={"Equinex-Monolith"}},
    [2880] = {n="Kopfgeld für Trollhalsketten", d="Bringt Fraggar Thundermantle in Aerie Peak 5 Troll-Stammeshalsketten.", tgo={{"Axtwerfer der Vilebranch", "Hexendoktorin der Vilebranch", "Kopfjäger der Vilebranch", "Schattenzauberin der Vilebranch", "Berserker der Vilebranch", "Balgabzieherin der Vilebranch", "Schattenjäger der Vilebranch", "Bluttrinker der Vilebranch"}}},
    [2904] = {n="Eine schöne Bescherung", d="Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Booty Bay."},
    [2922] = {n="Rettet Techbots Hirn!", d="Bringt Techbots Speicherkern zu Tüftlermeister Overspark nach Ironforge.", tgo={{"Techbot"}}},
    [2923] = {n="Tüftlermeister Overspark", d="Sprecht mit Tüftlermeister Overspark in Ironforge."},
    [2924] = {n="Grundlegende Artifixe", d="Bringt Klockmort Spannerspan in Ironforge 12 grundlegende Artifixe.", objs={"Künstlicher Extrapolator"}},
    [2925] = {n="Klockmorts Grundlagen", d="Sprecht mit Klockmort Spannerspan in Ironforge."},
    [2926] = {n="Gnogaine", d="Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Togglevolt nach Kharanos zurück.", tgo={{"Bestrahlter Eindringling", "Bestrahlter Plünderer"}}},
    [2927] = {n="Der Tag danach", d="Sprecht mit Ozzie Togglevolt in Kharanos."},
    [2928] = {n="Gyrobohrmatische Exkavation", d="Bringt 24 robomechanische Innereien zu Shoni nach Stormwind.", tgo={{"Einbuddler der Tiefentroggs", "Wegelagerer der Tiefentroggs", "Eindringling der Tiefentroggs", "Häscher der Tiefentroggs", "Agent der Dunkeleisenzwerge", "Bestrahlter Eindringling", "Bestrahlter Brühschleimer", "Ätzender Lauerer"}}},
    [2929] = {n="Der große Verrat", d="Reist nach Gnomeregan und tötet Robogenieur Thermaplugg. Kehrt zu Hochtüftler Mekkatorque zurück, wenn der Auftrag ausgeführt ist.", tgo={{"Robogenieur Thermaplugg"}}},
    [2930] = {n="Datenrettung", d="Bringt Mechanikermeister Castpipe in Ironforge eine Prismalochkarte.", objs={"Matrix Punchograph 3005-D"}},
    [2931] = {n="Castpipes Auftrag", d="Sprecht mit Mechanikermeister Castpipe in Ironforge."},
    [2939] = {n="Auf der Suche nach Wissen", d="Sprecht mit Daryn Lightwind im Dorf Rut'theran."},
    [2940] = {n="Feralas: Ein historischer Abriss", d="Fragt Daryn Lightwind, ob Ihr Euch ihr Buch ausleihen dürft."},
    [2941] = {n="Der Borger", d="Bringt den Brief zu Curgle Cranklehop nach Tanaris."},
    [2942] = {n="Der Morgenstein", d="Bringt den funkelnden Stein und den Stock von Equinex zu Troyas Moonbreeze in die Festung Feathermoon."},
    [2943] = {n="Rückkehr zu Troyas", d="Liefert das Buch bei Troyas Moonbreeze in der Festung Feathermoon ab."},
    [2944] = {n="Der Superschnapper FX", d="Benutzt den Superschnapper FX, um einen Schnappschuss von Gammerita zu machen, und kehrt dann zu Daryn Lightwind nach Rut'theran zurück.", tgo={{"Gammerita"}}},
    [2945] = {n="Schmutzverkrusteter Ring", d="Findet einen Weg, den schmutzverkrusteten Ring zu säubern."},
    [2946] = {n="Mal sehen, was passiert...", d="Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem."},
    [2947] = {n="Die Rückkehr des Rings", d="Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist."},
    [2954] = {n="Der Steinbehüter", d="Findet den Zweck des Steinbehüters von Norgannon heraus und interagiert dann mit dem Uldum-Sockel in der Tanariswüste.", tgo={{"Steinbehüter von Norgannon"}}},
    [2962] = {n="Das einzige Heilmittel ist mehr grünes Leuchten", d="Reist nach Gnomeregan und bringt etwas von der hoch konzentrierten radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen.\nOzzie wird außerdem Eure schwere bleierne Phiole benötigen, nachdem die Aufgabe erledigt ist.", tgo={{"Bestrahlter Brühschleimer", "Ätzender Lauerer", "Bestrahlter Schrecken"}}},
    [2963] = {n="Omen von Uldum", d="Sprecht mit Historiker Karnik in der Halle der Forscher in Ironforge."},
    [2964] = {n="Eine zukünftige Aufgabe", d="Sprecht mit Hochforscher Magellas in Ironforge."},
    [2969] = {n="Freiheit für alle Kreaturen", d="Befreit mit dem Bambuskäfigschlüssel die Grimmlingflitzer aus dem Pferch im Grimmtotemlager. Kindal Moonweaver sowie mindestens 6 Grimmlingflitzer müssen überleben.\nIhr habt 6 Minuten, bis Kindal beschließt, dass es Zeit zum Rückzug und Eure Aufgabe gescheitert ist."},
    [2970] = {n="Gerechtigkeit üben", d="Tötet 12 Naturalisten der Grimmtotem, 10 Räuber der Grimmtotem sowie 6 Schamanen der Grimmtotem und kehrt dann zu Jer'kai Moonweaver nach Feralas zurück.", tgo={{"Naturalist der Grimmtotem"}, {"Räuber der Grimmtotem"}, {"Schamane der Grimmtotem"}}},
    [2972] = {n="Gerechtigkeit üben", d="Bringt Jer'kais Siegelring zu Hohepriesterin Tyrande Whisperwind nach Darnassus."},
    [2977] = {n="Rückkehr nach Ironforge", d="Sprecht mit Historiker Karnik in Ironforge."},
    [2982] = {n="Die obere Wildnis", d="Angelas Moonbreeze will, dass Ihr 8 Hexenmeister der Gordunni, 8 Schamanen der Gordunni und 8 Schläger der Gordunni tötet.", tgo={{"Hexenmeister der Gordunni"}, {"Schamane der Gordunni"}, {"Schläger der Gordunni"}}},
    [2988] = {n="Käfige der Witherbark", d="Durchsucht die Käfige in den beiden Dörfern der Witherbark und kehrt dann zu Greifenmeister Talonaxe zurück.", objs={"Erster Käfig der Witherbark", "Zweiter Käfig der Witherbark", "Dritter Käfig der Witherbark"}},
    [2989] = {n="Der Altar von Zul", d="Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Talonaxe zurück."},
    [2990] = {n="Thadius Grimshade", d="Bringt Scharfschnabels Feder zu Thadius Grimshade in die verwüsteten Lande."},
    [2991] = {n="Nekrums Medaillon", d="Bringt Thadius Grimshade in den verwüsteten Landen Nekrums Medaillon.", tgo={{"Nekrum der Ausweider"}}},
    [2999] = {n="Foliant der Offenbarung", d="Sprecht mit Tiza Battleforge in Ironforge."},
    [3022] = {n="Vorsichtig behandeln", d="Bringt die sorgfältig verpackte Kiste zu Erelas Ambersky in das Dorf Rut'theran."},
    [3042] = {n="Trollaushärter", d="Bringt 20 Phiolen Trollaushärter zu Trenton Lighthammer in Gadgetzan.", tgo={{"Schattenzauberer der Sandfury", "Bluttrinker der Sandfury", "Hexendoktor der Sandfury", "Schattenjäger der Sandfury", "Seelenfresser der Sandfury", "Häuptling Ukorz Sandscalp", "Theka der Märtyrer", "Henker der Sandfury"}}},
    [3100] = {n="Einfacher Brief", d="Lest den einfachen Brief und sprecht mit Llane Beshere in der Abtei von Nordhain."},
    [3101] = {n="Geweihter Brief", d="Lest den geweihten Brief und sprecht mit Bruder Sammuel in der Abtei von Nordhain."},
    [3102] = {n="Verschlüsselter Brief", d="Lest den verschlüsselten Brief und sprecht mit Jorik Kerridan im Stall hinter der Abtei von Nordhain."},
    [3103] = {n="Geheiligter Brief", d="Lest den geheiligten Brief und sprecht mit Priesterin Anetta in der Abtei von Nordhain."},
    [3104] = {n="Glyphen-Brief", d="Lest den mit Glyphen versehenen Brief und sprecht mit Kheldon Bremen in der Abtei von Nordhain."},
    [3105] = {n="Besudelter Brief", d="Lest den besudelten Brief und sprecht mit Drusilla La Salle nahe der Abtei von Nordhain."},
    [3106] = {n="Einfache Rune", d="Lest die einfache Rune und sprecht mit Thran Khorman im Coldridgetal."},
    [3107] = {n="Geweihte Rune", d="Lest die geweihte Rune und sprecht mit Bromos Grummner im Coldridgetal."},
    [3108] = {n="Geätzte Rune", d="Lest die geätzte Rune und sprecht mit Thorgas Grimson im Coldridgetal."},
    [3109] = {n="Verschlüsselte Rune", d="Lest die verschlüsselte Rune und sprecht mit Solm Hargrin im Coldridgetal."},
    [3110] = {n="Geheiligte Rune", d="Lest die geheiligte Rune und sprecht mit Branstock Khalder in Anvilmar."},
    [3112] = {n="Einfaches Memorandum", d="Lest das einfache Memorandum und sprecht mit Thran Khorman im Coldridgetal."},
    [3113] = {n="Verschlüsseltes Memorandum", d="Lest das verschlüsselte Memorandum und sprecht mit Solm Hargrin im Coldridgetal."},
    [3114] = {n="Glyphen-Memorandum", d="Lest das mit Glyphen versehene Memorandum und sprecht mit Marryk Nurribit in Anvilmar oberhalb des Coldridgetals."},
    [3115] = {n="Besudeltes Memorandum", d="Lest das besudelte Memorandum und sprecht mit Alamar Grimm in Anvilmar oberhalb des Coldridgetals."},
    [3116] = {n="Einfaches Siegelzeichen", d="Lest das einfache Siegelzeichen und sprecht mit Alyissia in Shadowglen."},
    [3117] = {n="Geätztes Siegelzeichen", d="Lest das geätzte Siegelzeichen und sprecht mit Ayanna Everstride oben auf Aldrassil in Shadowglen."},
    [3118] = {n="Verschlüsselte Siegelzeichen", d="Lest das verschlüsselte Siegelzeichen und sprecht mit Frahun Shadwhisper in Shadowglen."},
    [3119] = {n="Geheiligtes Siegelzeichen", d="Lest das geheiligte Siegel und sprecht mit Shanda in Aldrassil."},
    [3120] = {n="Tiefgrünes Siegelzeichen", d="Lest das tiefgrüne Siegel und sprecht mit Mardant Strongoak im großen Baum Aldrassil in Shadowglen."},
    [3130] = {n="Gegen die Hasskämme", d="Meldet Euch bei Latronicus Moonspear in der Festung Feathermoon."},
    [3161] = {n="Gahz'ridian", d="Marvon Rivetseeker in Tanaris möchte, dass Ihr 30 Gahz'ridian-Ornamente sammelt.", objs={"Gahz'ridian"}},
    [3181] = {n="Das Horn der Bestie", d="Bringt Margols gigantisches Horn zu Gebirgsjägerin Pebblebitty."},
    [3182] = {n="Besitznachweis", d="Bringt Margols gigantisches Horn zu Kurator Thorius in Ironforge."},
    [3201] = {n="Endlich!", d="Bringt die Urkunde für die Tat zurück zu Gebirgsjägerin Pebblebitty."},
    [3361] = {n="Dilemma eines Flüchtlings", d="Bringt Felix Whindlebolt in Anvilmar den Kasten, die Truhe und den Bolzeneimer von Felix.", objs={"Felix' Kasten", "Felix' Truhe", "Felix' Bolzeneimer"}},
    [3362] = {n="Disteltal", d="Tran'rek in Gadgetzan möchte, dass Ihr 8 knorrige Distelwandler und 8 Distelwurzelformer erledigt.", tgo={{"Knorriger Distelwandler"}, {"Distelwurzelformer"}}},
    [3364] = {n="Lieferung des kochend heißen Morgengebräus", d="Bringt ein kochend heißes Morgengebräu zu Durnan Furcutter ins Anvilmar hinein, bevor es innerhalb von fünf Minuten kalt wird!"},
    [3365] = {n="Den Becher zurückbringen", d="Bringt Nori Pridedrift den Becher zurück."},
    [3367] = {n="Suntara-Steine", d="Helft Dorius, zurück nach Ironforge zu kommen."},
    [3368] = {n="Suntara-Steine", d="Bringt den angesengten Brief zu Thorius in Ironforge. Er befindet sich in der Halle der Forscher."},
    [3371] = {n="Zwergengerechtigkeit", d="Kehrt zur sengenden Schlucht zurück und sucht Dorius' Archäologenteam."},
    [3372] = {n="Erlöst sie", d="Sucht das mysteriöse Artefakt, das im Norden von den Twilight-Hammer bewacht wird.", objs={"Twilight-Artefakt"}},
    [3373] = {n="Die Essenz des Eranikus", d="Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet."},
    [3377] = {n="Gebet an Elune", d="Hört Zamaels Geschichte.", tgo={{"Zamael Lunthistle"}}},
    [3378] = {n="Gebet an Elune", d="Findet das Gebet an Elune und bringt es zu Astarii Starseeker in Darnassus.", tgo={{"Twilight-Dunkelschamane", "Twilight-Feuerwache", "Twilight-Geomant", "Twilight-Götzendiener"}}},
    [3441] = {n="Göttliche Vergeltung", d="Lasst Velarok Windblade seine Geschichte erzählen.", tgo={{"Kalaran Windblade"}}},
    [3442] = {n="Die fehlerlose Flamme", d="Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Velarok Windblade.", tgo={{"Lodernder Elementar", "Infernoelementar", "Magmaelementar"}, {"Ausgehärteter Kriegsgolem", "Schwerer Kriegsgolem", "Magmaelementar"}}},
    [3443] = {n="Das Schmieden des Schafts", d="Bringt 8 mit Thorium beschichtete Dolche zu Velarok Windblade.", tgo={{"Geologe der Dunkeleisenzwerge", "Dampfschmied der Dunkeleisenzwerge", "Sklavenarbeiter", "Sklavenhändler der Dunkeleisenzwerge", "Zuchtmeister der Dunkeleisenzwerge", "Stahlschieber der Dunkeleisenzwerge", "Wachposten der Dunkeleisenzwerge"}}},
    [3444] = {n="Der runde Stein", d="Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet.", objs={"Marvons Truhe"}},
    [3445] = {n="Der versunkene Tempel", d="Sucht Marvon Rivetseeker in Tanaris."},
    [3446] = {n="In die Tiefen", d="Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends."},
    [3447] = {n="Das Geheimnis des Kreises", d="Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt."},
    [3452] = {n="Die Ummantelung der Flamme", d="Bringt ein Symbol von Ragnaros zu Velarok Windblade.", tgo={{"Twilight-Dunkelschamane", "Twilight-Feuerwache", "Twilight-Geomant", "Twilight-Götzendiener"}}},
    [3453] = {n="Die Fackel der Vergeltung", d="Wartet bis Velarok Windblade die Fackel der Vergeltung vollendet hat.", tgo={{"Kalaran Windblade"}}},
    [3454] = {n="Die Fackel der Vergeltung", d="Nehmt die Fackel der Vergeltung."},
    [3462] = {n="Knappe Maltrake", d="Sprecht mit dem Knappen Maltrake."},
    [3463] = {n="Setzt sie in Brand!", d="Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt.", objs={"Wachposten-Kohlenpfanne"}},
    [3481] = {n="Plunder...", d="Öffnet die Truhe."},
    [3519] = {n="Ein Freund in Not", d="Sprecht mit Dirania Silvershine in Shadowglen."},
    [3520] = {n="Kreischergeister", d="Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück.", tgo={{"Kreischergeist"}}},
    [3521] = {n="Iverrons Gegengift", d="Sammelt 7 Hyazinth-Pilze, 4 Mondblütenlilien und 1 Waldwebersekret für Dirania Silvershine in Shadowglen.", tgo={{"Grell", "Grellkin"}, {}, {"Waldweberspinne"}}, objs={"Mondblütenlilie"}},
    [3522] = {n="Iverrons Gegengift", d="Bringt Iverrons Gegengift zu Iverron, bevor die Zeit um ist. Ihr findet Iverron bei der Höhle im Norden."},
    [3523] = {n="Geißel der Niederungen", d="Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab."},
    [3524] = {n="An Land gespült", d="Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück.", objs={"Gestrandete Meereskreatur"}},
    [3525] = {n="Ausschalten des Götzen", d="Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen.\nBeschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten."},
    [3527] = {n="Die Prophezeiung von Mosh'aru", d="Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris.", tgo={{"Theka der Märtyrer", "Theka der Märtyrer Gestaltwandlung"}, {"Wasserbeschwörerin Velratha"}}},
    [3528] = {n="Der Gott Hakkar", d="Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris."},
    [3566] = {n="Erhebt Euch, Obsidion!", d="Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Ironforge mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion.", tgo={{"Lathoric der Schwarze"}, {"Obsidion"}}},
    [3636] = {n="Das Licht bringen", d="Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln von Razorfen tötet.", tgo={{"Amnennar der Kältebringer"}}},
    [3661] = {n="Elunes Lieblinge?", d="Sammelt 15 Wildekinfedern aus dem Hinterland für Erelas Ambersky in Rut'theran.", objs={"Wildekinfeder"}},
    [3701] = {n="Die glimmenden Ruinen von Thaurissan", d="Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt.", objs={"Thauris-Relikt"}},
    [3702] = {n="Die glimmenden Ruinen von Thaurissan", d="Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan.", tgo={{"Königliche Historikerin Archesonus"}}},
    [3721] = {n="Ein eigener OOX"},
    [3741] = {n="Hilarys Halskette", d="Sucht Hilarys Halskette und bringt sie Hilary in Seenhain zurück.", objs={"Glitzernder Matsch"}},
    [3765] = {n="Verderbnis in der Fremde", d="Reist zu Gershala Nightwhisper in Auberdine."},
    [3783] = {n="Sind wir endlich da, Yeti?", d="Sammelt 10 dicke Yetifelle für Umi Rumplesnicker in Everlook.", tgo={{"Wilder Eisdistelyeti", "Eisdistelyeti"}}},
    [3801] = {n="Dunkeleisenerbe", d="Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten."},
    [3802] = {n="Dunkeleisenerbe", d="Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright.", tgo={{"Fineous Darkvire"}}},
    [3823] = {n="Die Feuermagenoger auslöschen", d="Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen und kehrt zu Oralius zurück, wenn Ihr fertig seid.", tgo={{"Ogermagier der Feuermägen"}, {"Oger der Feuermägen"}, {"Schläger der Feuermägen"}}},
    [3824] = {n="Gor'tesh der Schläger-Lord", d="Sucht Gor'tesh irgendwo im Westen des Schreckensfelsens. Tötet Gor'tesh und bringt dann seinen abgehackten Kopf zu Oralius in der brennenden Steppe zurück.", tgo={{"Gor'tesh", "Grubbub"}}},
    [3825] = {n="Ogerkopf auf einem Pfahl = Party", d="Nehmt Gor'teshs abgehackten Kopf und platziert ihn auf dem Gipfel des Schreckensfelsens. Sucht nach einem weichen Erdhügel, um den Pfahl aufzustellen.", objs={"Weicher Erdhaufen"}},
    [3844] = {n="Es ist für jeden ein Geheimnis", d="Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte."},
    [3845] = {n="Es ist für jeden ein Geheimnis", d="Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer."},
    [3881] = {n="Rettungsexpedition", d="Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marshal im Un'Goro Krater.", objs={"Kiste mit Lebensmitteln", "Forscherausrüstung"}},
    [3882] = {n="Knochenklappern", d="Bringt 8 Dinosaurierknochen zu Spark Nilminer im Un'Goro Krater.", tgo={{"Stegodon", "Plattenpanzerstegodon", "Stachelstegodon", "Donnerstampferstegodon", "Junger Dimetrodon", "Dimetrodon", "Alter Dimetrodon"}}},
    [3883] = {n="Eine fremdartige Ökologie", d="Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Un'Goro Krater zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut.\nBringt die Schwarmbauwandprobe zu Hol'anyee Marshal im Un'Goro Krater.", objs={"Gorishi Hive Hatchery"}},
    [3884] = {n="Willidens Tagebuch", d="Bringt das Tagebuch zu Williden Marshal zurück. Er befindet sich irgendwo im Un'Goro Krater."},
    [3903] = {n="Milly Osworth", d="Sprecht mit Milly Osworth."},
    [3904] = {n="Millys Ernte", d="Bringt 8 Kisten mit Millys Ernte zu Milly Osworth in der Nähe der Abtei von Nordhain.", objs={"Millys Ernte"}},
    [3905] = {n="Traubenliste", d="Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain."},
    [3908] = {n="Es ist für jeden ein Geheimnis", d="Bringt Linkens Schwert zu Donova Snowden in Winterspring."},
    [3909] = {n="Das Videre-Elixier", d="Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück.", tgo={{"Gregan Brewspewer"}}},
    [3912] = {n="Treffen am Grab", d="Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden."},
    [3913] = {n="Grabesstille", d="Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat."},
    [3914] = {n="Linkens Schwert", d="Liefert Linkens überragendes Schwert bei Linken im Un'Goro Krater ab."},
    [3941] = {n="Die Hilfe des Gnoms", d="Sucht J.D. Collie in der Höhle in Marshals Zuflucht auf."},
    [3942] = {n="Linkens Andenken", d="Sucht Eridan Bluewind im südlichen Teil des Teufelswalds."},
    [4022] = {n="Eine Kostprobe der Flamme", d="Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Velarok Windblade erhalten habt.", tgo={{"Rasender Schwarzdrache"}}},
    [4024] = {n="Eine Kostprobe der Flamme", d="Begebt Euch in die Blackrocktiefen und tötet Bael'Gar.\nIhr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.\nBringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück.", tgo={{"Bael'Gar"}}},
    [4084] = {n="Silberherz", d="Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Bluewind im Teufelswald.", tgo={{"Wutklauenbär", "Wutklauengrizzly", "Wutklauenraufer", "Teufelspfotenwolf", "Teufelspfotenaasfresser", "Teufelspfotenverheerer", "Todesheuler", "Mongress"}, {"Wanderer der Eisenstämme", "Donnerstampfer der Eisenstämme"}}},
    [4101] = {n="Den Teufelswald säubern", d="Bringt 15 Einheiten Blutharz zu Arathandris Silversky im Teufelswald.", tgo={{"Wucherborkenschinder", "Wucherborkenschredder", "Dessecus"}}},
    [4123] = {n="Das Herz des Berges", d="Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe.", objs={"Herz des Berges"}},
    [4124] = {n="Der vermisste Kurier", d="Sprecht mit Ginro Hearthkindle in der Festung Feathermoon."},
    [4125] = {n="Der vermisste Kurier", d="Sucht das Boot des Kuriers irgendwo entlang der Küste von Feralas."},
    [4126] = {n="Hurley Pestatem", d="Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept.", tgo={{"Hurley Pestatem", "Pestatems Spießgeselle"}}},
    [4127] = {n="Havarie", d="Kehrt zur Festung Feathermoon zurück und zeigt Ginro Hearthkindle das gefundene Messer."},
    [4128] = {n="Ragnar Donnerbräu", d="Sprecht mit Ragnar Donnerbräu."},
    [4129] = {n="Das wieder aufgetauchte Messer", d="Bringt Quintis Jonespyre in der Festung Feathermoon das gefundene Messer."},
    [4130] = {n="Psychometrie-Sitzung", d="Sprecht mit Ginro Hearthkindle in der Festung Feathermoon."},
    [4131] = {n="Die Waldpfotengnolle", d="Durchsucht die Lager der Waldpfotengnolle im Süden Feralas nach Hinweisen auf den Verbleib des Kuriers oder seiner Habseligkeiten."},
    [4135] = {n="Die verwundene Tiefe", d="Da Ihr jetzt Raschals letzten bekannten Aufenthaltsort in Erfahrung gebracht habt, setzt Ihr die Suche nach ihm oder seinen sterblichen Überresten in der verwundenen Tiefe fort. Laut Notiz soll dieser Ort südlich der Lager der Waldpfotengnolle liegen."},
    [4141] = {n="Muigin und Larion", d="Sammelt 15 Blutblüten und kehrt zu Muigin zurück.", tgo={{"Blutblütenpeitscher", "Blutblütenschinder", "Blutblütendrescher", "Blutblütenfalle"}}},
    [4142] = {n="Ein Besuch bei Gregan", d="Bringt Gregan Brewspewer in Feralas eine Blutblüte."},
    [4161] = {n="Rezept der Kaldorei", d="Sammelt 7 kleine Spinnenbeine für Zarrin in Dolanaar.", tgo={{"Waldspinne", "Minenspinne", "Giftzahnbrutmutter", "Klippenlauerer", "Holzlauerer", "Waldlauerer", "Heimtückischer Nachtweber", "Moospirscher"}}},
    [4182] = {n="Drachkin-Bedrohung", d="Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist.", tgo={{"Schwarzer Brutling"}, {"Schwarze Großdrachenbrut"}, {"Schwarzdrache"}, {"Schwarzwyrmkin"}}},
    [4183] = {n="Die wahren Meister", d="Reist nach Seenhain und händigt Magistrat Solomon Helendis Riverhorns Brief aus."},
    [4184] = {n="Die wahren Meister", d="Reist nach Stormwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor.\nBolvar residiert in der Burg Stormwind."},
    [4185] = {n="Die wahren Meister", d="Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon.", tgo={{"Lady Katrana Prestor"}}},
    [4186] = {n="Die wahren Meister", d="Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus."},
    [4223] = {n="Die wahren Meister", d="Sprecht mit Marshal Maxwell in der brennenden Steppe."},
    [4224] = {n="Die wahren Meister", d="Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt.\nIhr erinnert Euch daran, dass Marshal Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen.", tgo={{"Struppiger John"}}},
    [4241] = {n="Marshal Windsor", d="Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist.\nIhr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt."},
    [4242] = {n="Verlorene Hoffnung", d="Überbringt Marshal Maxwell die schlechten Neuigkeiten."},
    [4243] = {n="Chasing A-Me 01", d="Sucht im Un'Goro Krater nach A-Me 01."},
    [4244] = {n="Chasing A-Me 01", d="Sucht ein Mithrilgehäuse und bringt es zu A-Me 01 im Un'Goro Krater.", tgo={{"Clunk", "Schreddereinheit der Frostwolf", "Schreddereinheit der Stormpike", "7:XT"}}},
    [4245] = {n="Chasing A-Me 01", d="Begleitet A-Me 01 zu Karna Remtravel im Un'Goro Krater."},
    [4265] = {n="Flucht aus dem Schwarmbau", d="Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus.\nKehrt zu Ginro Hearthkindle in der Festung Feathermoon zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht."},
    [4266] = {n="Der Empfang eines Helden", d="Sprecht mit Shandris Feathermoon in der Festung Feathermoon."},
    [4267] = {n="Aufstieg der Silithid", d="Bringt Raschals Bericht zu Gracina Spiritmight in Darnassus."},
    [4283] = {n="FÜNFZIG! Jawoll!", d="Oralius will 50 Medaillons der Blackrock haben. Die Chancen stehen gut, dass man die Medaillons bei den Orcs in der brennenden Steppe findet.", tgo={{"Soldat der Blackrock", "Zauberhexer der Blackrock", "Töter der Blackrock", "Hexenmeister der Blackrock", "Kampfmeister der Blackrock", "Worg der Blackrock", "Glutworg", "Sabbernder Glutworg"}}},
    [4284] = {n="Machtkristalle", d="Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün. Bringt sie zu J. D. Collie in Marshals Zuflucht.", objs={"Roter Machtkristall", "Gelber Machtkristall", "Grüner Machtkristall", "Blauer Machtkristall"}},
    [4285] = {n="Der Nordpylon", d="Findet den Standort des nördlichen Kristallpylonen im Un'Goro Krater.", objs={"Nördlicher Kristallpylon"}},
    [4286] = {n="Feine Sachen", d="Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen.", tgo={{"Vorarbeiter der Zorneshämmer", "Aufseher der Zorneshämmer", "Gardist der Zorneshämmer", "Fußsoldat der Zorneshämmer", "Soldat der Zorneshämmer", "Sanitäter der Zorneshämmer", "Offizier der Zorneshämmer", "Arbeiter der Schattenschmiede"}}},
    [4287] = {n="Der Ostpylon", d="Findet den Standort des östlichen Kristallpylonen im Un'Goro Krater.", objs={"Östlicher Kristallpylon"}},
    [4288] = {n="Der Westpylon", d="Findet den Standort des westlichen Kristallpylonen.", objs={"Westlicher Kristallpylon"}},
    [4289] = {n="Die Affen von Un'Goro", d="Bringt Torwa Pathfinder am Eingang zum Un'Goro Krater 2 Un'Goro-Gorillapelze, 2 Un'Goro-Stampferpelze und 2 Un'Goro-Donnererpelze.", tgo={{"Un'Goro-Gorilla", "Un'Goro-Gorilla"}, {"Un'Goro-Stampfer"}, {"Un'Goro-Donnerer"}}},
    [4290] = {n="Lar'korwis Mahl", d="Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pathfinder im Un'Goro Krater zurück.", objs={"Frisches Dreschadongerippe"}},
    [4291] = {n="Lar'korwis Fährte", d="Bringt Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater 2 Ravasaurus-Pheromondrüsen.", tgo={{"Lar'korwi-Weibchen"}}},
    [4292] = {n="Ein Köder für Lar'korwi", d="Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater.", tgo={{"Lar'korwi"}}},
    [4296] = {n="Schrifttafel der Sieben", d="Bringt Maxwort Uberglint in der brennenden Steppe die Abschrift der Schrifttafel.", objs={"Schrifttafel der Sieben"}},
    [4301] = {n="Der mächtige U'cha", d="Bringt U'chas Pelz zu Torwa Pathfinder am Eingang des Un'Goro Kraters.", tgo={{"U'cha"}}},
    [4321] = {n="Die Sache verstehen", d="Sprecht demnächst mit J. D. Collie."},
    [4341] = {n="Kharan Mighthammer", d="Begebt Euch in die Blackrocktiefen und findet Kharan Mighthammer.\nDer König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten."},
    [4342] = {n="Kharans Geschichte", d="Lasst Kharan Mighthammer seine Geschichte erzählen.", tgo={{"Kharan Mighthammer"}}},
    [4421] = {n="Die Verderbnis der Jadefeuer", d="Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Bluewind im Teufelswald zurück, sobald die Aufgabe erledigt ist.", tgo={{"Jadefeuerteufelsanbeter"}, {"Jadefeuerschattenpirscher"}, {"Jadefeuerschurke"}, {"Xavathras"}}},
    [4441] = {n="Gebundene Urtume", d="Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück.", objs={"Brunnen des Tempels des Mondes"}},
    [4442] = {n="Geläutert!", d="Sprecht Eridan gleich noch einmal an."},
    [4449] = {n="Eingesperrt!", d="Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff.", tgo={{"Geologe der Dunkeleisenzwerge"}, {}}, objs={"Alteracgranit", "Ramponierte Truhe", "Robuste Truhe"}},
    [4450] = {n="Geschäftsbuch aus Tanaris", d="Nehmt die Abschrift von Goodsteels Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goodsteel in Tanaris aufsucht.", tgo={{}, {"Glasnetzspinne"}, {}, {"Jarquia"}}, objs={"Goodsteel-Geschäftsbuch", "Beschädigte Kiste"}},
    [4486] = {n="Der Foliant des Adels", d="Sprecht mit Duthorian Rall in Stormwind."},
    [4487] = {n="Teufelsross beschwören", d="Sprecht mit Strahad Farsan in Ratchet."},
    [4490] = {n="Teufelsross beschwören", d="Sprecht in Ratchet mit Strahad Farsan, um zu lernen, wie man ein Teufelsross beschwört."},
    [4491] = {n="Etwas Hilfe von guten Freunden", d="Führt Ringo zu Spraggle Frock in Marshals Zuflucht.\nFalls Ringo ohnmächtig werden sollte, verwendet Spraggles Feldflasche, um ihn zu beleben."},
    [4492] = {n="Verloren!", d="Sucht Ringo am Feuerfedergrat."},
    [4493] = {n="Der Marsch der Silithiden", d="Sprecht in Gadgetzan mit Alchimist Pestlezugg."},
    [4495] = {n="Ein guter Freund", d="Sucht Iverron an der Höhle im Norden."},
    [4496] = {n="Dschungelei", d="Bringt eine Gorishiduftdrüse und 5 Un'Goro-Erdproben zu Alchimist Pestlezugg in Gadgetzan.", tgo={{"Wespe der Gorishi", "Arbeiter der Gorishi", "Häscher der Gorishi", "Stecher der Gorishi", "Tunnelgräber der Gorishi", "Schwarmwache der Gorishi", "Schwarmkönigin der Gorishi"}, {}}, objs={"Un'Goro-Erdhaufen"}},
    [4501] = {n="Vorsicht, Pterrordax!", d="Tötet 10 Pterrordax und 15 rasende Pterrordax und sprecht dann mit Spraggle Frock in Marshals Zuflucht.", tgo={{"Pterrordax"}, {"Rasender Pterrordax"}}},
    [4502] = {n="Vulkanische Aktivität", d="Sammelt 9 Proben Un'Goro-Asche von den Feuerelementare am Vulkan im Un'Goro Krater ein und bringt die Proben zu Liv Rizzlefix in Ratchet.", tgo={{"Versengender Elementar", "Lebendiges Feuer", "Sturmflamme", "Lodernder Eindringling", "Baron Glutarr"}}},
    [4503] = {n="Shizzles Flieger", d="Sammelt 8 eingesponnene Dimetrodon-Schuppen und 8 eingesponnene Pterrordax-Schuppen für Shizzle in Marshals Zuflucht.", tgo={{"Junger Dimetrodon", "Dimetrodon", "Alter Dimetrodon"}, {"Pterrordaxjunges", "Pterrordax", "Rasender Pterrordax"}}},
    [4504] = {n="Superkleber", d="Sammelt 12 Proben superklebrigen Teer für Tran'rek in Gadgetzan.", tgo={{"Teerbestie", "Teerlauerer", "Teerfürst", "Teerkriecher"}}},
    [4581] = {n="Kayneth Stillwind", d="Bringt Shindrells Notiz zu Kayneth Stillwind in Forest Song."},
    [4681] = {n="An Land gespült", d="Bergt die Meeresschildkrötenüberreste der skelettierten Meeresschildkröte in den Gewässern westlich von Auberdine und sprecht anschließend in Auberdine mit Gwennyth Bly'Leggonde.", objs={"Skelettierte Meeresschildkröte"}},
    [4701] = {n="Stellt sie ab", d="Begebt Euch zur Blackrockspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs.", tgo={{"Halycon"}}},
    [4722] = {n="Gestrandete Meeresschildkröte", d="Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4723] = {n="Gestrandete Meereskreatur", d="Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4725] = {n="Gestrandete Meeresschildkröte", d="Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4726] = {n="Brutlingessenz", d="Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe.", objs={"Brutlingessenz"}},
    [4727] = {n="Gestrandete Meeresschildkröte", d="Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4728] = {n="Gestrandete Meereskreatur", d="Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4729] = {n="Kiblers Exotische Tiere", d="Begebt Euch zur Blackrockspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler."},
    [4730] = {n="Gestrandete Meereskreatur", d="Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4731] = {n="Gestrandete Meeresschildkröte", d="Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4732] = {n="Gestrandete Meeresschildkröte", d="Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4733] = {n="Gestrandete Meereskreatur", d="Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4734] = {n="Ei-Frosten", d="Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst.", objs={"Krähenhorstei"}},
    [4735] = {n="Eiersammlung", d="Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe.", objs={"Krähenhorstei"}},
    [4740] = {n="GESUCHT: Gurgelbacke!", d="Sucht und tötet den Murloc namens Gurgelbacke. Man nimmt an, dass die Kreatur die Hütten der Murlocs am Strand südlich von Auberdine beschützt.\nInformiert Schildwache Glynda Nal'Shea über Gurgelbackes Tod.", tgo={{"Gurgelbacke"}}},
    [4742] = {n="Siegel des Aufstiegs", d="Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.\nVaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten.", tgo={{"Hochlord Omokk"}, {"Kriegsmeister Voone"}, {"Oberanführer Wyrmthalak"}, {"Grunzer der Schmetterschilde", "Wachposten der Schmetterschilde", "Akolyt der Schmetterschilde", "Rüstmeister der Schmetterschilde", "Legionär der Schmetterschilde", "Zauberbinder der Schmetterschilde", "Hochlord Omokk", "Kampfmagier der Felsspitzoger"}}},
    [4743] = {n="Siegel des Aufstiegs", d="Reist zum Drachensumpf in den Marschen von Dustwallow. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist.\nIn genau diesem Moment müsst Ihr das ungeschmiedete Siegel des Aufstiegs vor der großen Bestie hinlegen. Dann müsst Ihr schnell die Kugel der drachischen Energie auf seine geschwächte Gestalt anwenden und die Kontrolle über seine geistigen Kräfte übernehmen. Kontrolliert die Bestie und zwingt die Flammen des schwarzen Drachenschwarms auf das ungeschmiedete Siegel des Aufstiegs!", objs={"Geschmiedetes Siegel des Aufstiegs"}},
    [4761] = {n="Thundris Windwirker", d="Sprecht mit Thundris Windwirker in Auberdine."},
    [4762] = {n="Der Cliffspring", d="Geht von Auberdine aus nach Norden zum ersten Wasserfall des Cliffspring und entnehmt aus dem Teich dort eine Probe.\nKehrt mit der Cliffspringprobe zu Thundris Windwirker nach Auberdine zurück.", objs={"Cliffspring River Waterfall"}},
    [4763] = {n="Die verderbten Schwarzfelle", d="Füllt die leere Säuberungsschale am Mondbrunnen in Auberdine.\nHolt jeweils eine Probe von Früchten, Nüssen und Getreide aus dem Lager der Schwarzfellfurbolgs im Norden.\nMischt alles in der Schale und stellt diese bei dem Freudenfeuer neben dem Cliffspring auf Höhe des nördlichen Lagers ab und lockt dadurch den Satyrverderber an.\nNehmt den Talisman der Verderbnis und bringt ihn zu Thundris Windwirker in Auberdine.", objs={"Xabraxxis Dämonentasche"}},
    [4764] = {n="Doomriggers Schnalle", d="Bringt Mayara Brightwing in der brennenden Steppe Doomriggers Schnalle.", objs={"Doomriggers Kasten"}},
    [4765] = {n="Lieferung an Ridgewell", d="Bringt Ridgewells Kiste zu Remington Ridgewell nach Stormwind."},
    [4771] = {n="Dämmerungstrickfalle", d="Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Bigglezink zurück.", tgo={{"Vectus"}}},
    [4781] = {n="Komponenten für die verzauberte Goldblutrobe", d="Bringt Xizk Goodstitch im Schlingendorntal einen Goldbarren.", objs={"Ramponierte Truhe", "Robuste Truhe", "Geldkassette der Allianz"}},
    [4782] = {n="Komponenten für die verzauberte Goldblutrobe", d="Kehrt zu Menara Voidrender im Brachland zurück."},
    [4783] = {n="Komponenten für die verzauberte Goldblutrobe", d="Bringt Menara Voidrender im Brachland 10 Phiolen Zornsäerblut und 1 geringen Höllenstein.", tgo={{"Schurke der Zornsäer", "Schwindler der Zornsäer", "Teufelsanbeter der Zornsäer", "Verräter der Zornsäer", "Schattenpirscher der Zornsäer", "Höllenrufer der Zornsäer", "Prinz Kellen"}, {"Geringe Höllenbestie", "Dämonenportalwächter"}}},
    [4784] = {n="Komponenten für die verzauberte Goldblutrobe", d="Bringt Menara Voidrender im Brachland Goldgarn, 2 glimmende Kohlen und einen Seelensplitter.", tgo={{"Xizk Goodstitch"}, {"Brennender Verbannter"}, {}}},
    [4785] = {n="Feiner Goldfaden"},
    [4786] = {n="Die fertig gestellte Robe", d="Wartet, bis Menara Voidrender Eure Robe fertig gestellt hat, und sprecht dann noch einmal mit ihr.", tgo={{"Menara Voidrender"}}},
    [4787] = {n="Das uralte Ei", d="Bringt das uralte Ei zu Yeh'kinya nach Tanaris.", objs={"Uraltes Ei"}},
    [4788] = {n="Die letzten Schrifttafeln", d="Bringt Ausgrabungsleiter Ironboot in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru.", objs={"Fünfte Mosh'aru-Schrifttafel", "Sechste Mosh'aru-Schrifttafel"}},
    [4808] = {n="Felnok Steelspring", d="Gebt Felnok Steelspring Tinkees Brief."},
    [4809] = {n="Hörner der Eiswindschimären", d="Bringt Felnok Steelspring 8 unbeschädigte Hörner einer Eiswindschimäre.", tgo={{"Eiswindjunges", "Eiswindschimäre", "Eiswindverheerer"}}},
    [4810] = {n="Rückkehr zu Tinkee", d="Bringt Tinkee Steamboil in der brennenden Steppe Felnoks Päckchen."},
    [4811] = {n="Der rote Kristall", d="Reist von Auberdine nach Osten und sucht nach einem großen, roten Kristall entlang der östlichen Bergkette von Dunkelküste. Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.", objs={"Geheimnisvoller roter Kristall"}},
    [4812] = {n="Wenn das Wasser fließt", d="Füllt die leere Wasserröhre am Mondbrunnen von Auberdine und untersucht dann den roten Kristall an der östlichen Bergkette von Dunkelküste.", objs={"Auberdine Mondbrunnen"}},
    [4813] = {n="Die Fragmente im Inneren", d="Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse."},
    [4842] = {n="Sonderbare Quellen", d="Befolgt Donova Snowdens Anweisungen und meldet Euch dann wieder bei ihr."},
    [4861] = {n="Wütende Wildekin", d="Findet Jaron Stoneshapers ruiniertes Lager samt dessen Vorräte im südlichen Winterspring."},
    [4862] = {n="Be-Öh-Es-Eh", d="Reist zur Blackrockspitze und sammelt 15 Spitzenspinnen-Eier für Kibler.\nLogischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden.", objs={"Spitzenspinnen-Ei"}},
    [4863] = {n="Wütende Wildekin", d="Sucht Jaron Stoneshapers zerstörten Wagen."},
    [4864] = {n="Wütende Wildekin", d="Klaubt Jarons Vorräte aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte.\nBringt Jaron Stoneshaper in der Lodge in Winterspring dessen Vorräte und das blaugefiederte Amulett.", tgo={{}, {"Wahnsinnige Eulenbestie", "Mondbestrahlte Eulenbestie", "Berserkereulenbestie", "Wächter von Elune"}}, objs={"Jarons Laden"}},
    [4866] = {n="Muttermilch", d="Ihr findet Mutter Glimmernetz im Herzen der Blackrockspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann.", tgo={{"Struppiger John"}}},
    [4867] = {n="Urok Schreckensbote", d="Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh.", tgo={{"Urok Schreckensbote"}}},
    [4901] = {n="Wächter des Altars", d="Schützt Ranshalla, während sie versucht, den Altar von Elune wieder zu aktivieren. Berichtet Erelas Ambersky in Rut'theran von Eurem Fund."},
    [4902] = {n="Wildekin von Elune", d="Sprecht mit Erzdruide Fandral Staghelm in Darnassus."},
    [4906] = {n="Weitere Verderbnis", d="Eridan Bluewind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt.", tgo={{"Jadefeuerhöllenrufer"}, {"Jadefeuerverräter"}, {"Jadefeuerschwindler"}, {"Xavaric"}}},
    [4961] = {n="Die Säuberung der Kugel von Orahil", d="Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", tgo={{"Dämon der Kugel"}}},
    [4962] = {n="Splitter eines Teufelshundes", d="Nehmt den Felhas-Rubin und benutzt ihn bei einem der Teufelshunde von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Teufelshundgeist und den Felhas-Rubin.", tgo={{"Manafresser"}}},
    [4963] = {n="Splitter einer Höllenbestie", d="Nehmt den Infus-Smaragd und benutzt ihn bei einer der Höllenbestien von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Höllenbestiengeist und den Infus-Smaragd.", tgo={{"Geringe Höllenbestie"}}},
    [4964] = {n="Die fertig gestellte Kugel von Dar'Orahil", d="Wartet, bis Menara Voidrender die Kugel von Dar'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", tgo={{"Menara Voidrender"}}},
    [4965] = {n="Wissen der Kugel von Orahil", d="Sprecht mit Menara Voidrender im Brachland."},
    [4971] = {n="Eine Frage der Zeit", d="Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren.\nTötet 15 temporale Parasiten und bringt dann den Temporalversetzer zu Chromie im Gasthaus Andorhal in den Westlichen Pestländern.", tgo={{"Temporaler Parasit"}}},
    [4972] = {n="Tempus fugit", d="Sucht 5 Andorhal-Uhren, die in Schließkassetten überall im Schutt der Stadt zu finden sind. Kehrt mit ihnen zu Chromie ins Gasthaus Andorhal in den Westlichen Pestländern zurück.", objs={"Kleine Schließkassette"}},
    [4975] = {n="Die fertig gestellte Kugel von Noh'Orahil", d="Wartet, bis Menara Voidrender die Kugel von Noh'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", tgo={{"Menara Voidrender"}}},
    [4976] = {n="Ablieferung der gesäuberten Kugel", d="Bringt die gesäuberte Höllenkugel zu Menara Voidrender ins Brachland."},
    [4984] = {n="Die Tierwelt leidet auch", d="Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.", tgo={{"Kranker Wolf"}}},
    [4985] = {n="Die Tierwelt leidet auch", d="Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.", tgo={{"Kranker Grizzly"}}},
    [4986] = {n="Glyphenverzierter Eichenast", d="Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Darnassus bringt. Bittet einen der Druiden dort um Hilfe."},
    [5001] = {n="Bijous Habseligkeiten", d="Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!", objs={"Bijous Habseligkeiten"}},
    [5002] = {n="Nachricht an Maxwell", d="Begebt Euch in die brennende Steppe und leitet Bijous Informationen an Marshal Maxwell weiter."},
    [5021] = {n="Besser spät als nie", d="Das wilde Gebrabbel der Geisterfrau deutete darauf hin, dass sie ein Paket ausliefern musste. Sie behauptete, dass es dort war, wo auch ihr Pferd war. Darüber, wo das Pferd jetzt ist oder wohin das Paket ausgeliefert werden muss, sagt der Geist nichts."},
    [5022] = {n="Besser spät als nie", d="Wendet Euch an die königlichen Disponenten von Stormwind, um etwas über den Aufenthaltsort von Emma Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter im Rathaus."},
    [5047] = {n="Pip Quickwit, zu Euren Diensten!", d="Sprecht mit Malyfous Darkhammer in Everlook."},
    [5048] = {n="Emma die Nette", d="Sucht die alte Emma in Stormwind und findet heraus, ob sie tatsächlich Emma Felstone ist. Wenn sie es ist, dann möchte sie vielleicht das Paket haben, das Janice Felstone für sie gepackt hat."},
    [5058] = {n="Mrs. Dalsons Tagebuch"},
    [5059] = {n="Weggeschlossen", d="Beute von: Wanderndes Skelett", tgo={{"Wanderndes Skelett"}}},
    [5060] = {n="Weggeschlossen", d="Beute von: Bauer Dalson", tgo={{"Bauer Dalson"}}},
    [5061] = {n="Wassergestalt", d="Kehrt nach Darnassus zurück und zeigt Mathrengyl Bearwalker den Anhänger des Seelöwen."},
    [5066] = {n="Der Ruf zu den Waffen: Die Pestländer!", d="Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges."},
    [5081] = {n="Maxwells Mission", d="Reist zur Blackrockspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.", tgo={{"Kriegsmeister Voone"}, {"Hochlord Omokk"}, {"Oberanführer Wyrmthalak"}}},
    [5082] = {n="Bedrohung durch die Winterfelle", d="Donova Snowden in Winterspring möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt.", tgo={{"Pfadfinder der Winterfelle"}, {"Höhlenbehüter der Winterfelle"}, {"Totemiker der Winterfelle"}}},
    [5083] = {n="Feuerwasser der Winterfelle", d="Bringt das leere Feuerwasserfläschchen zu Donova Snowden in Winterspring."},
    [5084] = {n="Der Verderbnis erliegen", d="Durchsucht das Furbolglager der Totenwaldfelle im nördlichen Teil des Teufelswalds nach einem Hinweis."},
    [5085] = {n="Geheimnisvoller Glibber", d="Berichtet Donova Snowden von Euren Entdeckungen."},
    [5089] = {n="General Drakkisaths Befehl", d="Bringt den Befehl von General Drakkisath zu Marshal Maxwell in der brennenden Steppe."},
    [5092] = {n="Den Weg räumen", d="Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Sorrow Hill.\nKehrt zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück.", tgo={{"Skelettschinder"}, {"Sabbernder Ghul"}}},
    [5097] = {n="Turm um Turm", d="Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.\nWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück.", tgo={{"Turm 1 von Andorhal"}, {"Turm 2 von Andorhal"}, {"Turm 3 von Andorhal"}, {"Turm 4 von Andorhal"}}},
    [5102] = {n="General Drakkisaths Niedergang", d="Begebt Euch zur Blackrockspitze und schaltet General Drakkisath aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.", tgo={{"General Drakkisath"}}},
    [5126] = {n="Lorax' Geschichte", d="Sprecht mit Lorax. Hört, was er zu sagen hat.", tgo={{"Lorax"}}},
    [5127] = {n="Die Dämonenschmiede", d="Begebt Euch zur Blackrockspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein.\nIhr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden.\nBringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterspring.", tgo={{"Goraluk Hammerbruch"}, {}}, objs={"Ungeschmiedete runenverzierte Brustplatte"}},
    [5149] = {n="Pamelas Puppe", d="Sucht Pamelas Puppe."},
    [5152] = {n="Tante Marlene", d="Sprecht mit Marlene, südlich der Ruinen von Andorhal."},
    [5153] = {n="Ein seltsamer Historiker", d="Bringt Josephs Ehering zu Chromie.", objs={"Joseph Redpaths Monument"}},
    [5154] = {n="Die Annalen von Darrowshire", d="Bringt die 'Annalen von Darrowshire' zu Chromie in Andorhal.", objs={"Modriger Foliant"}},
    [5155] = {n="Streitmacht von Jaedenar", d="Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.", tgo={{"Hund von Jaedenar"}, {"Wächter von Jaedenar"}, {"Adept von Jaedenar"}, {"Kultist von Jaedenar"}}},
    [5156] = {n="Die Verderbnis überprüfen", d="Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr das Shatter Scar-Tal erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Fel-Wasser gefüllt sind, kehrt zu Taronn Redfeather im Teufelswald zurück.", tgo={{"Entropische Bestie"}, {"Entropischer Schrecken"}}},
    [5157] = {n="Verderbtes Wasser sammeln", d="Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.", objs={"der verderbte Mondbrunnen von Jaedenar"}},
    [5158] = {n="Spirituelle Hilfe suchen", d="Bringt das verderbte Mondbrunnenwasser in das Brachland zu Islen Waterseer."},
    [5159] = {n="Gesäubertes Wasser wird zum Teufelswald gebracht", d="Bringt das geläuterte Mondbrunnenwasser zu Greta Mosshoof im Teufelswald."},
    [5160] = {n="Die oberste Beschützerin", d="Begebt Euch nach Winterspring und sucht Haleh. Gebt ihr Awbees Schuppe."},
    [5168] = {n="Helden von Darrowshire", d="Bringt Davils Buchband und Redpaths Schild zu Carlin Redpath.", objs={"Davils Buchband", "Redpaths Schild"}},
    [5181] = {n="Bösewichte von Darrowshire", d="Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Redpath in der Kapelle des hoffnungsvollen Lichts.", objs={"Horgus' Schädel", "Zertrümmertes Schwert von Marduk"}},
    [5210] = {n="Bruder Carlin", d="Bringt die erweiterten 'Annalen von Darrowshire' zu Carlin Redpath in den Östlichen Pestländern."},
    [5211] = {n="Verteidiger von Darrowshire", d="Befreit 15 Geister von Darrowshire und kehrt dann zu Carlin Redpath zurück.", tgo={{"Geist von Darrowshire"}}},
    [5212] = {n="Das Fleisch lügt nicht", d="Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt.", tgo={{"Verheerter Kadaver", "Geschundener Kadaver", "Seuchenghul", "Tobsüchtiger Ghul", "Fleischschinderghul", "Gruftkriecher", "Gruftbestie", "Flickwerkschrecken"}}},
    [5213] = {n="Der aktive Wirkstoff", d="Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück.", objs={"Geißeldaten"}},
    [5214] = {n="Der große Ezra Grimm", d="Sucht Ezra Grimms Raucherladen in Stratholme und bergt einen Kasten von Grimms Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist.", tgo={{"Ezra Grimm"}}},
    [5215] = {n="Die Geißelkessel", d="Sprecht mit der Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."},
    [5216] = {n="Ziel: Teufelssteinfeld", d="Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Gallenschlund"}}},
    [5217] = {n="Rückkehr zum Chillwind-Lager", d="Bringt die gefüllte Flasche: Teufelssteinfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."},
    [5219] = {n="Ziel: Dalsons Tränenfeld", d="Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Malvinius"}}},
    [5220] = {n="Rückkehr zum Chillwind-Lager", d="Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."},
    [5222] = {n="Ziel: Das trostlose Feld", d="Begebt Euch zum trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Razarch"}}},
    [5223] = {n="Rückkehr zum Chillwind-Lager", d="Bringt die gefüllte Flasche: Das trostlose Feld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."},
    [5225] = {n="Ziel: Gahrrons Trauerfeld", d="Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Rachseele"}}},
    [5226] = {n="Rückkehr zum Chillwind-Lager", d="Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."},
    [5237] = {n="Mission erfüllt!"},
    [5241] = {n="Onkel Carlin", d="Sucht Carlin Redpath."},
    [5243] = {n="Häuser der Heiligen", d="Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Heiliges Wasser von Stratholme. Kehrt zu Leonid Barthalomew dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt.", objs={"Vorratskiste", "Vorratskiste von Stratholme"}},
    [5244] = {n="Die Ruinen von Kel'Theril", d="Sprecht mit Jaron Stoneshaper in Starfall."},
    [5245] = {n="Die gequälten Seelen von Kel'Theril", d="Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Skycaller in den Östlichen Pestländern.", objs={"Fragment eines Hochgeborenenrelikts"}},
    [5250] = {n="Starfall", d="Sucht Starfall in Winterspring und sprecht mit Wynd Nightchaser."},
    [5251] = {n="Der Archivar", d="Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv.", tgo={{"Archivar Galford"}, {}}, objs={"Scharlachrotes Archiv"}},
    [5261] = {n="Eagan Peltskinner", d="Sprecht mit Eagan Peltskinner."},
    [5262] = {n="Die Wahrheit zeigt sich mit Macht", d="Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern."},
    [5263] = {n="Übertroffen", d="Zieht nach Stratholme und vernichtet Baron Rivendare. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück.", tgo={{"Baron Rivendare"}}},
    [5282] = {n="Die ruhelosen Seelen", d="Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei!\nBefreit 15 ruhelose Seelen und kehrt zu Egan zurück.", tgo={{"Ruhelose Seele"}}},
    [5306] = {n="Schlangenstein der Schattenjägerin", d="Begebt Euch zur Blackrockspitze und erschlagt Schattenjägerin Vosh'gajin. Holt Vosh'gajins Schlangenstein und kehrt zu Kilram zurück.", tgo={{"Schattenjägerin Vosh'gajin"}}},
    [5343] = {n="Das Familienvermögen der Barovs", d="Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist.", objs={"Die Besitzurkunde für Brill", "Die Besitzurkunde für Caer Darrow", "Die Besitzurkunde für Southshore", "Die Besitzurkunde für Tarrens Mühle"}},
    [5382] = {n="Doktor Theolen Krastinov, der Schlächter", d="Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt.", tgo={{"Doktor Theolen Krastinov"}, {}, {}}, objs={"Überreste von Eva Sarkhoff", "Überreste von Lucien Sarkhoff"}},
    [5384] = {n="Kirtonos der Herold", d="Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren.\nKämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück.", tgo={{"Kirtonos der Herold"}}},
    [5401] = {n="Anstecknadel der Argentumdämmerung"},
    [5466] = {n="Der Lich Ras Frostraunen", d="Sucht Ras Frostraunen in der Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduke.", tgo={{"Ras Frostraunen"}}},
    [5501] = {n="Knochensammler", d="Bringt Bibbly F'utzbuckle bei Kormeks Hütte 10 Kodoknochen vom Kodofriedhof.", objs={"Kodoknochen"}},
    [5505] = {n="Der Schlüssel zur Scholomance"},
    [5515] = {n="Krastinovs Tasche der Schrecken", d="Sucht nach Jandice Barov in der Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff.", tgo={{"Jandice Barov"}}},
    [5518] = {n="Der Ogeranzug der Gordok", d="Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Thimblejack. Momentan ist er im Gordokflügel von Düsterbruch angekettet.", objs={"Felsteel Chest", "Gerbekorb der Oger", "Knot Thimblejacks Behälter"}},
    [5522] = {n="Leonid Barthalomew", d="Bringt die gefrorenen Eier zu Leonid Barthalomew in den Östlichen Pestländern."},
    [5525] = {n="Befreit Knot!", d="Beute von: Schläger der Gordok, Magierlord der Gordok, Captain der Gordok", tgo={{"Schläger der Gordok", "Magierlord der Gordok", "Captain der Gordok", "Hexenmeister der Gordok", "Häscher der Gordok", "Wache Fengus", "Wache Slip'kik", "Captain Kromcrush"}}},
    [5526] = {n="Die Splitter der Teufelsranke", d="Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach, werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Requiliar der Reinheit, um darin den Splitter sicher zu versiegeln und bringt das versiegelte Reliquiar zu Rabine Saturna in Nighthaven, Moonglade."},
    [5527] = {n="Ein Reliquiar der Reinheit", d="Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nighthaven, Moonglade zurück.", objs={"Staubiger Reliquienschrein"}},
    [5528] = {n="Der Gordokgeschmackstest"},
    [5529] = {n="Verseuchte Jungtiere", d="Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts zurück.", tgo={{"Verseuchtes Jungtier"}}},
    [5531] = {n="Betina Bigglezink", d="Bringt die gefrorenen Eier zu Betina Bigglezink."},
    [5533] = {n="Scholomance", d="Sprecht mit Alchimist Arbington an der Chillwindspitze, Westliche Pestländer."},
    [5535] = {n="Spirituelle Unruhe", d="Vernichtet 6 Erscheinungen einer Hochgeborenen und 6 Lichlinge eines Hochgeborenen, bevor Ihr zu Loh'atu in Azshara zurückkehrt.", tgo={{"Erscheinung einer Hochgeborenen"}, {"Lichling eines Hochgeborenen"}}},
    [5536] = {n="Ein Land voller Hass", d="Tötet 6 Satyrn der Haldarr, 2 Schwindler der Haldarr sowie 2 Teufelsanbeter der Haldarr und kehrt dann zu Loh'atu an der Grenze zu Ashenvale zurück.", tgo={{"Satyr der Haldarr"}, {"Schwindler der Haldarr"}, {"Teufelsanbeter der Haldarr"}}},
    [5537] = {n="Skelettfragmente", d="Bringt 15 Skelettfragmente zu Alchimist Arbington an der Chillwindspitze, Westliche Pestländer.", tgo={{"Skelettschinder", "Skelettzauberhexer", "Skelettschrecker", "Skeletthenker", "Skelettkriegsherr", "Skelettakolyth", "Skeletal Magelord"}}},
    [5538] = {n="Sold reimt sich auf...", d="Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goodsteel in Gadgetzan."},
    [5541] = {n="Munition für Rumbleshot", d="Bringt Rumbleshots Munition zu Hegnar Rumbleshot in Dun Morogh.", objs={"Munitionskiste"}},
    [5542] = {n="Dämonenhunde", d="Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt.", tgo={{"Kleiner Seuchenhund"}, {"Seuchenhund"}, {"Rasender Seuchenhund"}}},
    [5543] = {n="Blutgefärbter Himmel", d="Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück.", tgo={{"Seuchenfledermaus"}}},
    [5544] = {n="Aassammlung", d="Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt.", tgo={{"Aaslarve", "Aasverschlinger"}}},
    [5545] = {n="Ein Bündel Probleme", d="Bringt 8 Holzbündel zu Raelen beim Holzfällerlager des Osttals.", objs={"Kleinholzbündel"}},
    [5561] = {n="Kodozusammentrieb", d="Bringt fünf gezähmte Kodos sowie den Kodokombobulator zu Smeed Scrabblescrew bei Scrabblescrews Lager."},
    [5582] = {n="Gesunde Großdrachenschuppe", d="Bringt die gesunde Großdrachenschuppe zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern."},
    [5601] = {n="Schwester Pamela", d="Sucht Pamela Redpath in Darrowshire."},
    [5621] = {n="Gewänder des Mondes", d="Sucht die Schildwache Shaya und heilt ihre Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Laurna Morninglight in Dolanaar zurück.", tgo={{"Schildwache Shaya"}}},
    [5622] = {n="Elune geneigt", d="Sprecht mit Laurna Morninglight in Teldrassil."},
    [5623] = {n="Dem Licht geneigt", d="Sprecht mit der Priesterin Josetta im Wald von Elwynn."},
    [5624] = {n="Gewänder des Lichts", d="Sucht die Wache Roberts und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Priesterin Josetta in Goldhain zurück.", tgo={{"Wache Roberts"}}},
    [5625] = {n="Gewänder des Lichts", d="Sucht den Gebirgsjäger Dolf und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Maxan Anvol in Kharanos zurück.", tgo={{"Gebirgsjäger Dolf"}}},
    [5626] = {n="Dem Licht geneigt", d="Sprecht mit Maxan Anvol in Dun Morogh."},
    [5627] = {n="Sterne von Elune"},
    [5629] = {n="Heimkehr", d="Sprecht mit der Priesterin Alathea in Darnassus."},
    [5634] = {n="Verzweifeltes Gebet", d="Sprecht mit Hohepriester Rohan in Ironforge."},
    [5645] = {n="Züchtigung", d="Sprecht mit Hohepriester Rohan in Ironforge."},
    [5672] = {n="Elunes Anmut"},
    [5676] = {n="Arkane Rückkopplung"},
    [5713] = {n="Ein Schuss, ein Treffer", d="Schützt die Schildwache Aynasha und sprecht dann mit Onaeya bei Maestras Posten in Ashenvale."},
    [5741] = {n="Szepter des Lichts", d="Besorgt das Szepter des Lichts und bringt es zurück zu Azore Aldamort am Turm in Ethel Rethor.", tgo={{"Seher der Burning Blade"}}},
    [5742] = {n="Erlösung", d="Hört Euch an, was Tirion Fordring zu sagen hat.", tgo={{"Tirion Fordring"}}},
    [5762] = {n="Hemet Nesingwary", d="Bringt Kravels Kiste zu Hemet Nesingwary ins Schlingendorntal."},
    [5781] = {n="Von vergessenen Erinnerungen", d="Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", tgo={{"Mercutio Dreckschipper"}}},
    [5801] = {n="Feuerfeder geschmiedet", d="Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.\nBringt den unvollendeten Skelettschlüssel dann zum Alchimisten Arbington an der Chillwindspitze in den Westlichen Pestländern.", objs={"Feuerfedergrat-Lavasee"}},
    [5803] = {n="Arajs Skarabäus", d="Zerstört Araj den Beschwörer und bringt Arajs Skarabäus zum Alchimisten Arbington an der Chillwindspitze in den westlichen Pestländern.", objs={"Arajs Phylakterium"}},
    [5845] = {n="Von verlorener Ehre", d="Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", objs={"Symbol der verlorenen Ehre"}},
    [5846] = {n="Von Liebe und Familie", d="Begebt Euch zur Insel Caer Darrow im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte."},
    [5848] = {n="Von Liebe und Familie", d="Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der Scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.\nBringt das Gemälde zu Tirion Fordring.", objs={"Unvollendetes Gemälde"}},
    [5863] = {n="Das Truppenlager der Dünenbrecher", d="Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet.", tgo={{"Schläger der Dünenbrecher"}, {"Vollstrecker der Dünenbrecher"}, {"Gor'marok der Verheerer"}}},
    [5882] = {n="Salbe durch Jagd", d="Beute von: Verfluchter Brühschlammer, Besudelter Brühschlammer, Übler Brühschlammer", tgo={{"Verfluchter Brühschlammer", "Besudelter Brühschlammer", "Übler Brühschlammer", "Eisenschnabeleule", "Eisenschnabelkreischer", "Eisenschnabeljäger", "Wucherborkenschinder", "Wucherborkenschredder"}}},
    [5903] = {n="Eine Plage komme über Euch", d="Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestland-Termiten gesammelt habt, kehrt zu Nathaniel Dumah am Chillwindposten in den Westlichen Pestländern zurück.", objs={"Großer Termitenhügel"}},
    [5904] = {n="Eine Plage komme über Euch", d="Sucht Euch einen geeigneten Ort in der Mitte des Northridge-Sägewerks in den Westlichen Pestländern, um das Fass mit den Pestland-Termiten abzustellen."},
    [5921] = {n="Moonglade", d="Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven."},
    [5929] = {n="Großer Bärengeist", d="Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.", tgo={{"Großer Bärengeist"}}},
    [5931] = {n="Zurück nach Darnassus", d="Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius."},
    [6001] = {n="Körper und Herz", d="Benutzt den Mondstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\nSprecht mit Mathrengyl Bearwalker in Darnassus, wenn Ihr fertig seid.", tgo={{"Geist von Mondklaue"}}},
    [6004] = {n="Offene Rechnungen", d="Tötet 2 scharlachrote Sanitäter, 2 scharlachrote Jäger, 2 scharlachrote Magi und 2 scharlachrote Ritter, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.", tgo={{"Scharlachrote Sanitäterin"}, {"Scharlachroter Jäger"}, {"Scharlachrote Magierin"}, {"Scharlachroter Ritter"}}},
    [6021] = {n="Zaeldarr der Ausgestoßene", d="Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des hoffnungsvollen Lichts.", tgo={{"Zaeldarr der Ausgestoßene"}}},
    [6023] = {n="Offene Rechnungen", d="Besiegt Jägerin Radley und Chevalier Durgen, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.", tgo={{"Jägerin Radley"}, {"Chevalier Durgen"}}},
    [6024] = {n="Hameyas Bitte", d="Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe.", tgo={{"Spitzel Hameya"}}},
    [6025] = {n="Offene Rechnungen", d="Geht nach Hearthglen, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Deepshadow in den Westlichen Pestländern zurück."},
    [6028] = {n="Der Everlook-Bericht", d="Bringt den Everlook-Bericht zu Argentumoffizier Pureheart im Chillwind-Lager in den westlichen Pestländern."},
    [6030] = {n="Fürst Nicholas Zverenhoff", d="Bringt das Buch 'Studien zur Geistersuche' zu Fürst Nicholas Zverenhoff in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern."},
    [6063] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen Waldweberlauerer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", tgo={{"Waldweberlauerer"}}},
    [6064] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen großen Klippeneber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.", tgo={{"Großer Klippeneber"}}},
    [6084] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen Schneeleoparden zu zähmen. Übt Eure Fertigkeiten und kehrt dann zu Grif Wildheart in Kharanos zurück.", tgo={{"Schneeleopard"}}},
    [6085] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen Eisklauenbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.", tgo={{"Eisklauenbär"}}},
    [6086] = {n="Die Ausbildung des Tiers", d="Sprecht mit Belia Thundergranite in Ironforge."},
    [6101] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", tgo={{"Pirschender Nachtsäbler"}}},
    [6102] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", tgo={{"Strigidkreischer"}}},
    [6103] = {n="Die Ausbildung des Tiers", d="Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus."},
    [6121] = {n="Neue Lektionen", d="Reist nach Moonglade und sprecht mit Dendrite Starblaze im Dorf Nighthaven."},
    [6122] = {n="Die eigentliche Ursache", d="Benutzt das leere Gefäß bei Cliffspring Falls und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen.\nBringt das gefüllte Gefäß von Cliffspring Falls zu Alanndarian Nightsong nach Auberdine in Dunkelküste.", objs={"Cliffspring Falls Cave Mouth"}},
    [6123] = {n="Das Heilmittel sammeln", d="Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nightsong in Auberdine, damit sie eine Heilsalbe machen kann.", tgo={{"Wildschlagsetzling", "Zornranke"}, {}}, objs={"Lunarfungusblüte"}},
    [6124] = {n="Heilung der Kranken", d="Benutzt die Tier-Heilsalbe bei 10 kranken Wildtieren rund um Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass krankes Wild südlich des Cliffspring, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo Ashenvale beginnt, aufgetaucht ist.", tgo={{"Kränkliches Reh"}}},
    [6125] = {n="Macht über Gift", d="Kehrt zu Mathrengyl Bearwalker in der Enklave des Cenarius in Darnassus zurück."},
    [6134] = {n="Geisterplasmasuche", d="Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brimbuzzle in Desolace.", tgo={{"Zentaurengeist"}}},
    [6182] = {n="Der Erste und Letzte", d="Sprecht mit Meister Mathias Shaw in der Altstadt von Stormwind. Er wohnt in der Kaserne."},
    [6183] = {n="Ehret die Toten", d="Sprecht wieder mit Mathias Shaw, wenn Ihr seine Aufgabe annehmen wollt."},
    [6184] = {n="Flint Shadowmore", d="Reist zur Chillwindspitze in den Westlichen Pestländern und trefft Euren Kontaktmann Flint Shadowmore."},
    [6185] = {n="Die östlichen Pestländer", d="Sucht in den östlichen Pestländern nach Hinweisen auf den 'Blightcaller' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Shadowmore an der Chillwindspitze.", objs={"Zerfleischte menschliche Überreste"}},
    [6341] = {n="Die Arten von Teldrassil", d="Bringt Nessas Sammlung zu Vesprystus."},
    [6342] = {n="Flug nach Auberdine", d="Bucht bei Hippogryphenmeister Vesprystus einen Hippogryphen nach Auberdine und bringt dann Nessas Sammlung zu Laird."},
    [6343] = {n="Rückkehr zu Nessa", d="Bringt Lairds Antwort zu Nessa Shadowsong."},
    [6344] = {n="Nessa Shadowsong", d="Sprecht mit Nessa Shadowsong."},
    [6387] = {n="Ehrenstudenten", d="Bringt Brocks Liste zu Thorgrum Borrelson in Thelsamar."},
    [6388] = {n="Gryth Thurden", d="Bringt die Ehrenhacken zu Gryth Thurden in Ironforge."},
    [6389] = {n="Eine Plage komme über Euch", d="Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Nathaniel Dumah im Chillwind-Posten in den westlichen Pestländern zurück."},
    [6391] = {n="Flug nach Ironforge", d="Bucht einen Greifen nach Ironforge von Greifenmeister Thorgrum Borrelson, dann bringt Brocks Liste zu Golnir Bouldertoe in Ironforge."},
    [6392] = {n="Rückkehr zu Brock", d="Bucht einen Greifen nach Thelsamar bei Greifenmeister Gryth Thurden, dann bringt die Ehrenhacken zu Brock Stoneseeker in Thelsamar."},
    [6502] = {n="Drachenfeueramulett", d="Ihr müsst das Blut des schwarzen Großdrachen-Helden von General Drakkisath bekommen.\nIhr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Blackrockspitze.", tgo={{"General Drakkisath"}}},
    [6603] = {n="Probleme in Winterspring", d="Findet Donova Snowden bei den Thermalquellen in Winterspring."},
    [6604] = {n="Wütende Wildekin", d="Sprecht mit Jaron Stoneshaper in Starfall."},
    [6606] = {n="Ein bisschen Glück", d="Sprecht in Everlook mit Hexendoktorin Mau'ari."},
    [6626] = {n="Ein Hort des Bösen", d="Tötet 8 Schlachtwachen von Razorfen, 8 Dornenwirker von Razorfen und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Moonsinger nahe dem Eingang zu den Hügeln von Razorfen zurück.", tgo={{"Schlachtwache von Razorfen"}, {"Dornenwirker von Razorfen"}, {"Kultistin der Totenköpfe"}}},
    [6681] = {n="Das Anwesen, Ravenholdt", d="Bringt das Ravenholdt-Siegel zu Fahrad im Ravenholdt-Anwesen, das versteckt in den Hügeln von Hillsbrad liegt.\nUnterwegs wird man Eure Schlauheit testen. Seid darauf gefasst.", tgo={{"Ravenholdt"}}},
    [6701] = {n="Syndikatsembleme", d="Beute von: Auftragsmörder des Syndikats, Herbeizauberer des Syndikats, Schleicher des Syndikats", tgo={{"Auftragsmörder des Syndikats", "Herbeizauberer des Syndikats", "Schleicher des Syndikats", "Straßenräuber des Syndikats", "Söldner des Syndikats", "Pfadpirscher des Syndikats", "Streuner des Syndikats", "Spion des Syndikats"}}},
    [7028] = {n="Dunkles Böses", d="Sammelt 25 theradrische Kristallschnitzereien für Willow in Desolace.", tgo={{"Verfluchter Zentaur", "Satyr der Putridus", "Schwindler der Putridus", "Schattenpirscher der Putridus", "Dryade von Celebrian", "Schwester von Celebrian", "Prinzessin Theradras", "Erdrutsch"}}},
    [7041] = {n="Schlangenzunges Verderbnis", d="Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird.\nHeilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Talendria an der Nijelspitze zurück.", tgo={{"Noxxious-Spross"}, {}}, objs={"Maraudon orangefarbenen Kristallteich"}},
    [7044] = {n="Legenden von Maraudon", d="Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten.\nFindet einen Weg, um mit Celebras zu sprechen.", tgo={{"Lord Schlangenzunge"}, {"Noxxion", "Noxxions Brut"}}},
    [7046] = {n="Das Szepter von Celebras", d="Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt.\nSprecht mit ihm, nachdem das Ritual vollendet ist.", objs={"Incantation of Celebras"}},
    [7065] = {n="Verderbnis von Erde und Samenkorn", d="Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück.", tgo={{"Prinzessin Theradras"}}},
    [7066] = {n="Samenkorn des Lebens", d="Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens."},
    [7067] = {n="Die Anweisungen des Pariahs", d="Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace."},
    [7070] = {n="Schattensplitter", d="Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Marschen von Dustwallow.", tgo={{"Schattensteinrumpler", "Schattensteinzerkracher", "Schattensteindonnerer"}}},
    [7383] = {n="Krone der Erde", d="Füllt die Amethystphiole und bringt sie Corithras Moonrage in Dolanaar.", objs={"Lichtung des Orakels'-Mondbrunnen"}},
    [7441] = {n="Pusillin und der Älteste Azj'Tordin", d="Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben.\nKehrt mit dem Buch zu Az'Tordin, an Lariss' Pavillon in Feralas, zurück.", tgo={{"Pusillin"}}},
    [7461] = {n="Der innere Wahnsinn", d="Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.\nBetretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.\nKehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück.", tgo={{"Immol'thar"}, {"Prinz Tortheldrin"}}},
    [7462] = {n="Der Schatz der Shen'dralar", d="Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!"},
    [7463] = {n="Arcane Erfrischung", d="Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz, zum Hüter des Wissens Lydros im Athenaeum zurück.", tgo={{"Hydrobrut"}}},
    [7482] = {n="Elfische Legenden", d="Sucht in Düsterbruch nach Telmius Dreamseeker. Meldet Euch anschließend bei der Gelehrten Runethorn in Feathermoon.", objs={"Die sterblichen Überreste von Telmius Dreamseeker"}},
    [7483] = {n="Buchband der Schnelligkeit", d="Bringt ein Buchband der Schnelligkeit, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 2 mal das Blut von Helden, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum der Schnelligkeit zu erhalten.", tgo={{"Schläger der Gordok", "Magierlord der Gordok", "Captain der Gordok", "Hexenmeister der Gordok", "Häscher der Gordok", "Satyr der Wildhufe", "Schurke der Wildhufe", "Schwindler der Wildhufe"}, {"Skelettkriegsherr", "Fleischgolem", "Scharlachroter Magus", "Scharlachroter Chevalier", "Großknecht Jerris", "Hochbeschützer Lorik", "Araj der Beschwörer", "Verfluchter Justiziar"}, {}, {}}, objs={"Blut von Helden"}},
    [7484] = {n="Buchband des Fokus", d="Bringt ein Buchband des Fokus, 1 makellosen schwarzen Diamanten, 4 große glänzende Splitter und 2 mal Schattenhaut, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Fokus zu erhalten.", tgo={{"Schläger der Gordok", "Magierlord der Gordok", "Captain der Gordok", "Hexenmeister der Gordok", "Häscher der Gordok", "Satyr der Wildhufe", "Schurke der Wildhufe", "Schwindler der Wildhufe"}, {"Skelettkriegsherr", "Fleischgolem", "Scharlachroter Magus", "Scharlachroter Chevalier", "Großknecht Jerris", "Hochbeschützer Lorik", "Araj der Beschwörer", "Verfluchter Justiziar"}, {}, {"Auferstandenes Konstrukt", "Auferstandener Knochenwärter", "Lady Illucia Barov", "Instrukteurin Malicia", "Der Ravenier", "Hüter des Wissens Polkelt"}}},
    [7485] = {n="Buchband des Schutzes", d="Bringt ein Buchband des Schutzes, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 1 ausgefranste Monstrositätenstickerei zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Schutzes zu erhalten.", tgo={{"Schläger der Gordok", "Magierlord der Gordok", "Captain der Gordok", "Hexenmeister der Gordok", "Häscher der Gordok", "Versteinerter Treant", "Beschützer von Eisenborke", "Schnauber der Eldreth"}, {"Skelettkriegsherr", "Fleischgolem", "Scharlachroter Magus", "Scharlachroter Chevalier", "Großknecht Jerris", "Hochbeschützer Lorik", "Araj der Beschwörer", "Verfluchter Justiziar"}, {}, {"Flickwerkschrecken", "Gallspucker", "Giftrülpser", "Ramstein der Verschlinger"}}},
    [7488] = {n="Lethtendris' Netz", d="Bringt Lethtendris' Netz zu Latronicus Moonspear in der Festung Feathermoon, in Feralas.", tgo={{"Lethtendris"}}},
    [7498] = {n="Garona: Eine Studie über Heimlichkeit und Verrat", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7499] = {n="Kodex der Verteidigung", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7500] = {n="Das Arkanistenkochbuch", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7501] = {n="Vom Licht und wie man es schwingt", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7502] = {n="Schatten einspannen", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7503] = {n="Das größte Volk von Jägern", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7504] = {n="Heiliger Fleischklops: Was das Licht Dir nicht erzählt", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7505] = {n="Frostschock und Du", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7506] = {n="Der Smaragdgrüne Traum", d="Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
    [7507] = {n="Nostros Kompendium", d="Bringt Nostros Kompendium des Drachentötens zurück in das Athenaeum."},
    [7601] = {n="Nibys Anweisungen", d="Sprecht mit Impsy im Teufelswald."},
    [7602] = {n="Reine Teufelsessenz", d="Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt.\nDie Satyrn der Legashi von Azshara bergen die Teufelsessenz ihrer Region. Die Legionäre von Jaedenar in Jaedenar bergen die Teufelsessenz ihrer Region. Die Wachposten der Teufelswache in den verwüsteten Landen bergen die Teufelsessenz ihrer Region.\nFindet die Teufelsessenzen und bringt sie zu Impsy im Teufelswald.", tgo={{"Satyr der Legashi", "Schurke der Legashi", "Höllenrufer der Legashi", "Seelendieb der Legashi", "Aufwiegler der Legashi", "Schwarzwache der Legashi"}, {"Legionär von Jaedenar"}, {"Wachposten der Teufelswache"}}},
    [7603] = {n="Kroshius Höllenbestienkern", d="Sucht im Shattered Scar-Tal im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern.\nBringt Kroshius' Höllenbestienkern zu Niby dem Allmächtigen im Teufelswald.", tgo={{"Kroshius"}, {"Kroshius"}}},
    [7701] = {n="GESUCHT: Vorarbeiter Maltorius", d="Tief in der Schlackengrube des Kessels in der sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden.\nTötet den Aufseher Maltorius und nehmt seinen Kopf an Euch. Bringt diesen zum Ausguck Captain Lolo Longstriker in der sengenden Schlucht für eine Belohnung.", tgo={{"Aufseher Maltorius"}}},
    [7703] = {n="Die offene Rechnung der Gordok", d="Findet die Stulpen der Gordokmacht und bringt sie zu Captain Kromcrush in Düsterbruch.\nKromcrush zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat.", objs={"Die Truhe des Prinzen"}},
    [7722] = {n="Was zum Fluxus?!", d="Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der sengenden Schlucht.", objs={"Geheimpläne: Feuriger Fluxus"}},
    [7723] = {n="Verdammt seien diese fetten Finger", d="Hansel Heavyhands möchte, dass Ihr 20 Schwere Kriegsgolems tötet.\nDie Schweren Kriegsgolems wandern in der Gegend um den Kessel in der sengenden Schlucht herum. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.", tgo={{"Schwerer Kriegsgolem"}}},
    [7724] = {n="Feurige Bedrohung!", d="Hansel Heavyhands möchte, dass Ihr 20 sengende Lavaspinnen in der sengenden Schlucht tötet.\nDie sengenden Lavaspinnen findet Ihr auf den Plateaus und in den Lavabecken der sengenden Schlucht. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.", tgo={{"Versengende Lavaspinne"}}},
    [7727] = {n="Incendosaurier? Was-auch-immer-Saurier?", d="Hansel Heavyhands möchte, dass Ihr 20 Incendosaurier tötet.\nDie Incendosaurier haben sich in den Lavabecken der Schlackengrube eingenistet. Ihr findet die Schlackengrube im Kessel der segenden Schlucht.\nSobald Ihr genug Incendosaurier getötet habt, kehrt zu Hansel Heavyhands in der sengenden Schlucht zurück.", tgo={{"Incendosaurier"}}},
    [7728] = {n="GESTOHLEN: Schmiedewindform und ein Ausguck-Handfernrohr", d="Sucht die Schmiedewindform und das Ausguck-Handfernrohr. Bringt diese Gegenstände zu Zuchtmeister Scrange in der sengenden Schlucht.\nDie einzigen Informationen die Ihr habt sind: Die Schmiedewindform is ein SCHMIEDEwerkzeug welches von SCHMIEDEN verwendet wird und das Ausguck-Handfernrohr ist ein unverzichtbares Werkzeug für SPÄHPOSTEN.", tgo={{"Dampfschmied der Dunkeleisenzwerge"}, {"Ausguck der Dunkeleisenzwerge"}}},
    [7729] = {n="STELLE ZU VERGEBEN: Erledige die Konkurrenz", d="Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Scrange zurück, sobald Ihr die Aufgabe erfüllt habt.", tgo={{"Zuchtmeister der Dunkeleisenzwerge"}, {"Sklavenhändler der Dunkeleisenzwerge"}}},
    [7733] = {n="Beste Qualität", d="Bringt Pratt McGrubben in der Festung Feathermoon 10 Wutschrammyetibälge.", tgo={{"Wutschrammyeti", "Alter Wutschrammyeti", "Wilder Wutschrammyeti", "Lauernder Wildschrammyeti"}}},
    [7735] = {n="Makelloser Yetibalg", d="Bringt Pratt McGrubben in der Festung Feathermoon den makellosen Yetibalg."},
    [7791] = {n="Spendet Wolle", d="Benutzen/Sammeln: Alteracgranit, Ramponierte Truhe, Ramponierte Truhe", objs={"Alteracgranit", "Ramponierte Truhe", "Ramponierte Truhe"}},
    [7793] = {n="Spendet Seide", d="Benutzen/Sammeln: Alteracgranit, Ramponierte Truhe, Robuste Truhe", objs={"Alteracgranit", "Ramponierte Truhe", "Robuste Truhe"}},
    [8151] = {n="Der Talisman des Jägers", d="Sprecht mit Ogtinc in Azshara."},
    [8153] = {n="Gehörnte Renner", d="Bringt ein perfektes Rennergeweih zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath.", tgo={{"Mooshufrenner"}}},
    [8231] = {n="Wellenjagd", d="Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", tgo={{"Junger Wellenhauer", "Wellenhauer", "Großer Wellenhauer"}}},
    [8232] = {n="Der grüne Drache", d="Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", tgo={{"Morphaz"}}},
    [8250] = {n="Geschick der Magier", d="Sucht nach Sanath Lim-yo und verschafft Euch Zugang zu Erzmagier Xylem."},
    [8251] = {n="Magischer Staub", d="Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben.", tgo={{"Blutelfenfeldmesser", "Blutelfenwiederbeschafferin", "Blutelfenverteidiger", "Blutelfenarkanist", "Evin Schmidt", "Lumina Windsinger"}}},
    [8252] = {n="Die Koralle der Sirenen", d="Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem.", tgo={{"Sirene der Grollflossen"}}},
    [8253] = {n="Vernichtet Morphaz", d="Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück.", tgo={{"Morphaz"}}},
    [8254] = {n="Cenarische Hilfe", d="Sucht Ogtinc in Azshara auf."},
    [8255] = {n="Renner für einen höheren Zweck", d="Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", tgo={{"Mooshufrenner"}}},
    [8256] = {n="Sekret des Untodes", d="Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", tgo={{"Zombie von Zanzil", "Jäger von Zanzil", "Skelettschinder", "Skelettzauberhexer", "Skelettschrecker", "Skeletthenker", "Skelettkriegsherr", "Skelettakolyth"}}},
    [8257] = {n="Morphaz' Blut", d="Tötet Morphaz im versunkenen Tempel von Atal'Hakkar und bringt Greta Mosshoof im Teufelswald sein Blut. Der Eingang zum versunkenen Tempel liegt in den Sümpfen des Elends.", tgo={{"Morphaz"}}},
    [8365] = {n="Piratenhüte Ahoy!", d="Sammelt 20 Südmeerpiratenhüte und bringt sie zurück zur eingebildeten Modeschöpferin nach Steamwheedle in Tanaris.", tgo={{"Pirat der Südmeerfreibeuter", "Seeräuber der Südmeerfreibeuter", "Dockarbeiter der Südmeerfreibeuter", "Schwadroneur der Südmeerfreibeuter", "Andre Feuerbart", "Kregg Kielhol"}}},
    [8366] = {n="Gaunerei und Erpressung im Südmeer", d="Sicherheitschef Bilgewhizzle aus Steamwheedle in Tanaris beauftragt Euch, 10 Piraten der Südmeerfreibeuter, 10 Seeräuber der Südmeerfreibeuter, 10 Dockarbeiter der Südmeerfreibeuter und 10 Schwadroneure der Südseefreibeuter zu töten.", tgo={{"Pirat der Südmeerfreibeuter"}, {"Seeräuber der Südmeerfreibeuter"}, {"Dockarbeiter der Südmeerfreibeuter"}, {"Schwadroneur der Südmeerfreibeuter"}}},
    [8414] = {n="Austreibung des Bösen", d="Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den westlichen Pestländern.", tgo={{"Skelettschinder", "Skelettzauberhexer", "Skelettschrecker", "Skeletthenker", "Skelettakolyth", "Sabbernder Ghul", "Faulender Ghul", "Seelenloser Ghul"}}},
    [8415] = {n="Chillwindspitze", d="Sprecht mit Kommandanten Ashlam Valorfist an der Chillwindspitze."},
    [8416] = {n="Gereinigte Geißelsteine", d="Bringt den gereinigten Geißelstein zu Kommandant Ashlan Valorfist an der Chillwindspitze."},
    [8417] = {n="Ein geplagter Geist", d="Sprecht mit dem gefallenen Helden der Horde am Eingang zu den verwüsteten Landen."},
    [8418] = {n="Erschaffung des Steins der Macht", d="Bringt die Voodoofedern zu Ashlam Valorfist.", tgo={{"Schlitzer", "Zul'Lor"}, {"Hukku", "Mijan"}, {"Zolo", "Loro"}}},
    [8420] = {n="Heiß und brennend", d="Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald.", tgo={{"Teufelsjäger", "Wachposten der Teufelswache", "Satyr der Legashi", "Schurke der Legashi", "Höllenrufer der Legashi", "Meister Gräuelbart", "Jadefeuerschurke", "Jadefeuerschwindler"}}},
    [8421] = {n="Das richtige Zeug", d="Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald.", tgo={{"Wanderer der Eisenstämme", "Donnerstampfer der Eisenstämme", "Siechender Beschützer"}, {"Besudelter Brühschlammer"}}},
    [8422] = {n="Federn von Trollen", d="Bringt 6 Voodoofedern von den Trollen aus dem versunkenen Tempel.", tgo={{"Schlitzer", "Zul'Lor", "Schlitzer"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loro", "Loro"}}},
    [8423] = {n="Kriegerverwandtschaft", d="Tötet 7 Hölleneber in den verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück.", tgo={{"Hölleneber"}}},
    [8424] = {n="Krieg den Schattenanbetern", d="Merzt die Schattenanbeter in den verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück.", tgo={{"Adept der Schattenanbeter"}, {"Kultist der Schattenanbeter"}, {"Rohling der Schattenanbeter"}}},
    [8425] = {n="Voodoofedern", d="Bringt die Voodoofedern der Trolle im versunkenen Tempel zu dem gefallenen Helden der Horde.", tgo={{"Schlitzer", "Zul'Lor", "Schlitzer"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loro", "Loro"}}},
    [8460] = {n="Verbündeter der Holzschlundfeste", d="Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt.", tgo={{"Krieger der Totenwaldfelle"}, {"Pfadfinder der Totenwaldfelle"}, {"Gärtner der Totenwaldfelle"}}},
    [8461] = {n="Totenwaldfelle des Nordens", d="Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück.", tgo={{"Höhlenbehüter der Totenwaldfelle"}, {"Rächer der Totenwaldfelle"}, {"Schamane der Totenwaldfelle"}}},
    [8462] = {n="Sprecht mit Nafien", d="Reist nach Norden entlang der Hauptstraße des Teufelswalds und sprecht mit einem Furbolg names Nafien. Er hält außerhalb des Eingangs zur Holzschlundfeste Wache."},
    [8464] = {n="Aktivität der Winterfelle", d="Salfa möchte, dass Ihr 8 Schamanen der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Ursa der Winterfelle erledigt. Salfa befindet sich direkt außerhalb des Eingangs zur Holzschlundfeste in Winterspring.", tgo={{"Schamane der Winterfelle"}, {"Höhlenbehüter der Winterfelle"}, {"Ursa der Winterfelle"}}},
    [8465] = {n="Sprecht mit Salfa", d="Durchquert die Holzschlundfeste und verlasst sie in Richtung Winterspring. Sprecht mit Salfa, die außerhalb des Eingangs zur Holzschlundfeste Wache steht."},
    [9051] = {n="Giftexperiment", d="Stecht einen Teufelssaurier mit dem Teufelssaurierhaken."},
    [9052] = {n="Blutblütengift", d="Sammelt Blutkappenpilze und Gorishistachel und kehrt zu Torwa Pathfinder im Un'Goro Krater zurück.", tgo={{"Wespe der Gorishi", "Stecher der Gorishi"}, {}}, objs={"Blutblütensprössling"}},
    [9053] = {n="Eine bessere Zutat", d="Beschafft Euch eine Fäulnisranke von dem Wächter auf dem Grund des versunkenen Tempels und kehrt zu Torwa Pathfinder zurück.", tgo={{"Atal'alarion"}}},
    [65602] = {n="Alles aus Liebe", d="Beschafft die Holzstatuette und bringt sie zu Gakin dem Dunkelbinder im Magierviertel von Stormwind.", objs={"Holzstatuette"}},
    [65603] = {n="Die Bindung", d="Beschwört mit Hilfe der Holzstatuette einen Inkubus, unterwerft ihn und bringt dann die Holzstatuette zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück.", tgo={{"Beschworener Inkubus"}}},
    [79358] = {n="Sturm, Erde und Feuer", d="Sammelt 5 verdrehte Feuertotems, 5 verdrehte Erdtotems, 5 verdrehte Lufttotems und 5 verdrehte Wassertotems für Veyric Thunderhame im Arathihochland.", tgo={{"Pfützenspringer der Schlammflossen", "Murloc der Schlammflossen", "Krieger der Schlammflossen", "Matschkrabbler der Schlammflossen", "Küstenläufer der Schlammflossen", "Orakel der Schlammflossen"}, {"Matschlauerer der Verirrten", "Angler der Verirrten", "Jäger der Verirrten", "Matschkrabbler der Verirrten", "Seher der Verirrten", "Risssucher der Verirrten", "Häuptling der Verirrten", "Koch der Verirrten"}, {"Schädelhauer der Steingrufttroggs", "Knochenknacker der Steingrufttroggs", "Schamane der Steingrufttroggs", "Oger der Staubspeier", "Schläger der Staubspeier", "Wyrmjäger der Staubspeier", "Raufer der Staubspeier", "Schamane der Staubspeier"}, {"Zänker der Maraudine", "Raufer der Maraudine", "Windhetzer der Maraudine", "Sturmruferin der Maraudine", "Marodeur der Maraudine", "Maraudine Pack Runner", "Späher der Maraudine"}}},
    [86574] = {n="Versorgungsgüter fürs Steinkrallengebirge", d="Sammelt 6 Vorratskisten des Steinkrallengebirges von Prachtschwingenwyvern und bringt sie zu Gastwirtin Faralia.", tgo={{"Junge Prachtschwinge", "Prachtschwingenflügeldrache", "Prachtschwingenhimmelsjäger", "Prachtschwingenkonsort", "Prachtschwingenpatriarch", "Freewind Post Wyvern"}}},
    [86585] = {n="Banner der Gefallenen", d="Erhebt das Banner von Ironforge, lockt den Trogg Kopfspalter hervor und tötet ihn. Meldet Euch anschließend bei Captain Rugelfuss.", tgo={{"Kopfspalter"}}},
    [86758] = {n="Ist dies ein Dolch", d="Findet und besiegt den Krokilisken Dolchzahn und holt Mareks Messer zurück.", tgo={{"Dolchzahn"}}},
    [87288] = {n="Weiche Säblerpelze", d="Bringt Aldria 6 weiche Nachtsäblerpelze.", tgo={{"Nachtsäbler"}}},
    [87494] = {n="Mikrokristallkontamination", d="Bringt die kristalldurchdrungene Schuppe zu Torwa Pathfinder.", tgo={{"Ravasaurus", "Ravasaurusläufer", "Ravasaurusjäger", "Gifthautravasaurus", "Junger Dimetrodon", "Dimetrodon", "Alter Dimetrodon", "Pterrordaxjunges"}}},
    [87760] = {n="Auf heiliger Tauchmission", d="Findet eine Tierbändigerin der Sturmschuppen, tötet sie und nehmt ihre Rute der Tiefenherrschaft an Euch.", tgo={{"Tierbändigerin der Sturmschuppen"}}},
    [90487] = {n="Uralte Verbündete", d="Reist von der Höhle des Einsiedlers nach Westen, um einen Außenposten von Ahnen und Dryaden an den unteren Hängen des Hyjal zu finden."},
    [90647] = {n="Der Stab des Berges", d="Bringt den Stab des Berges zu Tiala Weißsträhne auf dem Gipfel der Ewigkeit."},
    [90702] = {n="Gestörte Ruhe", d="Durchsucht die Umgebung nach den fehlenden Grabinhalten.", tgo={{"Fleischschinderräuber", "Fleshflayer Ravener"}}},
    [90750] = {n="Noch mehr Arbeit?", d="Sprecht mit dem Bauern und lasst ihn wissen, dass seine Arbeit erledigt ist."},
    [90865] = {n="Die Augen der Beobachter", d="Holt 8 Augen des Beobachters für Eluneth.", tgo={{"Ewiger Wachposten"}}},
    [91688] = {n="Zum Gipfel der Ewigkeit", d="Reist zum Gipfel der Ewigkeit und sprecht mit den Druiden über das Dorf der Überlebenden."},
    [91696] = {n="Jagdsaison", d="Eskortiert die Matriarchin der Baumrindenfurbolgs aus dem Bau der Totenwaldfelle und kehrt zum Bau der Baumrindenfurbolgs zurück."},
    [91697] = {n="Audienz bei den Ältesten", d="Findet und sprecht mit der Ältesten Mistpaw und dem Ältesten Pinespeaker innerhalb des Baus der Baumrindenfurbolgs."},
    [91698] = {n="Baumrindenbefreiung", d="Beschafft einen Schlüssel der Totenwaldfelle von einem Wächter der Totenwaldfelle und kehrt zum Käfig des Baumrindenfurbolgs zurück.", tgo={{"Wächter der Totenwaldfelle"}}},
    [91723] = {n="Empfindliche Instrumente", d="Tötet 8 Koboldgeomanten in der Jaspismine und kehrt anschließend zu Hamish Bergwort im Turm von Azora zurück.", tgo={{"Koboldgeomant"}}},
    [91732] = {n="Guter Stahl", d="Sammelt 4 Bergbauwerkzeuge in der Jaspismine und kehrt damit zu Hagar Lowe im Holzfällerlager des Osttals zurück.", objs={"Bergbauwerkzeuge"}},
    [91733] = {n="Flussabwärts", d="Sammelt die durchnässte Axt, durchnässte Säge und den durchnässten Werkzeugkasten, die vom Holzfällerlager des Osttals flussabwärts gespült wurden, und kehrt damit zu Ormin Pelford zurück.", objs={"Durchnässte Axt", "Durchnässte Säge", "Durchnässter Werkzeugkasten"}},
    [91740] = {n="Quakis Kopf", d="Bringt Quakis Kopf zu Merell Ross in der Kammwacht."},
    [91741] = {n="Angeknabbertes Buch", d="Bringt das Buch zu Bruder Paxton zurück."},
    [91743] = {n="Nervige Nager", d="Bergt 8 gestohlene Bücher von den Kobolden im Nordhaintal und bringt sie zurück zu Bruder Paxton.", tgo={{"Koboldgezücht", "Koboldhilfsarbeiter", "Koboldtagelöhner"}}},
    [91745] = {n="Bergbauberater", d="Sprecht mit Kelsey Fargo außerhalb der Echokammmine im Nordhaintal."},
    [91752] = {n="Das große Ganze", d="Bergt einen Sack voller \"Bilderbücher\" von Glitzerfinder Narf. Bringt den Sack zu Marshal McBride in der Abtei von Nordhain.", tgo={{"Glitzerfinder Narf"}}},
    [91753] = {n="Verzaubernde Erkenntnisse", d="Kitta Firewind im Turm von Azora möchte, dass Ihr 3 leuchtende Rückstände sammelt.\nLeuchtende Rückstände erhaltet Ihr durch Entzaubern von primitiven Wachsbildnissen, die von Koboldgeomanten fallen gelassen werden."},
    [91754] = {n="Etwas Dreck in die Wunde", d="Sammelt 6 Proben unbefleckter Erde in den Ausläufern des Hyjal."},
    [91755] = {n="Von Blättern zu Verbänden", d="Sammelt 12 tiefgrüne Blätter von besudelten Gebüschen in den Ausläufern des Hyjal.", tgo={{"Besudeltes Gebüsch"}}},
    [91758] = {n="Folgt diesem Kobold!", d="Sprecht mit Tordrin Sternblade in der Nähe des Stalls hinter der Abtei von Nordhain."},
    [91770] = {n="Borkenbiss", d="Wendet den Umschlag bei Fraxinus an.", tgo={{"Fraxinus"}}},
    [91772] = {n="Pssst! Wir jagen Kobolde", d="Folgt den Koboldspuren und meldet Euch bei Marshal Dughan in Goldhain mit Euren Erkenntnissen und dem Kobold-Fährtenleseset.", objs={"Kobold Tracks"}},
    [91775] = {n="Buchrückgabe", d="Findet 6 verlorene Bücher sowie \"Spaß mit Elementaren\" und bringt sie zu Marshal Dughan zurück.", tgo={{"Nimsy"}, {"Koboldminenarbeiter", "Koboldtunnelgräber"}}},
    [91777] = {n="Seltene Bücher", d="Findet \"Geomantie für neugierige kleine Zauberer\" und \"Arkane Erläuterungen: Magisches in einfachen Worten\" und bringt sie zu Bruder Paxton in der Abtei von Nordhain zurück.", tgo={{"Geoformerin Yip", "Koboldgeomant"}, {"Giftzahnbrutmutter", "Koboldgeomant"}}},
    [91881] = {n="Der westliche Posten", d="Trefft Sefira Everbright beim Außenposten."},
    [91883] = {n="Der Speer des Himmelsfürsten", d="Tötet Zarrat Wurmschwinge und bringt Omnurons Speer zurück.", tgo={{"Zarrat Wurmschwinge"}}},
    [91923] = {n="Celastrus der Bittere", d="Findet und vernichtet Celastrus den Bitteren und kehrt dann mit dem zerbrochenen Wedel zu Thylaen zurück.", tgo={{"Celastrus der Bittere"}}},
    [91952] = {n="Die Quelle der Verderbnis", d="Sucht den Einsiedler Ketharas auf dem Hyjal."},
    [92008] = {n="Premiumteile", d="Beschafft Kaylaena Springbolts Teile und kehrt zu Nami in Everlook zurück."},
    [92009] = {n="Knappe Kiste", d="Transportiert die Kiste mit Teilen und Spielereien behutsam zu Kaylaena Springwhisper auf dem Hyjal."},
    [92011] = {n="Schrottgestöber", d="Plündert die Überreste der Hordebasis und bringt 5 Stücke ausgefranster Draht, 5 Stücke Metallschrott und 5 verkalkte Exkremente zu Kaylaena."},
    [92014] = {n="Fuchsbau", d="Bringt 9 Schwänze eines Rostlaubfuchses zu Johun \"Haudrauf\" Dillas in Hyjal.", tgo={{"Rostlaubfuchs"}}},
    [92015] = {n="Gefahrenzone: Stinktier", d="Verscheucht die Stinktiere aus dem Bereich rund um Johuns Ausrüstung, ohne sie zu töten."},
    [92017] = {n="Reinigende Winde", d="Sammelt 5 große Hippogryphenfedern und 3 öliges Schimärenhaar für Marn", tgo={{"Bergsturmsteiger"}, {"Wildatem-Chimaerok"}}},
    [92020] = {n="Hol'anyees großes Buch der großen Echsen", d="Bringt Hol'anyees großes Buch der großen Echsen zu einem Druiden am Gipfel des Hyjal."},
    [92064] = {n="Ein Baum und ein Traum", d="Brecht den Ast, um Fenwick Togglespring zu befreien.", tgo={{"Ast"}}},
    [92065] = {n="De Rückeroberung des Schwarzschlunds", d="Bringt Varrox Bleakhoofs Kopf zu Torhüter Donnerschrei in Ursolan."},
    [92066] = {n="Die Zwillingsbären", d="Findet das Totem von Ursoc und das Totem von Ursol in der Schwarzschlundfeste. Kehrt dann zum Hüter des Wissens Nok in Ursolan zurück."},
    [92069] = {n="Reißende Klauen, durchbohrende Hauer", d="Bringt die Klauen des großen Bären und die Hauer des Ungebrochenen zu Ogtinc in Azshara."},
    [92070] = {n="Ein verlorenes Andenken", d="Findet denjenigen, dem die gefiederte Anhängerhalskette gehört.", tgo={{"Schwärmender Wichtel", "Schlächter der Legashi", "Satyr der Legashi"}}},
    [92100] = {n="Irgendwo, nur nicht hier", d="Findet die Schwertscheide des Veteranen des Dritten Krieges in der Nähe von Holderwild."},
    [92111] = {n="Von Freund und Fell", d="Betretet den Bau der Baumrindenfurbolgs und findet den Furbolg, den sie Osi nennen."},
    [92124] = {n="Bücherliste", d="Sprecht in der Bibliothek mit Daniel, Bruder Paxtons Gehilfe."},
    [92147] = {n="Hochfederhelfer", d="Tötet 18 Wurmschwingenharpyien auf dem Hyjal und bringt ihre Federn zu Phoebe Highfeather.", tgo={{"Harpyie der Wurmschwingen", "Windhexe der Wurmschwingen", "Wegelagerin der Wurmschwingen", "Nestling der Wurmschwingen", "Zarrat Wurmschwinge"}}},
    [92169] = {n="Rache am Pakt", d="Setzt den Stab des Berges gegen 10 Mitglieder des Schwarzdornpakts auf dem Gipfel der Ewigkeit ein, um ihre Schutzzauber zu entfernen und sie anschließend zu töten."},
    [92171] = {n="Auf zu neuen Höhen", d="Reist zum Schrein von Aviana auf Hyjal und bittet den Himmelsfürst Omnuron um Hilfe."},
    [92317] = {n="Gestohlenes Leben", d="Beschafft einen Tropfen gestohlenen Lebens von der Geißel in den Ruinen auf dem Hyjal und kehrt damit zu Ketharas zurück.", tgo={{"Todesheuler", "Fleischschinderräuber", "Vergessener Soldat", "Fleshflayer Ravener"}}},
    [92328] = {n="Belagerungskunst", d="Dreht die Getriebe und verbindet die Batterieanschlüsse an beiden Seiten von Kaylaenas Glevenschleuder."},
    [92329] = {n="Ärger zusammentrommeln", d="Geht zum Kamm südlich von Kaylaenas Werkstatt und findet einen Weg, ein ablenkendes Getöse zu machen, um die Schimäre Ghansurok so nah anzulocken, dass sie angegriffen werden kann."},
    [92335] = {n="Asche des Legionsaufstiegs", d="Holt eine Prise von Azgalors Asche aus den Ruinen von Dae'gun auf dem Hyjal."},
    [92344] = {n="Die Wurzel des Problems", d="Sammelt in der Schwarzschlundfeste 10 Wurzelkappen von Nordrassil für Mathrengyl Bearwalker in Darnassus."},
    [92345] = {n="Unter Nordrassil", d="Sprecht mit Mathrengyl Bearwalker in der Enklave des Cenarius in Darnassus."},
    [92415] = {n="Denk daran, ich liebe dich", d="Bringt den blutbefleckten Brief zu Waisenmatrone Nightingale in Stormwind."},
