    [96606] = {n="Die große weite Welt", d="Setzt Euch an Lyreenas einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", objs={"Basic Campfire"}},
    [96608] = {n="Die große weite Welt", d="Setzt Euch an Erics einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", objs={"Basic Campfire"}},
