    [96833] = {n="Giftige Mäuler", d="Warnt die anderen auf dem Berg vor der aggressiven Schimäre namens Ghansurok."},
    [96930] = {n="Ein verschmitzter Vogel", d="Kehrt zur seltsamen Krähe zurück."},
    [96931] = {n="Hoch oben auf dem Berg", d="Berührt das Krähenbildnis auf der Brücke über der Wiege der Ruhe, um die Wilde Göttin Jereman zu rufen."},
    [96939] = {n="Der Grat zwischen Leben und Tod", d="Sprecht mit dem wilden Gott, Marrosis."},
    [96957] = {n="Trautes Heim, Knochenbein", d="Sammelt 20 sonnengebleichte Knochen."},
    [96959] = {n="Die Lagerfeuer des Klingenmeisters", d="Zündet die beiden Lagerfeuer in Dae'gun an und kehrt zu Yashiro zurück."},
    [96964] = {n="Eine gerissene Kreatur", d="Sprecht mit dem wilden Gott Renalard."},
    [96971] = {n="Die Fabel von dem Fuchs und dem Dämon", d="Sammelt 8 zurückgelassene Ausrüstungsgegenstände."},
    [96978] = {n="Aggressives Wildbret", d="Sprecht mit dem wilden Gott Kala'th."},
