    [98042] = {n="Ein Blick in den Abgrund", d="Erbeutet ein unvergleichliches Auge von einem Jünger oder Schläger des Twilight-Hammers an der Meistergleve in Dunkelküste und findet in Auberdine jemanden, der bereit ist, es an sich zu nehmen.", tgo={{"Twilight-Jünger", "Twilight-Rohling"}}},
    [98046] = {n="Krone der Erde", d="Bringt das ausgelaugte Gefäß zu Lariia im Tempel des Mondes in Darnassus."},
    [98065] = {n="Krone der Erde", d="Bringt die Mondbrunnenüberreste zu Tyrande Whisperwind im Tempel des Mondes in Darnassus."},
    [98067] = {n="Die Augen der Schildwache", d="Stellt für Schildwache Dalia Sunblade im Tempel des Mondes von Darnassus Wächtereulen am Eingang zu den Tiefen der Burg Cenarius, der Bank von Darnassus, dem Gasthaus auf der Terrasse der Handwerker und am Stadttor auf.", tgo={{"Credit"}, {"Credit"}, {"Credit"}, {"Credit"}}},
    [98071] = {n="Brauerhandel", d="Liefert die Flaschen Fallrookrebenwein nach Dun Garok im südöstlichen Vorgebirge von Hillsbrad und bringt einen Sack ihres selbstgezogenen Hopfens zurück."},
    [98072] = {n="Krokis der Himmel", d="Sammelt 8 makellose Purpurschuppen und bringt sie zu James Halloran in den Hafen von Menethil.", tgo={{"Roter Welpe", "Verirrter Welpe", "Flammenschnaubender Welpe", "Purpurroter Welpe"}}},
